/* chinese/idioms/data/set3.js — 作者 C 的成語（catalog.js 第二欄 = 3 的那幾個）＋素養閱讀。照 set0.js 的寫法寫；規格 kids-member/docs/CHINESE_IDIOM_SPEC.md。
   成語照編號順序寫進 DATA_CY，素養閱讀寫進 DATA_CY_READ。每寫完一則跑：node test/chinese-idiom.test.js
   出處、人物、朝代、近反義已逐條對過教育部《成語典》（dict.idioms.moe.edu.tw）正文條目；故事、解說、例句、題目全部原創。 */
window.DATA_CY = (window.DATA_CY || []).concat([
  // ==================== L1 常用寓言 ====================
  {
    id: 'cy006', lv: 1, word: '對牛彈琴', zhuyin: 'ㄉㄨㄟˋ ㄋㄧㄡˊ ㄊㄢˊ ㄑㄧㄣˊ', src: '漢．牟融〈理惑論〉（《弘明集．卷一》）',
    quote: '公明儀為牛彈清角之操，伏食如故',
    facts: ['典源是漢．牟融〈理惑論〉，收在《弘明集．卷一》｜教育部《成語典》', '牟子舉春秋時魯國人公明儀替牛彈琴的事，說明講話要看對象｜教育部《成語典》典故說明', '公明儀改彈像蚊虻飛、小牛叫的聲音，牛才停下來聽｜〈理惑論〉', '《成語典》說明：牟子講這件事並沒有貶低牛的意思｜教育部《成語典》典故說明'],
    story: [
      '漢朝的時候，有一位讀書人，大家叫他牟子。他讀過很多儒家的書，後來又研究佛教的道理，常常有人來找他討論問題。',
      '有一天，一位客人不服氣的問他：「你說佛經像江海一樣深，文字像錦繡一樣美。那你為什麼不直接用佛經回答我，反而一直引用《詩經》、《尚書》這些書呢？」',
      '牟子笑了笑，說：「因為你讀過《詩經》、《尚書》，卻沒讀過佛經。我如果用你沒聽過的話來說，你一定聽不懂。所以我要用你熟悉的書，來說明新的道理。」接著，他講了一個故事。',
      '從前，魯國有一位很會彈琴的人，叫做公明儀。有一天，他看見一頭牛在草地上低頭吃草，心想：「我來彈一首最高雅的曲子給牠聽吧！」他坐下來，認真的彈起一首叫〈清角〉的名曲，琴聲又清亮又好聽。',
      '可是，那頭牛連頭都沒抬，還是一口一口的吃草，好像什麼都沒聽見。',
      '公明儀想了想，換了一種彈法。他用琴模仿蚊子、牛虻嗡嗡飛的聲音，又模仿小牛找媽媽時「哞——哞——」的叫聲。這一次，牛馬上停止吃草，甩甩尾巴、豎起耳朵，踏著小碎步，專心的聽了起來。',
      '牟子說：「牛不是聽不見，而是那首曲子不合牠的耳朵。」他講這個故事，並不是在笑牛笨，而是想說明：說話以前，要先想想對方聽不聽得懂。',
      '後來，「對牛彈琴」就用來比喻講話、做事不看對象，也用來比喻對不懂道理的人講道理，白費力氣。'
    ],
    mean: '對著牛彈琴，牛卻聽不懂。比喻講話、做事不看對象；也比喻對不懂道理的人講道理，白費力氣。',
    usage: ['用在說話、做事沒有考慮對方聽不聽得懂，方法用錯了的時候。', '也可以用在對聽不進道理的人講道理、白費唇舌的時候。這個說法帶有嘲笑的意思，不要拿來當面說別人，以免傷人。', '只是對方沒聽到、說話太小聲，不能用對牛彈琴；重點是說的內容不合對方。'],
    misuse: ['「全班都很喜歡聽老師講故事，老師說得真是對牛彈琴。」✗　大家聽得懂又喜歡，就不是對牛彈琴。'],
    eg: ['跟剛上一年級的弟弟講分數的除法，簡直是對牛彈琴，他只想知道點心什麼時候發。', '介紹科展作品時，要用同學聽得懂的話，不然滿口專有名詞，就像對牛彈琴。'],
    syn: ['語不擇人'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '公明儀第一次彈〈清角〉時，牛有什麼反應？', opts: ['還是低頭吃牠的草', '停下來豎起耳朵聽', '嚇得跑到遠處躲起來', '跟著琴聲哞哞的叫'], a: 0, why: '第五段：牛「連頭都沒抬，還是一口一口的吃草」。牛停下來聽，是公明儀換了彈法以後（第六段）。' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '公明儀換了彈法以後，牛為什麼開始聽了？', opts: ['琴聲變成牛熟悉的聲音', '琴聲變得比較大聲了', '牛已經把草吃飽了', '公明儀換了一把新琴'], a: 0, why: '第六段：他模仿蚊虻飛和小牛叫的聲音，都是牛熟悉的聲音。第七段牟子也說，牛不是聽不見，是原來的曲子不合牠的耳朵。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '牟子講公明儀的故事，是要回答客人的哪一個問題？', opts: ['為什麼要用客人熟悉的書來說明', '為什麼牛聽不懂那麼高雅的音樂', '為什麼公明儀要彈琴給牛聽', '佛經的文字為什麼寫得特別美'], a: 0, why: '第二段客人問他為什麼不直接用佛經；第三段牟子說要用客人熟悉的書，對方才聽得懂，接著用公明儀的故事來說明這個道理。' },
      { id: 'r4', p: 4, d: 3, type: 'open', q: '有人說：「牛聽不懂，是牛太笨。」也有人說：「是彈琴的人沒選對曲子。」你比較同意哪一種說法？請用故事裡的內容說明理由。',
        ref: '我比較同意是彈琴的人沒選對曲子。因為公明儀換成蚊虻飛和小牛叫的聲音以後，牛馬上就停下來聽了，可見牛不是聽不見，而是原來的曲子不合牠的耳朵。說話的人應該先想想對方懂什麼。',
        rubric: ['選出一種說法並表明立場', '用故事內容當證據（例如換了彈法後牛就聽了）', '說出說話、做事要看對象的道理'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「對牛彈琴」最主要是在說什麼？', opts: ['講話不看對象，對方聽不懂', '牛很喜歡聽好聽的音樂', '彈琴的人技術非常厲害', '在戶外練習彈琴比較好'], a: 0, why: '對牛彈琴比喻講話、做事不看對象，或對不懂道理的人講道理。重點不在牛，也不在琴藝。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '自然課分組報告時，小哲一上台就說了一大串「葉綠體」「二氧化碳濃度」，還念了好幾個英文名詞。他講得很認真，可是台下的同學都聽得一頭霧水，有人甚至開始打瞌睡。下課後老師提醒他：「下次換成大家聽得懂的說法，效果會更好。」', q: '小哲這次報告的情形，最適合用哪個成語形容？', opts: ['對牛彈琴', '濫竽充數', '畫蛇添足', '守株待兔'], a: 0, why: '小哲說的內容不合同學的程度，大家聽不懂，像對牛彈琴。濫竽充數是沒本事混在裡面；畫蛇添足是多做不必要的事；守株待兔是只等好運。小哲很認真準備，問題在說法不合聽的人。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈日記〉今天音樂課，老師彈了一首我們最喜歡的卡通主題曲，全班一邊聽一邊跟著唱，還有人跳起舞來。老師彈得真是對牛彈琴，大家都好開心！', q: '日記裡的「對牛彈琴」用得恰當。', a: false, why: '全班都聽得懂、還跟著唱，老師彈的曲子很合大家，不是對牛彈琴。對牛彈琴是說的內容不合對方、對方聽不懂。' },
      { id: 'p4', k: 'fill', d: 2, type: 'mc', q: '妹妹才三歲，你卻一直用英文跟她講恐龍的學名，她當然聽不懂，這不就是＿＿＿＿嗎？', opts: ['對牛彈琴', '刻舟求劍', '望梅止渴', '黔驢技窮'], a: 0, why: '說的內容不合三歲妹妹的程度，是對牛彈琴。刻舟求劍是不知變通，望梅止渴是用空想安慰自己，黔驢技窮是本事用完了，放進句子都不通。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '公明儀換一種彈法，牛就願意聽了。想一想：你要向家人或同學說明一件事（例如推薦一本書、教一個遊戲規則）時，怎麼做才不會「對牛彈琴」？',
        ref: '我想教阿公玩手機上的拼圖遊戲。我不會一直講「點兩下」「滑動」這些詞，而是先拿一盒真的拼圖給他看，說「這個就跟拼圖一樣」，再一步一步示範，讓他自己試一次。',
        rubric: ['說出一件要向別人說明的事', '說出怎麼依照對方懂的東西來調整說法', '做法具體、合理'] }
    ],
    xq: [
      { id: 'x1', k: 'judge', d: 1, type: 'tf', q: '「我跟只想玩積木的表弟講了半天的下棋規則，他一句也沒聽進去，真像對牛彈琴。」這句話的「對牛彈琴」用得恰當。', a: true, why: '表弟只想玩積木，對下棋規則聽不進去，說的人沒看對象，用對牛彈琴恰當。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '學校請一位科學家來演講，介紹天上的星星。他放了好多算式和圖表，講的是大學生才懂的內容。台下坐的卻是一到三年級的小朋友，大家一直扭來扭去、東張西望。演講結束後，一年級的小朋友問老師：「他剛剛到底在說什麼呀？」', q: '這場演講的情形像哪一個成語？', opts: ['對牛彈琴', '門庭若市', '磨杵成針', '買櫝還珠'], a: 0, why: '演講內容不合小朋友的程度，大家聽不懂，是講話不看對象的對牛彈琴。門庭若市是上門的人多，磨杵成針是有恆心，買櫝還珠是取捨不當。' }
    ]
  },
  {
    id: 'cy009', lv: 1, word: '刻舟求劍', zhuyin: 'ㄎㄜˋ ㄓㄡ ㄑㄧㄡˊ ㄐㄧㄢˋ', src: '《呂氏春秋．慎大覽．察今》',
    quote: '舟已行矣，而劍不行',
    facts: ['典源是《呂氏春秋．慎大覽．察今》，主角是戰國時代的楚國人｜教育部《成語典》', '《呂氏春秋》是秦國丞相呂不韋召集門客編寫的書｜教育部《成語典》典故說明', '書中用這個故事說明：治理國家要配合時代改變，不能死守舊的法令｜教育部《成語典》典故說明'],
    story: [
      '戰國時代，楚國有一個人要搭船渡過一條大江。他身上帶著一把很珍貴的寶劍，一路上都小心的抱著。',
      '船開到江中間，風浪大了起來，船身搖搖晃晃。楚國人一個不小心，手一鬆，「撲通」一聲，寶劍從船邊掉進水裡，一下子就沉下去，看不見了。',
      '船上的人都替他著急：「快想辦法啊！」沒想到楚國人一點也不慌。他拿出一把小刀，在劍掉下去的船邊刻了一個記號，得意的說：「我的劍是從這裡掉下去的，等一下照著記號去找就好了。」',
      '船繼續往前開，過了好一會兒，終於靠岸停了下來。楚國人立刻脫下外衣，從刻著記號的地方跳下水，在水底東摸西找。他找了好久好久，連劍的影子都沒看到。',
      '他爬上船，又看了看記號，滿臉疑惑：「奇怪，明明是從這裡掉下去的呀！」岸邊的人看了，都忍不住搖頭。',
      '劍掉下去以後，就一直躺在江中間的水底；船卻已經往前開了很遠。船邊的記號跟著船走，劍可不會跟著船走。照著記號去找，怎麼可能找得到呢？',
      '《呂氏春秋》說完這個故事，接著說：治理國家也是一樣。時代一直在改變，如果還死守古時候的法令，不知道跟著調整，就跟這個在船上刻記號找劍的人一樣糊塗。',
      '後來，「刻舟求劍」就用來比喻拘泥固執、不知道變通的人。'
    ],
    mean: '在船邊刻記號，想照著記號找回掉進水裡的劍。比喻做事死板、拘泥固執，不知道情況已經改變，要跟著變通。',
    usage: ['用在「情況已經變了，還照老方法做」的時候，是批評的意思（貶義）。', '近義成語有「守株待兔」「膠柱鼓瑟」；反義成語有「隨機應變」「因時制宜」。', '如果情況沒有改變，照著原本的方法做是對的，就不能說刻舟求劍。'],
    misuse: [],
    eg: ['學校的上課時間改了，弟弟還照著去年的課表帶課本，真是刻舟求劍。', '球隊換了新的對手，教練卻還用上次的戰術，未免有點刻舟求劍。'],
    syn: ['守株待兔', '膠柱鼓瑟', '食古不化'], ant: ['隨機應變', '因時制宜', '通權達變'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '寶劍掉進水裡以後，楚國人馬上做了什麼？', opts: ['在船邊刻一個記號', '立刻跳下水去找', '請船夫把船停下來', '大聲喊人來幫忙'], a: 0, why: '第三段：他「拿出一把小刀，在劍掉下去的船邊刻了一個記號」。他是等船靠岸以後才跳下水。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '楚國人從記號的地方跳下水，最後找到了寶劍。', a: false, why: '第四段：他找了好久好久，「連劍的影子都沒看到」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '楚國人為什麼找不到寶劍？', opts: ['船開走了，劍還在原來的水底', '記號刻得太小，他找錯地方', '寶劍被江裡的魚叼走了', '他下水太久，累得找不動'], a: 0, why: '第六段：劍一直躺在江中間的水底，船卻已經往前開了很遠，記號跟著船走，劍不會跟著船走。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '《呂氏春秋》把楚國人的做法，拿來比喻哪一種治理國家的方式？', opts: ['時代改變了，還死守舊法令', '國家的寶物沒有好好保管', '當官的人搭船時不夠小心', '遇到困難就馬上放棄不管'], a: 0, why: '第七段：時代一直在改變，還死守古時候的法令，就跟刻記號找劍的人一樣糊塗。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '如果你是船上的人，看到楚國人在船邊刻記號，你會怎麼提醒他？請用故事裡發生的事說明理由，並說出你覺得比較好的找劍方法。',
        ref: '我會跟他說：「船會一直往前開，劍卻留在掉下去的地方，記號跟著船走，等船停下來就對不上了。」比較好的方法是請船夫先把船停住，或記住劍掉在哪一棵樹、哪一塊大石頭的對面，再回來找。',
        rubric: ['說出具體的提醒', '用故事內容說明為什麼記號沒用（船在動、劍不動）', '提出一個合理的找劍方法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「刻舟求劍」的「舟」是什麼意思？', opts: ['船', '劍', '刀', '江'], a: 0, why: '「舟」就是船。「刻舟」是在船上刻記號，「求劍」是尋找寶劍。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '學校旁邊的書店上個月搬到了兩條街外的新大樓，門口還貼了搬家公告。小凱今天要買美勞用的色紙，卻照著以前的路線走到原本的地址。他看著空蕩蕩的店面，在門口等了半個小時，嘴裡還說：「我以前都在這裡買，一定是今天還沒開門。」', q: '小凱的做法，最適合用哪個成語形容？', opts: ['刻舟求劍', '對牛彈琴', '濫竽充數', '望梅止渴'], a: 0, why: '書店已經搬家（情況變了），小凱還照舊路線去、不肯相信，就是刻舟求劍。對牛彈琴是講話不看對象，濫竽充數是沒本事湊數，望梅止渴是用空想安慰自己。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈班會紀錄〉今年的校慶園遊會，攤位規則和去年一模一樣。總務股長照著去年的經驗，提早一週準備好桌椅和海報。有同學說：「股長這是刻舟求劍。」', q: '這位同學說「刻舟求劍」，恰當嗎？', opts: ['不恰當，規則沒變，照經驗做是對的', '恰當，因為股長照著去年的方法做', '恰當，因為股長提早一週就準備', '不恰當，因為園遊會跟船沒有關係'], a: 0, why: '刻舟求劍是情況變了還照舊做。今年規則和去年一樣，照經驗準備是聰明的做法，不是刻舟求劍。成語是比喻，跟有沒有船無關。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '這些成語跟「刻舟求劍」是什麼關係？配起來。', pairs: [['守株待兔', '近義成語'], ['隨機應變', '反義成語'], ['買櫝還珠', '意思無關']], why: '守株待兔也是死守老辦法；隨機應變是看情況改變做法，剛好相反；買櫝還珠是取捨不當，跟變不變通無關。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '楚國人沒有發現「船一直在動」。在你的生活中，有沒有「情況已經改變，做法卻沒跟著改」的例子（例如長高了、換了老師、規則改了）？你可以怎麼調整？',
        ref: '我升上五年級以後，數學作業變難了，我還是像以前一樣晚上九點才開始寫，常常寫到很晚。情況已經變了，我應該改成放學回家先寫數學，再做別的事。',
        rubric: ['舉出一個情況改變的生活例子', '指出原本的做法哪裡跟不上改變', '提出具體的調整做法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '公車路線已經改了，你還在舊的站牌等車，這不是＿＿＿＿嗎？', opts: ['刻舟求劍', '對牛彈琴', '磨杵成針', '門庭若市'], a: 0, why: '路線改了還在舊站牌等，是不知道跟著情況變通，用刻舟求劍。其他三個放進句子都說不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '小芳：「去年的跳繩比賽規定跳一分鐘，今年改成跳兩分鐘了。」\n小玉：「那我們練習也要改成兩分鐘，不能刻舟求劍，還照去年的方法練。」', q: '小玉說的「刻舟求劍」用得恰當。', a: true, why: '比賽規定改了，練習方法也要跟著改；小玉提醒不要照舊，用刻舟求劍說明不知變通的錯，很恰當。' }
    ]
  },
  {
    id: 'cy012', lv: 1, word: '濫竽充數', zhuyin: 'ㄌㄢˋ ㄩˊ ㄔㄨㄥ ㄕㄨˋ', src: '《韓非子．內儲說上》',
    quote: '齊宣王使人吹竽，必三百人',
    facts: ['典源是《韓非子．內儲說上》，人物是戰國時代齊國的齊宣王、齊湣王和南郭先生｜教育部《成語典》', '「竽」是古代一種吹奏樂器，讀ㄩˊ，不能寫成「芋」｜教育部《成語典》辨析', '這個成語也可以用來謙虛的說自己才能不夠｜教育部《成語典》用法說明'],
    story: [
      '戰國時代，齊國的國王齊宣王很喜歡聽一種叫「竽」的樂器。竽是用好幾根竹管做成的，吹起來聲音又低又厚。',
      '齊宣王有一個特別的習慣：他不喜歡聽一個人吹，最愛聽一大群人一起合奏。所以，每次要聽竽，一定要叫三百個樂工一起吹，聲音大得整座宮殿都嗡嗡作響。',
      '有一位南郭先生聽說了這件事，心裡打起了算盤。其實他根本不會吹竽，可是他想：「三百個人一起吹，誰會發現多了一個不會吹的人呢？」於是他跑去求見齊宣王，說自己很會吹竽。齊宣王很高興，就讓他加入樂隊，每天還發給他跟其他樂工一樣多的糧食。',
      '從那天起，南郭先生每天都跟著大家坐在樂隊裡。別人鼓起腮幫子吹，他也鼓起腮幫子；別人搖頭晃腦，他也搖頭晃腦，裝得好像很陶醉。三百支竽一起響，果然沒有人發現他根本沒吹出聲音。',
      '好日子過了好幾年。後來齊宣王過世了，他的兒子齊湣王當上國王。湣王也喜歡聽竽，可是他的習慣跟父親不一樣：他喜歡讓樂工一個一個輪流吹給他聽。',
      '消息一傳出來，南郭先生嚇壞了。輪到自己的時候，一吹就會露出馬腳啊！他越想越害怕，還沒輪到他，就偷偷收拾行李，逃出了王宮。',
      '後來，人們就用「濫竽充數」比喻沒有真本事的人混在行家裡湊數，也用來比喻拿不好的東西充場面。有時候，人們也會謙虛的說自己是「濫竽充數」，意思是自己的能力還不夠好。'
    ],
    mean: '不會吹竽的人混在樂隊裡湊數。比喻沒有真本事的人混在行家裡充數；也比喻拿不好的東西充場面；也可以用來謙虛的說自己能力不足。',
    usage: ['用在批評沒有真才實學、混在裡面湊人數的人，或品質不好卻拿來充場面的東西（貶義）。', '說自己時可以當謙虛的話，例如：「我只是濫竽充數，請大家多指教。」', '和「魚目混珠」都有想矇混過關的意思；濫竽充數側重「拿差的湊數」，魚目混珠側重「拿假的冒充真的」。'],
    misuse: ['「他在合唱團裡只會張嘴不出聲，根本是濫芋充數。」✗　「竽」是古代的樂器，不能寫成芋頭的「芋」，應該寫「濫竽充數」。'],
    eg: ['小明根本不會跳舞，卻躲在舞蹈隊最後一排濫竽充數，跳錯了也沒人發現。', '我的歌喉普通，這次能參加合唱團，只是濫竽充數而已。'],
    syn: ['魚目混珠', '備位充數'], ant: ['名副其實', '貨真價實'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '齊宣王聽竽有什麼習慣？', opts: ['一定要三百個人一起合奏', '喜歡一個一個輪流吹', '只在晚上睡覺前聽', '只聽南郭先生一個人吹'], a: 0, why: '第二段：每次要聽竽，「一定要叫三百個樂工一起吹」。一個一個輪流吹是湣王的習慣。' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '南郭先生為什麼敢加入齊宣王的樂隊？', opts: ['三百人一起吹，沒人聽得出來', '他偷偷練了很久，已經學會了', '齊宣王答應他可以不用吹', '他是樂隊隊長的好朋友'], a: 0, why: '第三段他想：「三百個人一起吹，誰會發現多了一個不會吹的人呢？」他是想混在人群裡。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '南郭先生在兩位國王的時候，結果為什麼不一樣？', opts: ['合奏能混過去，獨奏就藏不住', '湣王比宣王更喜歡聽竽了', '南郭先生後來生了一場病', '湣王給樂工的糧食變少了'], a: 0, why: '把第二段和第五段對照：宣王愛聽合奏，他能混在三百人裡；湣王要一個一個聽，他不會吹就藏不住，只好逃走。' },
      { id: 'r4', p: 4, d: 3, type: 'open', q: '南郭先生混了好幾年都沒被發現，最後還是逃走了。你覺得他這樣「混」，到底是賺到了還是虧到了？請用故事內容說明你的看法。',
        ref: '我覺得他虧到了。雖然他白白領了好幾年的糧食，可是他每天都要假裝、怕被發現，最後還是得偷偷逃走。如果他把那幾年拿來真的學吹竽，湣王要一個一個聽的時候，他就不用怕了。',
        rubric: ['表明自己的看法（賺到或虧到）', '用故事內容當理由（每天假裝、最後逃走）', '想到「真的學會本事」才是長久的辦法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「濫竽充數」的「竽」是什麼？', opts: ['古代一種吹奏的樂器', '一種可以吃的根莖', '古代用來打仗的武器', '國王坐的大椅子'], a: 0, why: '「竽」是古代用竹管做成的吹奏樂器，讀ㄩˊ。可以吃的根莖是「芋」，字不一樣。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '五年一班要組一支二十人的跳繩隊參加比賽。阿宏其實不太會跳，可是他想跟好朋友在一起，就趁報名時混進隊伍裡。練習時，他總是站在最後一排，輪到他跳就假裝綁鞋帶。後來老師改成每個人單獨跳給她看，阿宏一下子就被發現了。', q: '阿宏的做法，最適合用哪個成語形容？', opts: ['濫竽充數', '刻舟求劍', '對牛彈琴', '望梅止渴'], a: 0, why: '阿宏不會跳卻混在隊伍裡湊人數，單獨檢查就露餡，跟南郭先生一樣，是濫竽充數。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈校刊〉本屆書法比賽，小華的作品筆畫有力、結構工整，評審一致給他第一名。記者寫道：「小華的作品濫竽充數，令人佩服。」', q: '記者用「濫竽充數」恰當嗎？', opts: ['不恰當，作品很好，不是湊數的', '恰當，因為小華拿到了第一名', '恰當，因為比賽裡有很多件作品', '不恰當，因為書法比賽沒有吹竽'], a: 0, why: '濫竽充數是批評沒本事、拿差的湊數。小華的作品得第一名，應該稱讚，不能用濫竽充數。成語是比喻，跟有沒有吹竽無關。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '下面哪一個成語，意思和「濫竽充數」相反？', opts: ['名副其實', '魚目混珠', '備位充數', '對牛彈琴'], a: 0, why: '名副其實是名稱和實際相符，真有本事，和濫竽充數相反。魚目混珠、備位充數是近義。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '南郭先生用「假裝」混過去，最後還是被發現。在學校分組合作時，如果你對某件工作不太會，可以怎麼做，才不會變成「濫竽充數」？',
        ref: '如果分組做海報，我不太會畫圖，我會先跟組員說清楚，請會畫的同學教我簡單的部分，或改做我比較會的事，例如查資料、寫文字。這樣我是真的有出力，不是假裝在做。',
        rubric: ['承認自己不會的地方', '提出學習或分工的具體做法', '說明這樣做和「假裝混過去」有什麼不同'] }
    ],
    xq: [
      { id: 'x1', k: 'judge', d: 1, type: 'tf', q: '「這盒禮盒裡的水果大多碰傷了，店家還塞了幾顆快爛掉的來濫竽充數。」這句話的「濫竽充數」用得恰當。', a: true, why: '拿不好的東西充場面，也是濫竽充數的意思，用得恰當。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '社區合唱團要參加比賽，團員有四十人。鄰居阿德其實不太會唱歌，但他喜歡大家一起熱鬧，所以每次上台都站在最後一排，只張嘴不出聲。比賽前一週，指揮決定每個人都要單獨唱一段給她聽，阿德緊張得連著幾天都找藉口請假。', q: '阿德的做法像哪一個成語？', opts: ['濫竽充數', '黔驢技窮', '南轅北轍', '一字千金'], a: 0, why: '阿德不會唱卻混在團裡湊數，要單獨唱就躲起來，和南郭先生一樣是濫竽充數。黔驢技窮是本事用完了，南轅北轍是方向和目標相反，一字千金是稱讚文章好。' }
    ]
  },
  {
    id: 'cy015', lv: 1, word: '望梅止渴', zhuyin: 'ㄨㄤˋ ㄇㄟˊ ㄓˇ ㄎㄜˇ', src: '南朝宋．劉義慶《世說新語．假譎》',
    quote: '前有大梅林，饒子，甘酸，可以解渴',
    facts: ['典源是南朝宋．劉義慶《世說新語．假譎》，主角是東漢末年的曹操（書中稱「魏武」）｜教育部《成語典》', '《成語典》典故說明：曹操率軍討伐張繡，路上天氣炎熱又找不到水源｜教育部《成語典》典故說明', '後用「望梅止渴」比喻用空想來安慰自己｜教育部《成語典》釋義', '「渴」是口乾想喝水，不能寫成「喝」｜教育部《成語典》辨析'],
    story: [
      '東漢末年，天下很亂，各地的將領互相爭戰。有一年，曹操帶著大軍出發，要去攻打一位叫張繡的將領。',
      '那天太陽像火球一樣掛在天上，士兵們穿著厚重的盔甲，扛著武器，在塵土飛揚的路上走了好久。更糟的是，他們找不到可以取水的地方，每個人的水壺都空了。',
      '士兵們渴得嘴唇乾裂，喉嚨像要冒煙，腳步越來越慢，有人甚至走不動，坐在路邊不肯起來。照這樣下去，軍隊根本沒辦法繼續前進。',
      '曹操騎在馬上，看著大家無精打采的樣子，心裡很著急。附近明明沒有水，該怎麼辦呢？他想了一想，忽然舉起馬鞭往前一指，大聲喊：「大家撐著點！前面有一大片梅林，樹上結滿了梅子，又酸又甜，吃了就不渴了！」',
      '士兵們一聽到「梅子」，腦中立刻浮現酸溜溜的梅子，嘴巴裡不知不覺流出了口水，乾乾的喉嚨好像也舒服了一點。大家精神一振，又打起精神往前走。',
      '其實前面根本沒有梅林。但是靠著這股力氣，軍隊撐到了更遠的地方，終於找到了水源。',
      '後來，「望梅止渴」就用來比喻用空想來安慰自己。梅子並沒有真的出現，口渴的問題也不是梅子解決的；那一刻讓人好過一點的，只是心裡的想像而已。'
    ],
    mean: '想到梅子的酸味，流出口水，暫時不覺得渴。比喻用空想或還不能實現的希望來安慰自己。',
    usage: ['用在「事情沒有真的解決，只是用想像讓自己好過一點」的時候。', '和「畫餅充飢」意思相近。如果真的得到了想要的東西，就不能說望梅止渴。', '「渴」是口乾想喝水，不能寫成「喝」。'],
    misuse: ['「零用錢不夠買新球鞋，他只好每天看著球鞋的照片望梅止喝。」✗　「渴」是口乾想喝水，不能寫成「喝」，應該寫「望梅止渴」。'],
    eg: ['零用錢不夠買新的模型，弟弟只好每天翻著模型目錄，望梅止渴。', '颱風天不能出門，我們只能看著遊樂園的照片望梅止渴。'],
    syn: ['畫餅充飢'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '士兵們為什麼會渴得走不動？', opts: ['天氣熱，又找不到水喝', '吃了太多酸酸的梅子', '一直大聲唱歌喊口號', '跑步比賽跑得太累'], a: 0, why: '第二段：太陽像火球一樣，又「找不到可以取水的地方，每個人的水壺都空了」。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '前面真的有一大片結滿梅子的梅林。', a: false, why: '第六段：「其實前面根本沒有梅林。」' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '曹操說前面有梅林，最主要的目的是什麼？', opts: ['讓士兵打起精神繼續走', '讓士兵去摘梅子帶回家', '想考考士兵認不認得梅樹', '想把軍隊帶到梅林休息'], a: 0, why: '第三、四段：士兵走不動、軍隊沒辦法前進，曹操才喊出梅林，讓大家精神一振，繼續往前走。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '最後一段說，那一刻讓人好過一點的是什麼？', opts: ['心裡對梅子的想像', '真的吃到的梅子', '曹操給的一壺水', '路邊的一條小河'], a: 0, why: '最後一段：梅子並沒有出現，「讓人好過一點的，只是心裡的想像而已」。這也是成語「用空想安慰自己」的由來。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '曹操用說假話的方法讓士兵繼續前進，最後找到了水。你覺得他這樣做好不好？如果你是曹操，還有沒有別的辦法？',
        ref: '我覺得在那時候是有用的，因為大家真的走不動了，曹操的話讓士兵有力氣撐到水源。可是如果常常這樣騙人，大家以後就不相信他了。如果我是曹操，我可能會派幾個體力好的士兵先去前面找水，再告訴大家「水快到了」。',
        rubric: ['說出自己對曹操做法的看法', '用故事內容當理由', '想出另一個合理的辦法，或指出說假話的缺點'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「望梅止渴」比喻什麼？', opts: ['用空想來安慰自己', '口渴就要多吃梅子', '要找到水源才能解渴', '種梅樹可以賺大錢'], a: 0, why: '望梅止渴是想著梅子而暫時不渴，比喻用空想安慰自己，不是真的教人吃梅子。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '暑假全家原本要去日本玩，因為爸爸工作太忙，只好取消。小琪很失望，每天晚上都打開電腦，看別人拍的日本旅遊影片，一邊看一邊想像自己正在吃章魚燒、看楓葉。她說：「看一看，心情就好多了，好像自己也去過了。」', q: '小琪的做法，最適合用哪個成語形容？', opts: ['望梅止渴', '刻舟求劍', '濫竽充數', '破釜沉舟'], a: 0, why: '小琪去不成日本，只能看影片、想像自己去過，用想像安慰自己，就是望梅止渴。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈日記〉今天體育課跑完八百公尺，我渴得要命。下課鈴一響，我馬上衝到飲水機，一口氣喝了兩大杯水，終於望梅止渴，舒服多了。', q: '日記裡的「望梅止渴」用得恰當嗎？', opts: ['不恰當，他真的喝到水了', '恰當，因為他跑完步很口渴', '恰當，因為他喝完水就不渴了', '不恰當，因為他喝的不是梅汁'], a: 0, why: '望梅止渴是「沒有真的解決，只靠想像」。他真的喝了兩杯水，問題已經解決，不能用望梅止渴。' },
      { id: 'p4', k: 'fill', d: 2, type: 'mc', q: '這個月零用錢花光了，我只能站在文具店櫥窗前看著那盒彩色筆，＿＿＿＿一下。', opts: ['望梅止渴', '南轅北轍', '黔驢技窮', '刻舟求劍'], a: 0, why: '買不到，只能看一看安慰自己，用望梅止渴。南轅北轍是方向和目標相反，黔驢技窮是本事用完，刻舟求劍是不知變通，放進句子都不通。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '「望梅止渴」能讓人暫時好過一點，可是問題還沒有真正解決。想一件你很想要、現在還得不到的東西或目標，除了「想一想」，你還可以怎麼做，讓它真的有機會實現？',
        ref: '我很想要一台天文望遠鏡，現在只能看網路上的星空照片。除了看照片，我可以每個月存一點零用錢，也可以先去圖書館借天文的書，學會怎麼找星座，等存夠錢就能真的買望遠鏡。',
        rubric: ['說出一個想要的東西或目標', '分清楚「只靠想像」和「真的去做」', '提出具體可行的行動'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '沒有錢買演唱會的門票，姊姊只能在房間裡聽著歌手的專輯＿＿＿＿。', opts: ['望梅止渴', '門庭若市', '對牛彈琴', '磨杵成針'], a: 0, why: '去不了演唱會，只能聽專輯安慰自己，用望梅止渴。其他三個放進句子都說不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '全班說好期末考後要去烤肉，可是那一天下了大雨，活動延期了。同學們很失望，班長就在黑板上畫了一大盤烤肉和玉米，還寫上「香噴噴」三個字。大家看著黑板上的圖，一邊說「好香喔」，一邊吞口水，心情好像也沒那麼糟了。', q: '同學們看著黑板的情形，最像哪一個成語？', opts: ['望梅止渴', '畫蛇添足', '濫竽充數', '指鹿為馬'], a: 0, why: '烤肉沒吃到，只靠看圖想像讓心情好一點，就是望梅止渴。畫蛇添足是多做不必要的事，濫竽充數是混在裡面湊數，指鹿為馬是故意顛倒是非。' }
    ]
  },
  {
    id: 'cy018', lv: 1, word: '南轅北轍', zhuyin: 'ㄋㄢˊ ㄩㄢˊ ㄅㄟˇ ㄔㄜˋ', src: '《戰國策．魏策四》',
    quote: '此數者愈善，而離楚愈遠耳',
    facts: ['典源是《戰國策．魏策四》，人物是戰國時代魏國的大臣季梁和魏王｜教育部《成語典》', '魏王想出兵攻打趙國的都城邯鄲，季梁在半路聽到消息，趕回來勸阻｜教育部《成語典》典故說明', '「轅」是大車前面套在牲口兩邊、用來拉車的木頭；「轍」是車輪壓過留下的痕跡｜教育部《成語典》釋義'],
    story: [
      '戰國時代，魏國的國王想派兵去攻打趙國的都城邯鄲，好讓魏國變得更強大。',
      '大臣季梁那時正出門在外，聽到這個消息，馬上掉頭趕回來。他衣服皺了沒整理，頭上的灰塵也來不及撣掉，就急急忙忙去見魏王。',
      '季梁說：「大王，我在回來的路上，遇到一件怪事。有一個人駕著馬車往北走，他告訴我：『我要去楚國。』我說：『楚國在南方，你怎麼往北走呢？』」',
      '「那個人說：『沒關係，我的馬跑得很快！』我說：『馬再快，這也不是去楚國的路啊！』他又說：『我帶的旅費很多！』我說：『錢再多，這也不是去楚國的路啊！』他還是說：『我的車夫很會駕車！』」',
      '季梁嘆了一口氣：「大王，這個人的馬越好、錢越多、車夫越厲害，他就離楚國越遠啊！」',
      '接著，季梁說出了真正想說的話：「大王想成為天下的霸主，讓各國都信服。可是您仗著國家大、軍隊強，去攻打邯鄲，想擴張土地、提高名聲，這樣做得越多，就離成為霸主越遠，就像那個想去楚國卻往北走的人一樣。」',
      '後來，這個故事就變成了「南轅北轍」：本來想往南走，車子卻往北駛。它比喻行動和想達到的目標正好相反；也可以比喻兩者背道而馳，或兩個地方相隔很遠。'
    ],
    mean: '想往南走，車子卻往北駛。比喻行動和想達到的目的相反；也比喻兩者背道而馳，或兩地相隔很遠。',
    usage: ['最常用在「做法和目標相反，越努力離目標越遠」的時候。', '也可以形容兩個人的想法、做法完全相反，例如：兩人的意見南轅北轍。', '只是走錯一小段路或速度太慢，不能用南轅北轍；重點是方向和目標相反。'],
    misuse: [],
    eg: ['想減肥卻天天吃宵夜，這樣的做法和目標南轅北轍。', '哥哥想去海邊，姊姊想去爬山，兩個人的計畫南轅北轍，只好請媽媽決定。'],
    syn: ['背道而馳'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '那個駕車往北走的人，要去哪裡？', opts: ['楚國', '趙國', '魏國', '齊國'], a: 0, why: '第三段：他說「我要去楚國」。楚國在南方，他卻往北走。' },
      { id: 'r2', p: 1, d: 1, type: 'order', q: '依照那個人說的先後順序，排出他自誇的三個「好條件」。', items: ['馬跑得很快', '帶的旅費很多', '車夫很會駕車'], why: '第四段：他先說馬跑得很快，再說旅費很多，最後說車夫很會駕車。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '季梁說「馬越好、錢越多，就離楚國越遠」，是什麼意思？', opts: ['方向錯了，條件越好走越遠', '馬跑太快會讓人摔下車', '錢太多容易被小偷盯上', '車夫其實根本不會駕車'], a: 0, why: '往北走是錯的方向，馬快、錢多、車夫好，只會讓他在錯的方向上走得更遠。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '季梁講這個故事，是把魏王比作誰？', opts: ['想去楚國卻往北走的人', '很會駕車的那位車夫', '在路上遇到他的季梁', '住在楚國的老百姓'], a: 0, why: '第六段：魏王想當霸主（目標）卻去攻打邯鄲（做法相反），就像想去楚國卻往北走的人。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '季梁沒有直接說「大王，您錯了」，而是先講路上遇到的事。你覺得他這樣勸，比直接說好嗎？請用故事內容說明理由。',
        ref: '我覺得比較好。因為直接說國王錯了，國王可能會生氣、不想聽；先講一件奇怪的事，魏王自己就會覺得往北走去楚國很好笑，再聽到季梁把故事跟攻打邯鄲連起來，比較容易想通。',
        rubric: ['表明覺得好或不好', '用故事內容說明理由', '說出這種勸人方法的效果'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「南轅北轍」的「轍」是什麼？', opts: ['車輪壓過留下的痕跡', '車子前面拉車的木頭', '駕車用的長馬鞭', '車上坐的位子'], a: 0, why: '「轍」是車輪壓過留下的痕跡；車子前面套牲口、拉車的木頭是「轅」。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小莉想存錢買一台新的腳踏車。她聽說「多去特價的店比較省錢」，就每天放學都去文具店逛特價區，看到便宜的東西就買。一個月過去，她買了一大堆用不到的貼紙和小玩具，存錢筒裡的錢反而越來越少，離腳踏車越來越遠。', q: '小莉的做法，最適合用哪個成語形容？', opts: ['南轅北轍', '刻舟求劍', '對牛彈琴', '濫竽充數'], a: 0, why: '小莉想存錢，卻天天買東西，做法和目標相反，越做離目標越遠，就是南轅北轍。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈日記〉今天去動物園，我和弟弟都想先看企鵝，就一起往企鵝館走。一路上我們南轅北轍，一下子就到了。', q: '日記裡的「南轅北轍」用得恰當。', a: false, why: '兩人目標一樣、方向也對，很快就到了，跟「方向和目標相反」完全不同，不能用南轅北轍。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '下面哪一個成語，意思和「南轅北轍」最接近？', opts: ['背道而馳', '一路順風', '並駕齊驅', '異曲同工'], a: 0, why: '背道而馳是朝相反的方向跑，和南轅北轍相近。並駕齊驅是並排前進、不分高下；異曲同工是做法不同但效果一樣。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '想一個你最近的目標（例如考試進步、存錢、跑得更快、交朋友），檢查看看：你現在的做法，是在往目標走，還是可能「南轅北轍」？如果方向不對，要怎麼調整？',
        ref: '我的目標是跑步變快，可是我每天放學都在家玩電動，幾乎沒有運動，這跟目標南轅北轍。我要改成每天放學先去操場跑兩圈，週末跟家人去河堤慢跑，電動等跑完再玩。',
        rubric: ['說出一個具體目標', '檢查現在的做法和目標方向是否一致', '提出朝向目標的調整'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '你想睡得好，卻在睡前一直滑手機，做法和目標根本＿＿＿＿。', opts: ['南轅北轍', '望梅止渴', '濫竽充數', '刻舟求劍'], a: 0, why: '想睡好卻做讓自己睡不好的事，做法和目標相反，用南轅北轍。其他三個放進句子都說不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '班上討論畢業旅行要去哪裡。阿哲希望去遊樂園玩刺激的設施，小芸卻想去博物館看展覽，兩個人在班會上各說各的理由，吵了半節課，誰也說服不了誰。班長只好說：「你們兩個的想法完全相反，我們用投票來決定吧。」', q: '阿哲和小芸的想法，可以用哪一個成語形容？', opts: ['南轅北轍', '對牛彈琴', '望梅止渴', '門可羅雀'], a: 0, why: '兩人的想法完全相反，用南轅北轍形容兩者背道而馳。對牛彈琴是講話不看對象，望梅止渴是用想像安慰自己，門可羅雀是冷清沒有客人。' }
    ]
  },
  {
    id: 'cy021', lv: 1, word: '黔驢技窮', zhuyin: 'ㄑㄧㄢˊ ㄌㄩˊ ㄐㄧˋ ㄑㄩㄥˊ', src: '唐．柳宗元〈三戒．黔之驢〉',
    quote: '虎因喜，計之曰：「技止此耳！」',
    facts: ['典源是唐．柳宗元〈三戒．黔之驢〉｜教育部《成語典》', '柳宗元是唐朝河東人，唐宋八大家之一，寫過不少寓言｜教育部《成語典》典故說明', '黔地（今貴州一帶）原本沒有驢，是有人用船載進去，後來放在山下｜教育部《成語典》典故說明', '《成語典》列的近義成語是「技止此耳」，反義成語是「神通廣大」｜教育部《成語典》辨識'],
    story: [
      '唐朝的文學家柳宗元寫過一則寓言。故事發生在黔這個地方，大約是現在的貴州一帶。那裡山很多，原本沒有驢子。',
      '有一天，一個喜歡新奇東西的人，用船載了一頭驢子進來。可是運到以後，他發現驢子在山裡派不上用場，就把牠放在山腳下，不管牠了。',
      '山裡的老虎從來沒見過驢子。牠看見這頭動物又高又大，心想：「這是什麼神奇的怪物？」嚇得躲在樹林裡，只敢偷偷的看。過了一陣子，老虎慢慢走出來靠近一點，還是不知道驢子到底有多厲害。',
      '有一天，驢子突然「呃啊——」大叫一聲。老虎嚇了一大跳，以為驢子要來咬牠，轉身就逃得遠遠的。',
      '可是，老虎每天來來回回的觀察，發現驢子好像也沒有別的本領。牠聽慣了驢子的叫聲，膽子越來越大，開始在驢子身邊繞來繞去，還故意用身體去碰牠、撞牠。',
      '驢子被惹火了，抬起後腿踢了老虎一腳。老虎反而高興起來，心想：「原來牠的本事，就只有這樣而已！」於是大吼一聲撲了上去，把驢子吃掉了。',
      '柳宗元感嘆：驢子的樣子高大，好像很有本領；叫聲宏亮，好像很有能力。如果牠一直不露出底細，老虎再兇也不敢動手。可惜牠把僅有的一點本事全用完了，才落得這樣的下場。',
      '後來，「黔驢技窮」就用來比喻有限的一點本事已經用完，再也想不出辦法了。'
    ],
    mean: '黔地的驢子把僅有的本事用完，就被老虎吃掉了。比喻有限的一點本事已經用盡，再也無計可施。',
    usage: ['用在「本來就沒什麼本事，用完了就沒招了」的情況，帶有批評或嘲笑的意思（貶義）。', '形容自己時可以帶點自嘲，例如：「能想的辦法都用完了，我真是黔驢技窮。」', '如果本事很大、辦法很多，要用反義的「神通廣大」。'],
    misuse: [],
    eg: ['弟弟想盡辦法賴床，裝肚子痛、裝頭暈都被識破，最後黔驢技窮，只好乖乖起床。', '對方球隊只會一招長傳，被我們看穿以後就黔驢技窮了。'],
    syn: ['技止此耳'], ant: ['神通廣大'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '驢子是怎麼來到黔這個地方的？', opts: ['有人用船把牠載進來', '牠自己從北方走過來', '老虎把牠從別處抓來', '黔地本來就有很多驢'], a: 0, why: '第二段：「一個喜歡新奇東西的人，用船載了一頭驢子進來。」第一段也說黔原本沒有驢子。' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '老虎一開始為什麼躲在樹林裡，不敢靠近驢子？', opts: ['沒見過驢子，以為牠很厲害', '驢子身邊有很多人在保護', '老虎那時候正在生病', '樹林裡有更好吃的東西'], a: 0, why: '第三段：老虎從來沒見過驢子，看牠又高又大，以為是「神奇的怪物」，不知道牠有多厲害。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '老虎為什麼後來敢撲向驢子？', opts: ['看出驢子只會叫和踢而已', '驢子先大叫想要攻擊老虎', '老虎找到幫忙的同伴了', '驢子已經餓得走不動了'], a: 0, why: '把第四到六段合起來：老虎聽慣了叫聲，又被踢了一腳，發現「牠的本事就只有這樣」，才敢撲上去。' },
      { id: 'r4', p: 4, d: 3, type: 'open', q: '柳宗元說，如果驢子一直不露出底細，老虎就不敢動手。你同意「把本事藏起來比較安全」這個看法嗎？還是覺得驢子真正的問題在別的地方？請說明理由。',
        ref: '我只同意一半。藏起來可以暫時騙過老虎，可是老虎每天都在觀察，早晚會發現。驢子真正的問題是牠本來就沒什麼本事，一被惹火就亂踢。如果牠有真本領，就不怕被看穿了。',
        rubric: ['表明同意、不同意或部分同意', '用故事內容當理由（老虎每天觀察、驢子只會叫和踢）', '提出自己認為的真正問題或更好的辦法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「黔驢技窮」的「技窮」是什麼意思？', opts: ['本事用完了', '技術很高明', '生活很窮困', '跑得很遠'], a: 0, why: '「技」是本事，「窮」是用盡。技窮就是本事用完了。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '班際躲避球比賽，二班的阿寶每次都用同一招：假裝往左丟，其實往右丟。第一局大家都被他騙了，二班一路領先。到了第二局，我們班摸清了他的招式，一看到他往左做假動作，就全部往右邊閃。阿寶想不出別的辦法，只好亂丟一通，二班最後輸了比賽。', q: '阿寶在第二局的情形，最適合用哪個成語形容？', opts: ['黔驢技窮', '南轅北轍', '望梅止渴', '門庭若市'], a: 0, why: '阿寶只會一招，被看穿以後就沒有別的辦法了，像黔地的驢子，是黔驢技窮。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈班級日記〉今天的魔術社表演，小安變了十幾種魔術，每一種都不一樣，觀眾一直拍手叫好，表演時間到了還欲罷不能。主持人說：「小安真是黔驢技窮！」', q: '主持人用「黔驢技窮」恰當嗎？', opts: ['不恰當，小安本事很多，不是沒招了', '恰當，因為小安把魔術都表演完了', '恰當，因為表演的時間已經到了', '不恰當，因為魔術表演裡沒有驢子'], a: 0, why: '黔驢技窮是本事少、用完就沒辦法。小安變了十幾種，觀眾還想看，是本事很多，不能用黔驢技窮。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '這些成語跟「黔驢技窮」是什麼關係？配起來。', pairs: [['技止此耳', '近義成語'], ['神通廣大', '反義成語'], ['磨杵成針', '意思無關']], why: '技止此耳就是老虎說的「本事只有這樣」，和黔驢技窮相近；神通廣大是本事很大，相反；磨杵成針是有恆心，無關。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '驢子只有一兩招，用完就沒辦法了。想一想，你在學習或比賽時，有沒有「只會一招」的情形？你可以怎麼多準備幾種方法？',
        ref: '我寫數學應用題時，只會用畫圖的方法，題目一變複雜就畫不出來。我可以多學列式子的方法，也可以試著把數字換小一點先算算看。這樣一種方法不行，我還有別的方法可以用。',
        rubric: ['說出一個「只會一招」的情形', '提出至少一種新的方法', '說明多準備方法有什麼好處'] }
    ],
    xq: [
      { id: 'x1', k: 'judge', d: 1, type: 'tf', q: '「他什麼藉口都用過了，老師一個也不相信，最後黔驢技窮，只好老實承認忘了寫功課。」這句話的「黔驢技窮」用得恰當。', a: true, why: '藉口都用完，再也想不出辦法，用黔驢技窮恰當。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '下棋社比賽時，小剛一開始用一個新學的陷阱吃掉了對手兩顆棋子，得意得不得了。可是對手很快就看穿了他的招式，再也不上當。小剛想來想去，再也想不出別的妙招，只能一步一步被對手逼到角落，最後輸了這盤棋。', q: '小剛後來的情形可以用哪個成語形容？', opts: ['黔驢技窮', '刻舟求劍', '買櫝還珠', '三顧茅廬'], a: 0, why: '小剛只有一招，被看穿後就沒有辦法了，是黔驢技窮。刻舟求劍是不知變通，買櫝還珠是取捨不當，三顧茅廬是誠心邀請人才。' }
    ]
  },
  {
    id: 'cy024', lv: 1, word: '買櫝還珠', zhuyin: 'ㄇㄞˇ ㄉㄨˊ ㄏㄨㄢˊ ㄓㄨ', src: '《韓非子．外儲說左上》',
    quote: '鄭人買其櫝而還其珠',
    facts: ['典源是《韓非子．外儲說左上》｜教育部《成語典》', '楚王問田鳩：墨子的話內容很好，為什麼文字不華麗？田鳩用楚人到鄭國賣珠的故事回答｜教育部《成語典》典故說明', '「櫝」是盒子，讀ㄉㄨˊ；後用來比喻捨本逐末、取捨失當｜教育部《成語典》釋義'],
    story: [
      '戰國時代，楚國的國王有一個疑問。他問一位叫田鳩的學者：「墨子是很有名的思想家，他說的道理都很好，可是他寫的文章，為什麼一點也不華麗、不好聽呢？」',
      '田鳩想了想，說：「我說一個故事給大王聽吧。」',
      '從前，有一個楚國人要到鄭國去賣珍珠。他想：「珍珠這麼珍貴，一定要用漂亮的盒子裝，才配得上它。」於是他用名貴的木蘭木做了一個盒子，用香料把盒子薰得香噴噴的，再鑲上珠子和玉石，最後貼上翠綠的羽毛，裝飾得閃閃發亮。',
      '到了鄭國，有一個人看到這個盒子，愛不釋手，拿在手上翻來覆去的欣賞，馬上就掏錢買了下來。可是，他打開盒子，把裡面的珍珠拿出來，還給了楚國人，只帶著空盒子高高興興的走了。',
      '田鳩說：「這個楚國人很會賣盒子，卻不會賣珍珠啊！」接著他解釋：現在很多人說話寫文章，只顧著把文字修飾得很漂亮，大家讀了只記得好聽的句子，反而忘了真正有用的道理。墨子要傳的是古代聖王的道理，他怕大家只欣賞美麗的文字，忽略了內容，所以故意寫得樸素一點。',
      '後來，人們用「買櫝還珠」比喻沒有眼光，只看重外表或次要的東西，反而丟掉最重要、最有價值的東西，也就是取捨不當。'
    ],
    mean: '買下裝珍珠的漂亮盒子，卻把珍珠退還。比喻只看重外表或次要的部分，丟掉真正有價值的東西（捨本逐末、取捨失當）。',
    usage: ['用在「選錯了重點：留下次要的，放掉最重要的」的情況（貶義）。', '近義成語是「捨本逐末」。', '只是「包裝很漂亮」不能用買櫝還珠；要有「因為看重外表而丟掉真正有價值的東西」才對。'],
    misuse: [],
    eg: ['弟弟買零食只是為了收集包裝裡的貼紙，餅乾都沒吃就丟了，簡直是買櫝還珠。', '參觀博物館只顧著在門口拍照打卡，卻沒進去看展覽，這不是買櫝還珠嗎？'],
    syn: ['捨本逐末'], ant: ['取精用宏'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '鄭國人最後帶走了什麼？', opts: ['空的盒子', '一顆珍珠', '珍珠和盒子', '什麼都沒帶'], a: 0, why: '第四段：他把珍珠還給楚國人，「只帶著空盒子高高興興的走了」。' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '田鳩說楚國人「很會賣盒子，卻不會賣珍珠」，意思是什麼？', opts: ['盒子太漂亮，讓人忽略了珍珠', '楚國人做盒子的手藝很差', '那顆珍珠的品質其實不好', '鄭國人身上沒有帶夠錢'], a: 0, why: '盒子裝飾得太華麗，鄭國人只看上盒子，真正值錢的珍珠反而被退回來。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '把田鳩的故事和墨子對照，「珍珠」和「盒子」分別比喻什麼？', opts: ['珍珠是道理，盒子是華麗的文字', '珍珠是華麗的文字，盒子是道理', '珍珠是楚王，盒子是墨子的學生', '珍珠是錢，盒子是商人'], a: 0, why: '第五段：墨子要傳的是道理（珍珠），怕大家只欣賞美麗的文字（盒子）而忽略內容。' },
      { id: 'r4', p: 4, d: 3, type: 'open', q: '墨子為了怕大家忽略內容，故意把文章寫得樸素。你覺得文章「內容好」和「文字美」哪一個比較重要？有沒有可能兩個都兼顧？請用故事和自己的經驗說明。',
        ref: '我覺得內容比較重要，因為鄭國人只看盒子，最後錯過了真正值錢的珍珠。不過我覺得兩個可以兼顧，像我寫作文時，先把想說的事情想清楚，再用比較生動的句子寫出來，讀的人不會只記得漂亮的句子，也看得懂我的意思。',
        rubric: ['說出自己認為哪一個比較重要', '用故事內容當理由', '說出兼顧的可能或方法，並連結自己的經驗'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「買櫝還珠」的「櫝」是什麼意思？', opts: ['盒子', '珍珠', '錢幣', '商店'], a: 0, why: '「櫝」讀ㄉㄨˊ，是盒子。買櫝還珠就是買了盒子、還了珍珠。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '阿姨送給小宇一本很厚的恐龍百科全書，書外面還附了一個會發光的恐龍造型書套。小宇高興的把書套拆下來，掛在床頭當夜燈，天天開開關關的玩。至於那本百科全書，他連一頁都沒有翻開，就塞進了書櫃最底層。', q: '小宇的做法，最適合用哪個成語形容？', opts: ['買櫝還珠', '黔驢技窮', '望梅止渴', '濫竽充數'], a: 0, why: '書套是外面的「盒子」，百科全書才是「珍珠」。小宇只玩書套、不讀書，就是買櫝還珠。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈部落格〉這家蛋糕店的盒子設計得很漂亮，蛋糕更是鬆軟好吃，我和家人把蛋糕吃得一乾二淨，盒子也留下來裝文具。真是買櫝還珠的好店！', q: '這段話的「買櫝還珠」用得恰當嗎？', opts: ['不恰當，蛋糕吃了，沒丟掉重要的', '恰當，因為盒子很漂亮被留下來了', '恰當，因為蛋糕店的東西很好吃', '不恰當，因為蛋糕盒裡沒有珍珠'], a: 0, why: '買櫝還珠是只要外表、丟掉重要的。作者吃了蛋糕又留了盒子，沒有丟掉重要的，不能用買櫝還珠，更不能拿來稱讚店家。' },
      { id: 'p4', k: 'fill', d: 2, type: 'mc', q: '上自然課只顧著把實驗器材擺得整整齊齊，卻沒有觀察實驗結果，這就像＿＿＿＿。', opts: ['買櫝還珠', '門庭若市', '望梅止渴', '黔驢技窮'], a: 0, why: '擺器材是次要的，觀察結果才重要，只顧次要的就是買櫝還珠。其他三個放進句子都說不通。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '鄭國人把真正值錢的珍珠還回去了。想一想，你在上學、買東西或參加活動時，有沒有只顧「外面的盒子」、忘了「裡面的珍珠」的時候？以後可以怎麼提醒自己？',
        ref: '我上次參加作文比賽，花了很多時間把稿紙邊框畫得很漂亮，結果作文沒寫完。邊框就像盒子，作文內容才是珍珠。以後我會先問自己「這次最重要的是什麼」，先把重要的事做好，有時間再裝飾。',
        rubric: ['舉出一個只顧外表、忽略重點的經驗', '分辨出其中的「盒子」和「珍珠」', '提出提醒自己的具體方法'] }
    ],
    xq: [
      { id: 'x1', k: 'judge', d: 1, type: 'tf', q: '「參加校外教學時，他只顧著吃零食、拍照，導覽員介紹的內容一句也沒聽，真是買櫝還珠。」這句話的「買櫝還珠」用得恰當。', a: true, why: '校外教學最重要的是學到東西，他只顧次要的吃和拍照，用買櫝還珠恰當。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '媽媽：「這套故事書的封面好漂亮，你讀了嗎？」\n妹妹：「每一本我都讀了兩遍，封面也包上書套，捨不得弄髒。」\n姊姊：「妹妹真是買櫝還珠。」', q: '姊姊說的「買櫝還珠」用得恰當。', a: false, why: '妹妹讀了內容（珍珠），也愛護封面（盒子），沒有丟掉重要的東西，不是買櫝還珠。' }
    ]
  },

  // ==================== L2 歷史故事 ====================
  {
    id: 'cy028', lv: 2, word: '指鹿為馬', zhuyin: 'ㄓˇ ㄌㄨˋ ㄨㄟˊ ㄇㄚˇ', src: '漢．陸賈《新語．辨惑》',
    quote: '秦王不能自信其直目，而從邪臣之言',
    facts: ['《成語典》典出漢．陸賈《新語．辨惑》，不是《史記》；故事主角是秦朝的趙高和秦二世｜教育部《成語典》', '秦始皇死後，趙高假傳詔命，扶立胡亥當上二世皇帝，自己當上丞相、獨攬朝政｜教育部《成語典》典故說明', '《新語》記載：大臣有一半說是鹿、一半說是馬，二世最後不信自己的眼睛，聽從了趙高｜《新語．辨惑》'],
    story: [
      '秦朝的第一個皇帝秦始皇過世以後，一個叫趙高的大臣，用假造的命令讓秦始皇的兒子胡亥當上皇帝，也就是秦二世。趙高自己當上了丞相，朝廷的大小事情幾乎都由他說了算。',
      '可是趙高還不滿足，他心裡想要更大的權力。他擔心朝廷裡的大臣不聽他的話，就想出一個辦法，試探看看大家到底怕不怕他。',
      '有一天，秦二世要出門，趙高駕著一輛由鹿拉的車，跟在皇帝旁邊。秦二世看了覺得奇怪，就問：「丞相，你為什麼用鹿來拉車呢？」',
      '趙高面不改色的說：「陛下，這是馬呀。」秦二世笑了：「丞相弄錯了吧？這明明是鹿，怎麼說是馬？」趙高還是堅持：「這就是馬。陛下如果不相信我的話，可以問問大臣們。」',
      '秦二世真的轉頭去問身邊的大臣。大臣們你看我、我看你，心裡都很清楚那是一頭鹿。可是說出真話，會不會得罪趙高呢？結果，有一半的人說「是鹿」，另一半的人卻順著趙高說「是馬」。',
      '聽了大臣們的回答，秦二世竟然不再相信自己的眼睛，反而相信了趙高的話。陸賈在《新語》裡感嘆：國君明明看得清清楚楚，卻聽信奸臣的話，這就是糊塗啊！',
      '一頭鹿，只因為有權力的人說牠是馬，就有人跟著說是馬。後來，「指鹿為馬」就用來比喻故意顛倒是非、混淆黑白。'
    ],
    mean: '把鹿說成是馬，藉此展現自己的權勢。比喻故意顛倒是非、混淆黑白。',
    usage: ['用在有人故意把對的說成錯的、把錯的說成對的時候（貶義），常常帶有仗著權勢的意思。', '如果只是不小心認錯、看錯，不是故意的，不能說指鹿為馬。', '反義成語是「循名責實」：照著名稱去查看實際，要名實相符。'],
    misuse: ['「弟弟年紀小，把企鵝說成鴨子，真是指鹿為馬。」✗　弟弟是不小心認錯，不是故意顛倒是非，不能用指鹿為馬。'],
    eg: ['明明是他先推人，卻說是對方故意撞他，這種指鹿為馬的說法，大家都不相信。', '比賽影片拍得清清楚楚，他還硬說球沒出界，簡直是指鹿為馬。'],
    syn: [], ant: ['循名責實'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '趙高跟在秦二世旁邊時，駕的是什麼車？', opts: ['由鹿拉的車', '由馬拉的車', '由牛拉的車', '由人抬的轎子'], a: 0, why: '第三段：「趙高駕著一輛由鹿拉的車。」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '趙高為什麼要把鹿說成馬？', opts: ['想試探大臣們怕不怕他', '他真的分不清鹿和馬', '想讓秦二世開心一下', '他想把鹿送給皇帝'], a: 0, why: '第二段：他擔心大臣不聽他的話，想「試探看看大家到底怕不怕他」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '大臣們心裡知道是鹿，為什麼有一半的人說「是馬」？', opts: ['怕說真話會得罪趙高', '他們的眼睛看不清楚', '他們從來沒見過鹿', '皇帝要他們說是馬'], a: 0, why: '第五段：大臣「心裡都很清楚那是一頭鹿」，卻擔心「說出真話，會不會得罪趙高」。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '陸賈在《新語》裡，最感嘆的是誰的糊塗？', opts: ['不信自己眼睛的秦二世', '把鹿說成是馬的趙高', '說是鹿的那一半大臣', '替皇帝拉車的那頭鹿'], a: 0, why: '第六段：國君「明明看得清清楚楚，卻聽信奸臣的話」，陸賈感嘆的是秦二世的糊塗。引文的原句也是在說秦王不相信自己的眼睛。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '如果你是那時候的大臣，秦二世問你「這是鹿還是馬」，你會怎麼回答？說真話和說假話，各會有什麼後果？請說明你的選擇和理由。',
        ref: '我會說是鹿。說假話雖然可以討好趙高，可是大家都跟著說假話，皇帝就會越來越分不清是非，國家會更危險。說真話可能會被趙高討厭，但是我覺得做人要誠實，看到什麼就說什麼。',
        rubric: ['說出自己會怎麼回答', '比較說真話和說假話的後果', '理由合理，能連結故事內容'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「指鹿為馬」比喻什麼？', opts: ['故意顛倒是非', '分不清楚動物', '很會養鹿和馬', '做事很有效率'], a: 0, why: '指鹿為馬是故意把鹿說成馬，比喻故意顛倒是非、混淆黑白。重點在「故意」。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '下課時，阿強把小文的鉛筆盒撞到地上，還踩壞了一支筆。小文去告訴老師，阿強卻大聲說：「是小文自己放在桌邊，鉛筆盒自己掉下去的，跟我沒關係！」旁邊幾個平常跟阿強很要好的同學，也跟著說：「對啊，是自己掉的。」可是全班很多人都看見了事情的經過。', q: '阿強和那幾位同學的說法，最適合用哪個成語形容？', opts: ['指鹿為馬', '望梅止渴', '南轅北轍', '磨杵成針'], a: 0, why: '大家都看見了，阿強卻故意把事情說反，還有人跟著附和，就像趙高和附和的大臣，是指鹿為馬。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈日記〉今天去動物園，我第一次看到羊駝，以為牠是一隻長脖子的羊。爸爸笑著告訴我，羊駝是另一種動物。我真是指鹿為馬，下次要看清楚說明牌。', q: '日記裡的「指鹿為馬」用得恰當嗎？', opts: ['不恰當，他是不小心認錯，不是故意', '恰當，因為他把羊駝認成了羊', '恰當，因為爸爸糾正了他', '不恰當，因為羊駝跟鹿長得不一樣'], a: 0, why: '指鹿為馬是「故意」顛倒是非。日記裡的人是第一次看到、不小心認錯，不能用指鹿為馬。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「明明是自己忘了帶作業，他卻一口咬定是組長沒有收，大家都說他指鹿為馬。」這句話的「指鹿為馬」用得恰當。', a: true, why: '他知道是自己忘了帶，卻故意說成別人的錯，是故意顛倒是非，用得恰當。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '大臣們因為害怕趙高，有一半的人跟著說假話。如果你在班上看到有人故意把錯的說成對的，其他人都不敢說話，你會怎麼做？',
        ref: '我會把我看到的事情說清楚，不會跟著說假話。如果我怕自己說了會被欺負，可以先找老師，把看到的經過告訴老師，請老師來處理。這樣既誠實，也能保護自己。',
        rubric: ['說出自己會怎麼做', '能堅持說出事實', '想到保護自己或請大人協助的方法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '照片拍得清清楚楚，他卻硬說那不是自己，這種＿＿＿＿的態度，讓人很生氣。', opts: ['指鹿為馬', '望梅止渴', '磨杵成針', '門庭若市'], a: 0, why: '證據清楚卻硬說不是，是故意顛倒是非，用指鹿為馬。其他三個放進句子都說不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '社區開會討論公園的空地要種樹還是蓋停車場。大部分的住戶都簽名支持種樹，可是負責統計的王先生想要蓋停車場，就向大家宣布：「簽名支持停車場的人比較多。」有人拿出簽名單一數，發現支持種樹的人明明多了一倍。', q: '王先生的說法可以用哪個成語形容？', opts: ['指鹿為馬', '對牛彈琴', '黔驢技窮', '門可羅雀'], a: 0, why: '簽名單清清楚楚，王先生卻故意說反，是指鹿為馬。對牛彈琴是講話不看對象，黔驢技窮是本事用完，門可羅雀是冷清。' }
    ]
  },
  {
    id: 'cy032', lv: 2, word: '磨杵成針', zhuyin: 'ㄇㄛˊ ㄔㄨˇ ㄔㄥˊ ㄓㄣ', src: '宋．祝穆《方輿勝覽．磨鍼溪》',
    quote: '逢老媼方磨鐵杵，問之，曰：「欲作針。」',
    facts: ['典出宋．祝穆《方輿勝覽．卷五三．磨鍼溪》｜教育部《成語典》', '原文說這是「世傳」：世人流傳唐朝詩人李白（字太白）在山中讀書，還沒讀成就想離開｜《方輿勝覽．磨鍼溪》', '磨鍼溪在象耳山下；李白遇見老婦人磨鐵杵，深受感動，回去完成學業｜《方輿勝覽．磨鍼溪》、教育部《成語典》典故說明', '「杵」是舂米、搗藥時用的棒槌｜教育部《成語典》釋義'],
    story: [
      '唐朝有一位大詩人，叫做李白，字太白。宋朝人祝穆寫地理書時，記下了一個在民間流傳很久的故事，說的是李白年輕時讀書的事。',
      '傳說李白年輕時，在一座叫象耳山的山裡讀書。山上安安靜靜的，只有鳥叫和風聲。一開始，他還算用功；可是讀著讀著，他覺得書怎麼讀也讀不完，越讀越煩，心想：「讀書這麼辛苦，不如下山去吧！」於是，書還沒讀完，他就收拾東西離開了。',
      '下山的路上，他經過一條小溪，看見一位老婆婆蹲在溪邊的石頭旁，手裡拿著一根粗粗的鐵棒，一下一下的在石頭上磨著。',
      '李白覺得很奇怪，走過去問：「老婆婆，您在做什麼呀？」老婆婆頭也不抬的說：「我要把這根鐵棒磨成一根針。」',
      '李白嚇了一跳：「這麼粗的鐵棒，要磨成細細的針，那要磨到什麼時候啊？」老婆婆笑了笑，手還是沒停：「今天磨一點，明天再磨一點，只要一直磨下去，總有一天會變成針的。」',
      '李白站在溪邊，看著那根鐵棒，心裡好像被什麼東西敲了一下。這麼難的事，老婆婆都不放棄；自己讀書才遇到一點辛苦，就想半途而廢。他轉身走回山上，重新打開書本，從此認真讀書，最後終於完成了學業。',
      '這條小溪，就是地理書裡記載的「磨鍼溪」，「鍼」就是「針」。後來，「磨杵成針」成了一句成語，比喻只要有恆心、肯努力，再困難的事也能做成。'
    ],
    mean: '把鐵棒磨成細針。比喻只要有恆心、努力去做，無論多困難的事都能成功。',
    usage: ['用在稱讚或勉勵人長時間、不放棄的努力（褒義）。', '近義成語有「滴水穿石」「有志竟成」「磨穿鐵硯」。', '只做一兩次、很快就完成的事，不能說磨杵成針；重點是「長時間一點一點的累積」。'],
    misuse: [],
    eg: ['姊姊每天練習寫一頁毛筆字，三年下來字越寫越漂亮，真是磨杵成針。', '學游泳一開始很難，但只要有磨杵成針的精神，總有一天能游完五十公尺。'],
    syn: ['滴水穿石', '有志竟成', '磨穿鐵硯'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '李白在溪邊看到老婆婆在做什麼？', opts: ['把鐵棒磨成針', '在溪裡洗衣服', '在石頭上搗藥', '用針縫補衣服'], a: 0, why: '第三、四段：老婆婆拿著鐵棒在石頭上磨，說「我要把這根鐵棒磨成一根針」。' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '李白為什麼會在書還沒讀完時下山？', opts: ['覺得讀書辛苦，不想讀了', '家裡有急事要他回去', '山上的書都讀完了', '老師叫他下山去玩'], a: 0, why: '第二段：他覺得「書怎麼讀也讀不完，越讀越煩」，想到「讀書這麼辛苦」，就離開了。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '李白聽完老婆婆的話以後，有什麼改變？', opts: ['回山上認真讀書，完成學業', '留下來幫老婆婆磨鐵棒', '決定以後改行去做針', '跑去找更好玩的地方'], a: 0, why: '第六段：他想到老婆婆都不放棄，自己卻想半途而廢，就「轉身走回山上……最後終於完成了學業」。' },
      { id: 'r4', p: 4, d: 3, type: 'open', q: '有人說：「把鐵棒磨成針太浪費時間了，去買一根針不就好了？」你同意這個說法嗎？你覺得這個故事真正想告訴我們的是什麼？',
        ref: '如果只是要一根針，去買確實比較快。可是這個故事不是在教人怎麼做針，而是用磨鐵棒來比喻做難的事要有恆心。李白讀書就像磨鐵棒，沒有人能替他讀，只能自己每天讀一點，慢慢累積。',
        rubric: ['對這個說法提出看法', '指出故事是比喻，不是真的在教做針', '說出故事想告訴我們的道理（恆心、累積）'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「磨杵成針」的「杵」是什麼？', opts: ['舂米、搗藥用的棒子', '縫補衣服用的細針', '磨刀用的大石頭', '溪裡游來游去的魚'], a: 0, why: '「杵」是舂米、搗藥時用的棒槌，故事裡是鐵做的「鐵杵」。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '阿德剛開始學跳繩時，連五下都跳不到，常常被繩子絆倒。可是他沒有放棄，每天早上提早十分鐘到學校，在操場角落練習。一個月後他能跳五十下，三個月後能連跳兩百下，期末還代表班上參加跳繩比賽，拿到了第二名。', q: '阿德的進步，最適合用哪個成語形容？', opts: ['磨杵成針', '指鹿為馬', '買櫝還珠', '黔驢技窮'], a: 0, why: '阿德每天練一點，長時間累積，終於成功，就是磨杵成針。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈作文〉昨天晚上，我只花了十分鐘就把明天要考的生字背完了，今天考了一百分。這就是磨杵成針的道理！', q: '作文裡的「磨杵成針」用得恰當嗎？', opts: ['不恰當，只花十分鐘，不是長期努力', '恰當，因為他最後考了一百分', '恰當，因為他背得又快又好', '不恰當，因為背生字不需要用到針'], a: 0, why: '磨杵成針重在「長時間、一點一點的努力」。只花十分鐘，不是磨杵成針。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '下面哪一個成語，意思和「磨杵成針」最接近？', opts: ['滴水穿石', '半途而廢', '一暴十寒', '望梅止渴'], a: 0, why: '滴水穿石是水一滴一滴也能把石頭滴穿，和磨杵成針一樣強調恆心。半途而廢、一暴十寒都是不能堅持，意思相反。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '老婆婆說：「今天磨一點，明天再磨一點。」選一件你想學會、但現在覺得很難的事，替自己訂一個「每天磨一點」的計畫，並說說遇到想放棄的時候，你會怎麼提醒自己。',
        ref: '我想學會用烏克麗麗彈一首歌。我每天練十五分鐘，第一週先練會四個和弦，第二週練換和弦，第三週再跟著歌唱。想放棄的時候，我會看看第一天錄的影片，提醒自己已經進步很多了。',
        rubric: ['說出一件想學會的難事', '訂出每天一小步、有先後的計畫', '說出遇到挫折時提醒自己的方法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '他每天放學都練習十個英文單字，兩年下來能看懂整本英文故事書，正是＿＿＿＿的最好例子。', opts: ['磨杵成針', '指鹿為馬', '濫竽充數', '望梅止渴'], a: 0, why: '每天一點、兩年累積出成果，是磨杵成針。其他三個放進句子都說不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '小美：「我想學會倒立，可是練了兩天都倒不起來，我不想練了。」\n小玲：「別急，每天練一點，磨杵成針，總有一天會成功的。」', q: '小玲說的「磨杵成針」用得恰當。', a: true, why: '小玲勸小美每天練一點、長期堅持，用磨杵成針鼓勵她，很恰當。' }
    ]
  },
  {
    id: 'cy036', lv: 2, word: '精衛填海', zhuyin: 'ㄐㄧㄥ ㄨㄟˋ ㄊㄧㄢˊ ㄏㄞˇ', src: '《山海經．北山經》',
    quote: '常銜西山之木石，以堙于東海',
    facts: ['典出《山海經．北山經》｜教育部《成語典》', '主角是炎帝的小女兒女娃，她在東海遊玩時溺水沒有回來，後來化成一種叫「精衛」的鳥｜教育部《成語典》釋義', '精衛住在發鳩山，叫聲就像在叫自己的名字｜教育部《成語典》典故說明、《山海經．北山經》', '原本比喻心懷冤憤、立志報仇；也比喻意志堅定，不怕艱苦｜教育部《成語典》釋義'],
    story: [
      '很久很久以前，有一本記錄山川和奇特動物的古書，叫做《山海經》。書裡寫著一個古老的神話。',
      '傳說，上古時代的炎帝有一個小女兒，名叫女娃。女娃最喜歡大海，常常跑到東海邊，看浪花一層一層的打上沙灘。',
      '有一天，女娃又到東海去玩。忽然颳起了大風，海浪一下子翻得好高好高，把女娃捲進了海裡。她再也沒有回來。',
      '後來，在北方的發鳩山上，出現了一種小鳥。牠的頭上有花紋，嘴巴是白色的，腳是紅色的。牠一邊飛，一邊發出「精衛、精衛」的叫聲，好像在叫自己的名字，人們就叫牠「精衛」。傳說，精衛就是女娃變成的。',
      '精衛非常痛恨把她捲走的大海。她每天從西山銜來一根小樹枝、一顆小石子，飛過長長的路，丟進東海裡，想要把大海填平。',
      '大海那麼大，一根樹枝、一顆石子丟下去，連一點水花都看不見。浪花好像在笑她：「小鳥，你永遠也填不平我的！」可是精衛不理會，第二天、第三天、第一百天……她還是一趟一趟的飛，從來沒有停下來。',
      '這個神話一代一代流傳下來。「精衛填海」最早用來比喻心裡有冤屈和憤怒，立志要報仇；後來，人們更常用它來比喻意志堅定，不怕艱苦，不達目的不停止。'
    ],
    mean: '炎帝的小女兒溺水後化成精衛鳥，每天銜樹枝、石子想填平東海。原本比喻心懷冤憤、立志報仇；也比喻意志堅定、不怕艱苦。',
    usage: ['今天多用來稱讚意志堅定、不怕困難、一直努力的人（褒義）。', '原本也有「心懷冤憤、立志報仇」的意思，讀古書時要知道。', '近義成語有「愚公移山」「水滴石穿」；如果做事不能堅持，就不能用精衛填海。'],
    misuse: [],
    eg: ['這群志工每個週末都去淨灘，十年來從不間斷，憑的就是精衛填海的毅力。', '雖然要背的單字很多，但我會用精衛填海的精神，每天背一點。'],
    syn: ['愚公移山', '水滴石穿', '心堅石穿'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '精衛每天銜什麼東西丟進東海？', opts: ['小樹枝和小石子', '小魚和漂亮貝殼', '海邊的沙和海草', '山上的花和果子'], a: 0, why: '第五段：「她每天從西山銜來一根小樹枝、一顆小石子。」' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '人們叫這種鳥「精衛」，是因為牠的叫聲聽起來像「精衛」。', a: true, why: '第四段：牠發出「精衛、精衛」的叫聲，好像在叫自己的名字，人們就叫牠精衛。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '浪花「好像在笑她」，表示什麼？', opts: ['大海太大，看起來填不平', '大海很喜歡跟精衛玩', '精衛飛得太低被打到', '精衛的叫聲很好笑'], a: 0, why: '第六段：一根樹枝、一顆石子丟下去「連一點水花都看不見」，大海太大，精衛的事看起來不可能成功。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '「精衛填海」這個成語，早期和後來的用法有什麼不同？', opts: ['先多指立志報仇，後多指意志堅定', '先指意志堅定，後指立志報仇', '從古到今一直都是指把海填平', '從古到今一直都是指做白費力氣的事'], a: 0, why: '最後一段：最早比喻心有冤屈、立志報仇；後來更常比喻意志堅定、不怕艱苦。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '大海那麼大，精衛一定填不平。你覺得精衛的做法是「堅強」還是「傻」？請用故事內容說明你的看法。',
        ref: '我覺得是堅強。雖然大海填不平，但是精衛每天一趟一趟的飛，從來不放棄，這種毅力很了不起。不過如果是我，我也會想一想有沒有更好的方法，例如找其他鳥一起幫忙，或把力氣用在提醒別人小心大海。',
        rubric: ['表明自己的看法', '用故事內容當理由（大海很大、精衛天天飛）', '能說明堅持為什麼值得，或想到方法也很重要'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '今天說一個人有「精衛填海」的精神，是在稱讚他什麼？', opts: ['意志堅定，不怕艱苦', '很會游泳，不怕大海', '喜歡小鳥，愛護動物', '力氣很大，搬得動石頭'], a: 0, why: '精衛填海今天多比喻意志堅定、不怕艱苦，不是稱讚游泳或力氣。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '學校後面的小河以前常常被丟滿垃圾。林伯伯退休後，每天早上都拿著夾子和袋子去河邊撿垃圾。剛開始，他撿完了，第二天又有人亂丟，鄰居都說：「你撿不完的啦！」林伯伯還是天天去，五年過去了，河邊越來越乾淨，現在還有小魚游回來。', q: '林伯伯的做法，最適合用哪個成語形容？', opts: ['精衛填海', '紙上談兵', '望梅止渴', '黔驢技窮'], a: 0, why: '林伯伯面對看似做不完的事，仍然天天堅持，就像精衛一趟一趟的飛，是精衛填海。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈班級日記〉阿凱這學期參加數學營，練了兩天覺得太難，就說要退出，改去參加桌遊社。小莉說：「阿凱這真是精衛填海的精神啊！」', q: '小莉用「精衛填海」形容阿凱，恰當嗎？', opts: ['不恰當，阿凱遇到困難就放棄了', '恰當，因為數學營真的很難', '恰當，因為阿凱換了一個新社團', '不恰當，因為數學營沒有在海邊'], a: 0, why: '精衛填海是意志堅定、不怕艱苦。阿凱兩天就退出，剛好相反。成語是比喻，跟海邊無關。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '下面哪一個成語，意思和「精衛填海」最接近？', opts: ['愚公移山', '畫蛇添足', '望梅止渴', '門可羅雀'], a: 0, why: '愚公移山也是面對很大的困難，仍然一天一天堅持，《成語典》列為近義成語。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '精衛一趟一趟的飛，從不放棄。想一件你覺得「很大、很難、做不完」的事（例如整理房間、練一首曲子、讀完一套書），你可以怎麼把它分成每天做得到的小步驟？',
        ref: '我想讀完一套二十本的歷史漫畫，一開始覺得太多了。我可以每天睡前讀十五分鐘，大概兩天讀完一本，讀完一本就在書單上打勾。這樣一個多月就能讀完，不會一下子覺得做不到。',
        rubric: ['說出一件很大、很難的事', '把它分成每天做得到的小步驟', '說出怎麼保持堅持（例如記錄、打勾）'] }
    ],
    xq: [
      { id: 'x1', k: 'judge', d: 1, type: 'tf', q: '「他練了三天鋼琴就嫌手痠，說不學了，真是精衛填海。」這句話的「精衛填海」用得恰當。', a: false, why: '練三天就放棄，和精衛填海的「意志堅定、不怕艱苦」相反，用錯了。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '小鎮的圖書館很舊，書也很少。陳阿姨決定一個人募書，她每週騎著腳踏車到處拜訪住家，一本一本的收集舊書，再自己動手修補、分類。有人笑她：「這要收到什麼時候？」她還是一週一週的做，八年後圖書館已經有三萬本書，成了全鎮小朋友最愛去的地方。', q: '陳阿姨的做法可以用哪個成語形容？', opts: ['精衛填海', '南轅北轍', '指鹿為馬', '買櫝還珠'], a: 0, why: '別人覺得做不完，她仍然一本一本、一週一週的堅持，就是精衛填海。' }
    ]
  },
  {
    id: 'cy039', lv: 2, word: '紙上談兵', zhuyin: 'ㄓˇ ㄕㄤˋ ㄊㄢˊ ㄅㄧㄥ', src: '《史記．廉頗藺相如列傳》',
    quote: '括徒能讀其父書傳，不知合變也',
    facts: ['典出《史記．廉頗藺相如列傳》（附〈趙奢傳〉），主角是戰國時代趙國的趙括｜教育部《成語典》', '趙括是名將趙奢的兒子，從小熟讀兵書，趙奢卻認為他不懂變通，不適合當將軍｜教育部《成語典》典故說明', '秦國散布謠言，趙王改派趙括代替廉頗；秦將白起截斷趙軍的運糧路線，趙軍大敗｜教育部《成語典》典故說明', '藺相如和趙括的母親都勸過趙王不要用趙括｜教育部《成語典》典故說明'],
    story: [
      '戰國時代，趙國有一位很會打仗的將軍，叫做趙奢。他的兒子趙括從小就愛讀兵書，什麼陣法、戰術都背得滾瓜爛熟。',
      '趙括常常跟父親討論怎麼打仗，說得頭頭是道，連趙奢都說不過他。趙括很得意，覺得天下沒有人比得上自己。可是趙奢一點也不高興。妻子問他為什麼，趙奢說：「打仗是關係生死的大事，括兒卻把它說得那麼輕鬆。他只會讀書，不懂得隨著情況變化。將來趙國如果讓他當將軍，一定會吃大虧。」',
      '後來趙奢過世了。秦國派大軍攻打趙國，趙國由老將軍廉頗帶兵。廉頗知道秦軍很強，就守在堅固的營壘裡，不管秦軍怎麼挑戰，都不出去打。',
      '秦國很頭痛，就派人到趙國散播謠言：「秦國最怕的是趙括當將軍，廉頗根本不算什麼。」趙王聽信了謠言，決定換趙括去代替廉頗。',
      '生病在家的大臣藺相如勸趙王：「趙括只會讀他父親留下的兵書，不懂得變通啊！」趙括的母親也上書說：「這孩子不能當將軍。」可是趙王都聽不進去。',
      '趙括一到前線，就把廉頗的作戰方法全部改掉，還換掉了許多軍官。秦國的大將白起看準機會，派兵截斷趙軍運送糧食的路，把趙軍團團圍住。趙軍被困了四十多天，糧食都吃光了。趙括帶兵往外衝，沒能衝出去，趙軍大敗，趙國的力量從此大大減弱。',
      '趙括書讀得很多，說起打仗來誰也比不上，可是一到真正的戰場，書上的方法卻派不上用場。後來，人們用「紙上談兵」比喻只會空談、不切實際的議論。'
    ],
    mean: '在紙上談論用兵打仗的策略。比喻不切實際的議論，只會空談，不能真正做到。',
    usage: ['用在批評只會說、不會做，或議論不切實際的時候（貶義）。', '近義成語有「光說不練」「空言無補」。', '事前做計畫、讀書學方法本身不是紙上談兵；要有「只會說，用不到實際情況上」的意思才對。'],
    misuse: [],
    eg: ['他把游泳的書看了好幾本，卻從來沒下過水，說起游泳技巧只是紙上談兵。', '園遊會的計畫寫得再漂亮，不去實際算算成本，也只是紙上談兵。'],
    syn: ['光說不練', '空言無補'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '趙括從小最喜歡做什麼？', opts: ['讀兵書', '騎馬射箭', '到戰場打仗', '種田養馬'], a: 0, why: '第一段：「他的兒子趙括從小就愛讀兵書。」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '趙括說得比父親還好，趙奢為什麼「一點也不高興」？', opts: ['兒子只會說，不懂變通', '他嫉妒兒子比自己聰明', '他希望兒子不要再讀書', '他覺得兒子說話太大聲'], a: 0, why: '第二段趙奢說：括兒「只會讀書，不懂得隨著情況變化」，把打仗說得太輕鬆。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '秦國為什麼要散播「最怕趙括」的謠言？', opts: ['想讓趙王換掉守得很穩的廉頗', '秦國的將領真的很害怕趙括', '想讓趙括和廉頗一起帶兵', '想稱讚趙括兵書讀得很好'], a: 0, why: '第三、四段：廉頗守著不出戰，秦國很頭痛，才用謠言讓趙王換掉廉頗。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '把趙奢、藺相如的話和最後的結果合起來看，趙括失敗最主要的原因是什麼？', opts: ['只會照書上說，不會變通', '他讀過的兵書還不夠多', '趙國的士兵都不夠勇敢', '秦國的軍隊人數比較多'], a: 0, why: '趙奢說他「不懂得隨著情況變化」，藺相如也說他「不懂得變通」；結果一上戰場，書上的方法就派不上用場（最後一段）。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '趙括讀了很多兵書，最後卻打了敗仗。你覺得「讀書學到的知識」沒有用嗎？要怎麼做，才能讓學到的東西真正用得上？請用故事和自己的經驗說明。',
        ref: '我覺得讀書學到的知識是有用的，趙奢自己也是很會打仗的將軍。趙括的問題是只會照書上說，沒有看清楚真正的情況。像我學了游泳的動作，還是要下水練習，遇到水深的地方也要調整，才是真的會游泳。',
        rubric: ['對「知識有沒有用」提出看法', '用故事說明趙括的問題在哪裡', '舉出把學到的東西用在實際情況的例子'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「紙上談兵」比喻什麼？', opts: ['只會空談，不切實際', '在紙上畫打仗的圖', '很會寫信給朋友', '讀很多書就會成功'], a: 0, why: '紙上談兵是只會在紙上談打仗，比喻不切實際的議論。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '班上要種一盆向日葵參加比賽。阿誠在班會上說得頭頭是道：土要怎麼配、一天要澆幾次水、要曬幾個小時的太陽，都講得清清楚楚。可是他從來沒有種過花，輪到他照顧的第一週，就把水澆得太多，花苗的根都爛了。', q: '阿誠的情形，最適合用哪個成語形容？', opts: ['紙上談兵', '精衛填海', '磨杵成針', '買櫝還珠'], a: 0, why: '阿誠說得頭頭是道，實際做卻出錯，就像趙括，是紙上談兵。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈班會紀錄〉為了準備運動會，體育股長先在白板上畫好接力的棒次和交棒位置，接著帶大家到操場實際練習了五次，一邊練一邊調整。有人說：「股長真是紙上談兵。」', q: '這位同學說「紙上談兵」，恰當嗎？', opts: ['不恰當，股長有實際練習和調整', '恰當，因為股長先在白板上畫圖', '恰當，因為接力賽就是一種比賽', '不恰當，因為運動會不是在打仗'], a: 0, why: '股長先計畫、再實際練習並調整，正好不是紙上談兵。成語是比喻，不是只能用在打仗。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '下面哪一個成語，意思和「紙上談兵」最接近？', opts: ['光說不練', '身體力行', '一字千金', '磨杵成針'], a: 0, why: '光說不練是只說不做，和紙上談兵相近（《成語典》近義）。身體力行是親身去做，意思相反。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '趙括只會說，不會做。想一件你「說起來很會、做起來不一定會」的事（例如做菜、修腳踏車、照顧寵物），你可以怎麼從「紙上」走到「實際」？',
        ref: '我看了很多做蛋糕的影片，步驟都背起來了，可是從來沒有自己做過。我可以先請媽媽陪我做一次最簡單的杯子蛋糕，把每一步做做看，失敗了就記下哪裡不對，下次再改進。',
        rubric: ['說出一件說得出、卻還沒做過的事', '提出實際動手的步驟', '想到從錯誤中調整'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '你說了那麼多存錢的方法，自己卻一塊錢也沒存，再好的計畫也只是＿＿＿＿。', opts: ['紙上談兵', '精衛填海', '門庭若市', '一字千金'], a: 0, why: '只說不做，計畫用不到實際上，是紙上談兵。其他三個放進句子都說不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '自然科展前，小翔在組員面前滔滔不絕的說他的實驗計畫，說要觀察種子在不同顏色的燈光下怎麼長。可是三個星期過去了，他連種子都沒有買，也沒有做過一次記錄。發表那天，他只能拿著一張畫滿箭頭的紙，對著評審講他「本來想做」的實驗。', q: '小翔的情形可以用哪個成語形容？', opts: ['紙上談兵', '對牛彈琴', '黔驢技窮', '臥薪嘗膽'], a: 0, why: '小翔只會說計畫，沒有真正動手，是紙上談兵。' }
    ]
  },
  {
    id: 'cy042', lv: 2, word: '破釜沉舟', zhuyin: 'ㄆㄛˋ ㄈㄨˇ ㄔㄣˊ ㄓㄡ', src: '《史記．項羽本紀》',
    quote: '皆沉船，破釜甑，燒廬舍，持三日糧',
    facts: ['典出漢．司馬遷《史記．項羽本紀》｜教育部《成語典》', '秦朝末年，秦將章邯圍攻趙國的鉅鹿；楚懷王派宋義、項羽救趙，宋義卻按兵不動，後來項羽取得兵權｜教育部《成語典》典故說明', '項羽率全軍渡河後，弄沉船隻、打破炊具、燒掉營舍，只帶三天的糧食，表示死戰的決心｜《史記．項羽本紀》', '楚軍經過九次交戰大破秦軍，就是「鉅鹿之戰」｜教育部《成語典》典故說明', '《成語典》辨析：「破釜沉舟」側重不回頭、不罷休的決心；「背水一戰」側重絕境中奮力一搏｜教育部《成語典》辨析'],
    story: [
      '秦朝末年，天下大亂，各地的人紛紛起來反抗秦朝。秦國的大將章邯帶著強大的軍隊，把趙國的鉅鹿城團團圍住，趙國趕緊向各地求救。',
      '楚國派了宋義當主將、項羽當副將，帶兵去救趙國。可是宋義走到半路就停了下來，一停就是四十多天，不管趙國多危急，都不肯往前。項羽很著急，覺得再拖下去，趙國就完了。後來，項羽奪下了軍隊的指揮權，決定立刻出兵。',
      '他先派兩萬名士兵渡過黃河，可是戰況還是很不利，趙國又派人來求救。項羽下定決心，帶著全部的軍隊渡河。',
      '過了河以後，項羽下了一道讓大家都嚇一跳的命令：「把所有的船都弄沉！把煮飯的鍋子都打破！把營房都燒掉！每個人只帶三天的糧食！」',
      '士兵們看著沉到河底的船、碎成一片片的鍋子，心裡都明白了：沒有船可以回去，也沒有鍋子可以煮飯，三天的糧食吃完以前，一定要打贏，不能後退。大家把害怕放在一旁，鼓起所有的勇氣往前衝。',
      '楚軍和秦軍一連打了九場仗，每一個楚國士兵都拚盡全力，喊聲震天動地。最後，楚軍大敗秦軍，救下了鉅鹿。這場戰爭叫做「鉅鹿之戰」，項羽也從此名震天下。',
      '後來，人們就用「破釜沉舟」比喻下定決心、不留退路，全力以赴去爭取最好的結果。'
    ],
    mean: '打破鍋子、弄沉船隻，讓自己沒有退路。比喻下定決心、不留退路，全力以赴去爭取最好的結果。',
    usage: ['用在「下定決心、不再回頭，拚盡全力」的時候（褒義）。', '和「背水一戰」都有決心一戰的意思；破釜沉舟側重不回頭、不罷休的決心，背水一戰側重在絕境中奮力一搏。', '如果還留著退路、只是做做看，就不能說破釜沉舟；反義成語有「急流勇退」「退避三舍」。'],
    misuse: [],
    eg: ['為了專心準備鋼琴檢定，姊姊破釜沉舟，把平板電腦交給媽媽保管一個月。', '這是最後一場比賽，輸了就淘汰，球員們抱著破釜沉舟的決心上場。'],
    syn: ['背水一戰', '孤注一擲', '濟河焚舟'], ant: ['急流勇退', '退避三舍'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '渡河以後，項羽讓每個士兵帶幾天的糧食？', opts: ['三天', '九天', '四十天', '一個月'], a: 0, why: '第四段：「每個人只帶三天的糧食！」九是打仗的次數，四十多天是宋義停下來的時間。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '宋義帶兵走到半路就停下來，四十多天都不肯前進。', a: true, why: '第二段：宋義「走到半路就停了下來，一停就是四十多天」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '項羽為什麼要把船弄沉、把鍋子打破？', opts: ['讓士兵知道沒有退路了', '船和鍋子太舊不能用了', '怕秦軍搶走船和鍋子', '想讓軍隊走得輕鬆點'], a: 0, why: '第五段：士兵看了都明白「沒有船可以回去……一定要打贏，不能後退」。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '比較宋義和項羽的做法，下面哪一個說法最正確？', opts: ['宋義拖延，項羽決心往前', '宋義勇敢，項羽很害怕', '兩人都不想去救趙國', '兩人都很快就出兵了'], a: 0, why: '第二段宋義停了四十多天不前進；第三到五段項羽下定決心渡河、不留退路。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '項羽用「不留退路」讓士兵拚盡全力。你覺得做任何事都應該「破釜沉舟」嗎？什麼時候適合這樣做，什麼時候反而不適合？請說明理由。',
        ref: '我覺得不是每件事都適合。像比賽前專心練習，把會分心的東西收起來，可以讓自己更專心，這時候適合。可是如果是很危險的事，或還不知道自己做不做得到，就應該留一點退路，像爬山時一定要記得預留回程的時間。',
        rubric: ['表明是否每件事都適合', '舉出適合的情況', '舉出不適合的情況並說明理由'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「破釜沉舟」的「釜」是什麼？', opts: ['煮飯的鍋子', '渡河的小船', '打仗的盔甲', '裝水的水壺'], a: 0, why: '「釜」是古代煮飯的鍋子；「舟」才是船。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '陳大哥想開一家自己的麵包店，已經準備了好幾年。他把存了十年的錢全部拿出來，辭掉了原本穩定的工作，還把家搬到店的樓上，每天清晨四點就起床揉麵團。他說：「我已經沒有別的路可以回頭了，一定要把這家店做好！」', q: '陳大哥的做法，最適合用哪個成語形容？', opts: ['破釜沉舟', '紙上談兵', '望梅止渴', '首鼠兩端'], a: 0, why: '陳大哥辭掉工作、拿出所有積蓄，不留退路，全力以赴，就是破釜沉舟。首鼠兩端是猶豫不決，剛好相反。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈日記〉今天要去參加作文比賽，我心想：「寫不好也沒關係，反正下次還有機會。」我帶著破釜沉舟的輕鬆心情，隨便寫一寫就交卷了。', q: '日記裡的「破釜沉舟」用得恰當嗎？', opts: ['不恰當，他留著退路，沒有拚盡全力', '恰當，因為他心情很輕鬆', '恰當，因為他很快就交卷了', '不恰當，因為作文比賽不用坐船'], a: 0, why: '破釜沉舟是不留退路、全力以赴。日記裡的人想著「下次還有機會」，隨便寫一寫，剛好相反。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '這些成語跟「破釜沉舟」是什麼關係？配起來。', pairs: [['背水一戰', '近義成語'], ['急流勇退', '反義成語'], ['刻舟求劍', '意思無關']], why: '背水一戰也是下定決心一戰；急流勇退是在順利時及早退出，相反；刻舟求劍是不知變通，無關。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '項羽把退路切斷，讓自己只能往前。想一件你想全力完成的事，你可以「切斷」哪些會讓你分心或想放棄的東西？請說說你的做法，以及要注意的地方。',
        ref: '我想在一個月內練好跳遠。我會把放學後玩手機遊戲的時間改成練習時間，請媽媽先幫我保管手機。不過我也要注意不能練到受傷，累了還是要休息。',
        rubric: ['說出一件想全力完成的事', '說出要切斷的分心來源與做法', '想到要注意的地方（例如安全、休息）'] }
    ],
    xq: [
      { id: 'x1', k: 'judge', d: 1, type: 'tf', q: '「哥哥說要破釜沉舟，報名比賽後只練了一天，覺得不好玩就退出了。」這句話的「破釜沉舟」用得恰當。', a: false, why: '練一天就退出，沒有下定決心、全力以赴，不是破釜沉舟。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '小芸的籃球隊在冠軍賽落後十分，只剩最後一節。教練在暫停時說：「我們不保留體力了，所有主力都上場，全場緊迫盯人，不管輸贏都拚到最後一秒！」隊員們互相擊掌，衝回場上，最後真的追平比分，還在延長賽贏了。', q: '教練和球員在最後一節的決心，最適合用哪個成語形容？', opts: ['破釜沉舟', '黔驢技窮', '望梅止渴', '紙上談兵'], a: 0, why: '不保留、不留退路，全力拚到最後，是破釜沉舟。' }
    ]
  },
  {
    id: 'cy045', lv: 2, word: '門庭若市', zhuyin: 'ㄇㄣˊ ㄊㄧㄥˊ ㄖㄨㄛˋ ㄕˋ', src: '《戰國策．齊策一》',
    quote: '令初下，群臣進諫，門庭若市',
    facts: ['語出《戰國策．齊策一》，人物是戰國時代齊國的大夫鄒忌和齊威王｜教育部《成語典》', '鄒忌問妻、妾和客人自己和城北徐公誰美，三人都說他美；他發覺這是出於偏愛、畏懼和有求於他｜教育部《成語典》典故說明', '齊威王下令獎勵進諫的人；命令剛發布時，進諫的人多得像市集，一年後想說也沒什麼可說了｜《戰國策．齊策一》、教育部《成語典》典故說明'],
    story: [
      '戰國時代，齊國有一位大夫叫鄒忌，個子高、長得很英俊。有一天早上，他穿好衣服、戴好帽子，對著鏡子照了又照，問妻子：「我跟城北的徐公比，誰比較好看？」妻子說：「當然是你好看，徐公怎麼比得上你！」',
      '徐公是齊國有名的美男子，鄒忌有點不相信，又去問他的妾，妾也說：「徐公哪裡比得上您呢？」第二天，有客人來拜訪，鄒忌又問了一次，客人也說：「徐公沒有您好看。」',
      '過了幾天，徐公本人來了。鄒忌仔細看了看他，又照照鏡子，發現自己差得遠了。晚上，他躺在床上想：「妻子說我好看，是因為偏愛我；妾說我好看，是因為怕我；客人說我好看，是因為有事想求我。」',
      '鄒忌去見齊威王，把這件事說給國王聽，接著說：「齊國這麼大，宮裡的人都偏愛大王，朝廷的大臣都怕大王，全國的人都有事想求大王。這樣看來，大王聽到的好話一定很多，真話卻很少啊！」',
      '齊威王覺得很有道理，就下了一道命令：「能當面指出我錯誤的，得上等獎賞；上書勸我的，得中等獎賞；在大街上議論我的過錯、讓我聽到的，得下等獎賞。」',
      '命令一發布，來宮裡提意見的大臣一個接著一個，宮門前熱鬧得像市場一樣，這就是「門庭若市」。幾個月以後，還有人偶爾來提意見；一年以後，大家想說，也沒有什麼可說的了。鄰近的國家聽說了，都來朝見齊國。',
      '後來，「門庭若市」就用來比喻上門的人非常多，熱鬧得像市場一樣。'
    ],
    mean: '門口和庭院裡來往的人很多，像市集一樣熱鬧。比喻上門來的人非常多。',
    usage: ['用在形容一個地方（家、店、攤位、辦公室）上門的人很多、很熱鬧。', '近義成語有「車馬盈門」「絡繹不絕」；反義成語是「門可羅雀」「門庭冷落」。', '它說的是「上門的人多」，不是說地方很大或東西很多。'],
    misuse: [],
    eg: ['這家新開的豆花店口碑很好，每天下午都門庭若市，要排隊半小時。', '園遊會那天，我們班的抽獎攤位門庭若市，獎品不到中午就送光了。'],
    syn: ['車馬盈門', '絡繹不絕', '戶限為穿'], ant: ['門可羅雀', '門庭冷落'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '鄒忌問了哪三種人「我和徐公誰比較好看」？', opts: ['妻子、妾和客人', '國王、大臣和百姓', '父親、母親和兄弟', '老師、同學和鄰居'], a: 0, why: '第一、二段：他先問妻子，再問妾，第二天又問客人。' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '鄒忌認為客人說他好看，是因為什麼？', opts: ['客人有事想求他', '客人真的覺得他好看', '客人沒見過徐公', '客人怕他生氣'], a: 0, why: '第三段：「客人說我好看，是因為有事想求我。」怕他的是妾。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '鄒忌講自己問美醜的事，是想提醒齊威王什麼？', opts: ['大王身邊的人可能只說好話', '大王應該每天多照照鏡子', '大王應該請城北的徐公來當官', '大王長得沒有徐公好看'], a: 0, why: '第四段：鄒忌把自己的經驗推到國王身上——大王聽到的好話很多，真話卻很少。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '「一年以後，大家想說也沒有什麼可說了」，最可能的原因是什麼？', opts: ['齊威王已經把該改的錯都改了', '大臣們都怕被處罰，不敢再說了', '齊威王後來把獎賞都取消了', '大臣們都離開齊國了'], a: 0, why: '大家一直提意見，齊威王一直改，該改的都改好了，所以沒什麼可說；鄰國也因此來朝見齊國。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '齊威王用獎賞鼓勵大家說真話。如果你是班長，想知道同學對班上活動的真實意見，你會用什麼方法？請參考故事說明理由。',
        ref: '我會在教室後面放一個意見箱，大家可以不寫名字投進去，也會在班會時說：「提出好建議的人，可以優先選座位。」就像齊威王一樣，讓大家知道說真話不會被討厭，還會被感謝，大家才敢說。',
        rubric: ['提出具體的方法', '說明方法怎麼讓人敢說真話', '能參考故事中的做法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「門庭若市」的「若」是什麼意思？', opts: ['好像', '如果', '很多', '你'], a: 0, why: '「若」在這裡是「好像」，門庭若市就是門口庭院熱鬧得好像市集。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '學校圖書館新進了一整櫃的漫畫版科學書。消息一傳開，下課鐘一響，就有一大群同學跑進圖書館，借書櫃台前排了長長的隊伍，連平常很少來的高年級哥哥姊姊也來了。圖書館阿姨笑著說：「開館這麼多年，第一次這麼熱鬧！」', q: '圖書館這幾天的情形，最適合用哪個成語形容？', opts: ['門庭若市', '門可羅雀', '破釜沉舟', '紙上談兵'], a: 0, why: '來借書的人非常多，熱鬧得像市場，就是門庭若市。門可羅雀是冷清，剛好相反。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈新聞〉颱風來襲，夜市的攤販都沒有營業，街上空空蕩蕩，只剩下風雨聲。記者在現場報導：「今晚的夜市門庭若市。」', q: '記者用「門庭若市」恰當嗎？', opts: ['不恰當，夜市冷冷清清沒有人', '恰當，因為夜市本來就是市場', '恰當，因為夜市的攤位很多', '不恰當，門庭若市只能說家裡'], a: 0, why: '門庭若市是上門的人多。夜市空空蕩蕩，應該用反義的門可羅雀。它也不只能說家裡，店家、攤位都可以用。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '這些成語跟「門庭若市」是什麼關係？配起來。', pairs: [['車馬盈門', '近義成語'], ['門可羅雀', '反義成語'], ['破釜沉舟', '意思無關']], why: '車馬盈門是門口停滿客人的車馬，相近；門可羅雀是冷清得能張網捕鳥，相反；破釜沉舟是不留退路，無關。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '齊威王願意聽批評，才讓宮門前「門庭若市」。想一想，如果有人指出你的缺點，你通常有什麼反應？你可以怎麼做，讓別人更願意對你說真話？',
        ref: '以前同學說我的字很潦草，我會不高興，覺得他在找麻煩。現在我想，他願意說真話是在幫我。以後有人指出我的缺點，我會先說「謝謝你告訴我」，再想想要怎麼改，這樣大家以後才敢跟我說。',
        rubric: ['說出自己被指出缺點時的反應', '提出讓別人更願意說真話的做法', '能連結故事中齊威王的做法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '這間診所的醫生很有耐心，每天一開門就＿＿＿＿，候診室坐滿了病人。', opts: ['門庭若市', '門可羅雀', '指鹿為馬', '紙上談兵'], a: 0, why: '候診室坐滿了人，是上門的人多，用門庭若市。門可羅雀是冷清，和「坐滿了病人」矛盾。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '社區活動中心新開了免費的週末親子手作課。第一個星期六，一大早門口就排滿了帶著孩子的家長，報名表一下子就寫滿了三張，連走廊都擠得水洩不通。活動中心的主任說：「我們從來沒想到會來這麼多人！」', q: '活動中心那天的情形，可以用哪個成語形容？', opts: ['門庭若市', '精衛填海', '破釜沉舟', '黔驢技窮'], a: 0, why: '上門的人多到擠滿走廊，是門庭若市。' }
    ]
  },
  {
    id: 'cy048', lv: 2, word: '一字千金', zhuyin: 'ㄧ ㄗˋ ㄑㄧㄢ ㄐㄧㄣ', src: '《史記．呂不韋列傳》',
    quote: '延諸侯游士賓客有能增損一字者予千金',
    facts: ['典出《史記．呂不韋列傳》｜教育部《成語典》', '呂不韋原本是商人，後來當上秦國丞相，門客多達三千人｜教育部《成語典》典故說明', '呂不韋讓門客把見聞寫下來，編成二十多萬字的《呂氏春秋》，公布在咸陽城門，懸賞千金請人增減一字｜《史記．呂不韋列傳》、教育部《成語典》典故說明', '《成語典》典故說明：因為呂不韋權勢很大，沒有人敢出面批評｜教育部《成語典》典故說明', '注音本音ㄧ ㄗˋ，「一」口語變調讀ㄧˊ｜教育部《成語典》注音'],
    story: [
      '戰國時代末期，秦國有一位丞相，叫做呂不韋。他年輕時是個做生意的商人，很會看準機會，後來幫助一位秦國王子當上國王，自己也成了秦國最有權力的大臣之一。',
      '那時候，各國有權有勢的人都喜歡招待讀書人和有才能的人，稱為「門客」。呂不韋也不落人後，他的家裡最多住了三千位門客。',
      '呂不韋想：「我也要編一本能流傳後世的書！」他請門客們把自己知道的、聽過的道理都寫下來，再整理在一起，編成了一本二十多萬字的大書，從天地萬物到古今的事情都寫在裡面，取名叫《呂氏春秋》。',
      '書編好以後，呂不韋做了一件很特別的事。他把整本書公布在秦國都城咸陽的城門口，旁邊掛著一千金，還貼出告示：「各國的學者、客人，誰能在這本書裡加一個字或刪一個字，這一千金就送給他！」',
      '消息傳開以後，來看書的人很多，可是過了好久，一直沒有人站出來說要改。有人說，這本書寫得太好了，挑不出毛病；也有人說，呂不韋權勢那麼大，誰敢去改他的書呢？',
      '不管原因是什麼，「改一個字就能得到千金」這件事流傳了下來。後來，人們用「一字千金」比喻文章用字精當、結構嚴謹，一個字都不能改；也用來形容價值極高的作品，或稱讚書法作品一個字就值千金。'
    ],
    mean: '能改動一個字的人，就給他千金。比喻文辭精當、結構嚴謹；也形容價值極高的作品，或書法上一個字價值千金。',
    usage: ['用在稱讚文章、詩詞寫得非常好，或作品、書法價值很高（褒義）。', '說的是「文字、作品」好，不是「守信用」；稱讚人說到做到要用「一諾千金」。', '近義成語有「字字珠璣」，反義成語是「驢鳴犬吠」。'],
    misuse: ['「他答應的事一定做到，真是一字千金。」✗　說到做到是「一諾千金」；一字千金是稱讚文章或作品寫得好。'],
    eg: ['這首短詩只有二十個字，卻寫出了秋天的寂寞，每個字都用得恰到好處，真是一字千金。', '好的標語要做到一字千金，多一個字嫌囉嗦，少一個字又說不清楚。'],
    syn: ['字字珠璣'], ant: ['驢鳴犬吠'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '呂不韋把《呂氏春秋》公布在哪裡？', opts: ['咸陽的城門口', '自己家的大廳裡', '秦王的宮殿裡', '趙國的城牆上'], a: 0, why: '第四段：「他把整本書公布在秦國都城咸陽的城門口。」' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '《呂氏春秋》是呂不韋一個人花了很多年寫成的。', a: false, why: '第三段：是他「請門客們」把知道的道理寫下來，再整理成書。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '呂不韋為什麼要掛出千金，請人改一個字？', opts: ['想顯示這本書好到一字難改', '他想把黃金送給窮苦的人', '他找不到人幫忙校對錯字', '國王命令他一定要這樣做'], a: 0, why: '敢用千金懸賞改一個字，是要顯示這本書寫得非常完整、精當，好讓書和自己都更有名。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '文中說沒有人站出來改書，有哪兩種可能的原因？', opts: ['書寫得很好；呂不韋權勢太大', '賞的黃金太少；書寫得太難讀', '咸陽太遠；告示貼得太高', '大家都不識字；書被藏起來了'], a: 0, why: '第五段：有人說書寫得太好、挑不出毛病；也有人說呂不韋權勢大、沒人敢改。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '有人認為沒人改書是因為書寫得好，也有人認為是大家怕呂不韋。你比較相信哪一種？如果是你，你會怎麼判斷一本書是不是真的「一字千金」？',
        ref: '我比較相信是大家怕呂不韋，因為二十多萬字的大書，很難一個字都不能改；可是他權勢那麼大，就算看到可以改的地方，大家也可能不敢說。我會看很多人讀過以後的意見，尤其是不怕他的人怎麼說，才能判斷這本書是不是真的好。',
        rubric: ['選出一種說法並說出理由', '理由能用到故事內容（權勢大、書很長等）', '提出判斷作品好壞的合理方法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「一字千金」最常用來稱讚什麼？', opts: ['文章或作品寫得非常好', '一個人說話很守信用', '一個東西的價錢很便宜', '一個人寫字速度很快'], a: 0, why: '一字千金比喻文辭精當，或作品價值極高。稱讚守信用是一諾千金。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '學校舉辦標語比賽，主題是「節約用水」。很多同學寫了長長的一大段，只有小芸寫了短短十個字：「一滴不浪費，滴滴都是寶。」評審說，這十個字唸起來順口，意思清楚，換掉任何一個字都不會更好，所以給她第一名。', q: '評審對小芸標語的評價，最適合用哪個成語形容？', opts: ['一字千金', '一諾千金', '門庭若市', '望梅止渴'], a: 0, why: '評審說換掉任何一個字都不會更好，是稱讚用字精當，用一字千金。一諾千金是守信用，字很像但意思不同。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈班會紀錄〉班長上週答應要幫大家借到體育館，今天真的借到了。副班長說：「班長真是一字千金，答應的事都做到了！」', q: '副班長用「一字千金」恰當嗎？', opts: ['不恰當，說到做到應該說一諾千金', '恰當，因為班長真的借到體育館', '恰當，因為班長說的話很有價值', '不恰當，因為班長並沒有寫文章'], a: 0, why: '稱讚說到做到要用「一諾千金」；一字千金是稱讚文章或作品。這兩個成語很容易混淆。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '這些成語跟「一字千金」是什麼關係？配起來。', pairs: [['字字珠璣', '近義成語'], ['驢鳴犬吠', '反義成語'], ['一諾千金', '字很像，意思不同']], why: '字字珠璣是每個字都像珍珠，相近；驢鳴犬吠比喻文章拙劣，相反；一諾千金是守信用，只是字很像。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '呂不韋懸賞千金請人改字。你寫作文或做報告時，可以怎麼檢查，讓自己的文字更接近「一字千金」：不多一個字，也不少一個字？',
        ref: '我寫完作文後，會小聲唸一遍，唸起來卡卡的句子就改。我也會找出重複的話，例如「然後」寫了好多次，就刪掉一些。最後檢查每一段有沒有回答到題目，跟題目沒關係的句子就刪掉。',
        rubric: ['提出至少兩個具體的檢查方法', '方法能讓文字更精簡或更清楚', '說明為什麼這樣檢查有用'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '這篇得獎的短文沒有一句廢話，每個詞都用得很精準，可說是＿＿＿＿。', opts: ['一字千金', '一諾千金', '門可羅雀', '紙上談兵'], a: 0, why: '稱讚文章用字精準，用一字千金。一諾千金是守信用，放進句子不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '國語老師：「這首詩只有四句，可是每一個字都換不掉，難怪流傳了一千多年。」\n小安：「我懂了，這就是一字千金！」', q: '小安說的「一字千金」用得恰當。', a: true, why: '每個字都換不掉，是文辭精當，用一字千金恰當。' }
    ]
  },

  // ==================== L3 寓意加深 ====================
  {
    id: 'cy051', lv: 3, word: '臥薪嘗膽', zhuyin: 'ㄨㄛˋ ㄒㄧㄣ ㄔㄤˊ ㄉㄢˇ', src: '《史記．越王句踐世家》',
    quote: '坐臥即仰膽，飲食亦嘗膽也',
    facts: ['典出《史記．越王句踐世家》，主角是春秋末年的越王句踐｜教育部《成語典》', '句踐在會稽之戰敗給吳王夫差，被困在會稽；後來得到夫差赦免，回到越國｜教育部《成語典》典故說明', '句踐在座位旁放著苦膽，坐著躺著都抬頭看它，吃飯時也嘗一嘗，問自己：「你忘了會稽的恥辱嗎？」｜《史記．越王句踐世家》', '句踐親自耕作，夫人親自織布，吃飯不加肉，衣服不講究｜《史記．越王句踐世家》', '比喻刻苦自勵，發奮圖強｜教育部《成語典》釋義'],
    story: [
      '春秋時代末年，南方有兩個互相競爭的國家：吳國和越國。有一次，越王句踐帶兵和吳王夫差打仗，結果大敗，只剩下五千名士兵，被吳軍團團圍在會稽山上。',
      '眼看越國就要滅亡了，句踐只好向夫差求和，答應從此聽吳國的話。夫差最後放過了他，讓他回到越國。可是，打了敗仗、向敵人低頭的屈辱，句踐一天也忘不了。',
      '回國以後，句踐做了兩件奇怪的事。晚上，他不睡柔軟的床，而是躺在粗硬的柴草上，扎得全身不舒服，提醒自己不能貪圖安逸。他又在座位旁邊放了一顆苦膽，不管是坐著還是躺下，都抬頭看看它；吃飯以前，也先嘗一口那苦得讓人皺眉的膽。',
      '每次嘗到苦味，他就問自己：「你忘了在會稽受的恥辱嗎？」',
      '句踐不只是在心裡記著，也用行動改變自己。他親自下田耕種，他的夫人親自織布；吃飯不加肉，穿衣服也不講究。他尊重有才能的人，好好招待來訪的客人，幫助生活困苦的百姓，和大家一起辛苦工作。越國的人看到國王這麼努力，也都願意跟著他一起打拚。',
      '就這樣，越國一年一年慢慢強大起來。經過很多年的努力，句踐終於打敗了吳國，洗刷了當年的恥辱。',
      '後來，人們把「睡柴草」和「嘗苦膽」合在一起，說成「臥薪嘗膽」，用來比喻刻苦自勵、發奮圖強：不忘記過去的失敗，努力讓自己變得更強。'
    ],
    mean: '睡在柴草上，嘗苦膽，提醒自己不忘恥辱。比喻刻苦自勵、發奮圖強。',
    usage: ['用在為了雪恥或達成目標，長期刻苦努力、讓自己變強的時候（褒義）。', '重點是「記住失敗、長期刻苦奮發」；只是吃了苦的東西，或只是一時很累，不能說臥薪嘗膽。', '近義成語有「發奮圖強」，反義成語有「醉生夢死」「苟且偷生」。'],
    misuse: [],
    eg: ['去年輸掉冠軍賽以後，球隊臥薪嘗膽，每天提早一小時練球，今年終於奪冠。', '哥哥第一次檢定沒通過，他臥薪嘗膽苦讀半年，第二次拿到了高分。'],
    syn: ['發奮圖強', '奮發圖強'], ant: ['醉生夢死', '苟且偷生'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '句踐吃飯以前，會先做什麼？', opts: ['嘗一口苦膽', '喝一杯熱湯', '向夫差行禮', '到田裡耕種'], a: 0, why: '第三段：「吃飯以前，也先嘗一口那苦得讓人皺眉的膽。」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '句踐為什麼要睡在柴草上？', opts: ['提醒自己不能貪圖安逸', '越國沒有錢買床', '柴草睡起來比較涼快', '他想把柴草曬乾'], a: 0, why: '第三段：柴草扎得全身不舒服，是要「提醒自己不能貪圖安逸」。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '越國最後能打敗吳國，最主要是因為什麼？', opts: ['國王和百姓長期刻苦努力', '吳王把國家讓給了句踐', '句踐吃了苦膽後力氣變大', '吳國突然發生了大地震'], a: 0, why: '把第三到六段合起來：句踐記住恥辱、親自勞動、照顧百姓，大家一起打拚，越國才一年一年強大起來。' },
      { id: 'r4', p: 4, d: 3, type: 'open', q: '句踐記住了失敗的恥辱，努力讓自己變強。你覺得「一直記著失敗」是好事還是壞事？請用故事內容和自己的經驗說明。',
        ref: '我覺得要看怎麼記。句踐記著失敗，是為了提醒自己努力，所以是好事。可是如果只是一直難過、生氣，什麼都不做，就是壞事。我上次跳繩比賽輸了，我把成績貼在書桌前，提醒自己每天練習，這次就進步了。',
        rubric: ['表明看法（好、壞或要看情況）', '用故事內容說明理由', '舉出自己的經驗'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「臥薪嘗膽」的「薪」是什麼？', opts: ['柴草', '薪水', '鹽巴', '苦膽'], a: 0, why: '「薪」是柴草，「臥薪」就是睡在柴草上。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '去年的全市作文比賽，小琳只得到佳作，她難過了好幾天。後來她把評審寫的缺點抄在小卡片上，貼在書桌前。這一年，她每天讀一篇文章、每週寫一篇短文請老師批改，連寒假也沒有停。今年再參加比賽，她拿到了第一名。', q: '小琳這一年的做法，最適合用哪個成語形容？', opts: ['臥薪嘗膽', '破釜沉舟', '紙上談兵', '門庭若市'], a: 0, why: '小琳記住失敗、把缺點貼在眼前，長期刻苦努力，就是臥薪嘗膽。破釜沉舟重在一次下定決心、不留退路，不是長期記著失敗苦練。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈日記〉今天媽媽煮了苦瓜排骨湯，苦瓜好苦，我皺著眉頭一口一口吃完。我真是臥薪嘗膽啊！', q: '日記裡的「臥薪嘗膽」用得恰當嗎？', opts: ['不恰當，只是吃苦瓜，不是發奮', '恰當，因為苦瓜真的非常苦', '恰當，因為他把苦瓜都吃完了', '不恰當，因為苦瓜湯不是膽汁'], a: 0, why: '臥薪嘗膽是不忘失敗、刻苦自勵，不是吃苦的食物。成語是比喻，問題也不在膽汁。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '這些成語跟「臥薪嘗膽」是什麼關係？配起來。', pairs: [['發奮圖強', '近義成語'], ['醉生夢死', '反義成語'], ['望梅止渴', '意思無關']], why: '發奮圖強是下定決心努力變強，相近；醉生夢死是糊里糊塗過日子，相反；望梅止渴是用空想安慰自己，無關。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '句踐用「柴草」和「苦膽」提醒自己。想一次你失敗或不滿意的經驗，你可以用什麼「提醒物」或方法，讓自己記得要努力，而不是只是難過？',
        ref: '我上次月考數學粗心錯了好多題。我可以把錯的題目抄在一本「錯題本」裡，每天睡前看兩題，提醒自己算完要檢查。錯題本就像句踐的苦膽，提醒我不要再犯一樣的錯。',
        rubric: ['說出一次失敗或不滿意的經驗', '提出具體的提醒物或方法', '說明這個方法怎麼幫助自己努力'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '上次比賽輸給隔壁班以後，我們＿＿＿＿，每天午休都練習傳球，這次終於贏回來了。', opts: ['臥薪嘗膽', '醉生夢死', '望梅止渴', '按圖索驥'], a: 0, why: '記住失敗、刻苦練習、終於贏回來，用臥薪嘗膽。醉生夢死意思相反，其他兩個放進句子不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '一家小餅乾店曾經因為味道不好，被客人在網路上批評，生意一落千丈。老闆沒有放棄，他把每一則批評都印出來貼在廚房牆上，三年來天天研究配方，自己試吃了上千塊餅乾。現在他的餅乾得了全國烘焙比賽的金牌，店門口天天大排長龍。', q: '老闆這三年的努力，最適合用哪個成語形容？', opts: ['臥薪嘗膽', '門庭若市', '一字千金', '黔驢技窮'], a: 0, why: '把批評貼在眼前、三年刻苦研究，是臥薪嘗膽。門庭若市只是描寫現在客人多，不是在說他的努力。' }
    ]
  },
  {
    id: 'cy054', lv: 3, word: '按圖索驥', zhuyin: 'ㄢˋ ㄊㄨˊ ㄙㄨㄛˇ ㄐㄧˋ', src: '《漢書．梅福傳》',
    quote: '猶察伯樂之圖，求騏驥於市，而不可得',
    facts: ['語本《漢書．梅福傳》，人物是西漢成帝時的梅福｜教育部《成語典》', '當時外戚王鳳掌握朝政；梅福上書說，朝廷想用夏商周三代的老辦法選人才，就像拿伯樂的圖去市場找千里馬，一定找不到｜教育部《成語典》典故說明', '成帝沒有採納，仍舊怠於政事，外戚因此亂政｜教育部《成語典》典故說明', '有兩個意思：做事拘泥成規、不知變通；也比喻按照掌握的線索辦事｜教育部《成語典》釋義、用法說明'],
    story: [
      '西漢漢成帝的時候，皇帝的舅舅王鳳掌握了朝廷大權，很多事情都由他決定。大臣們心裡不滿，卻不敢說出來。',
      '這時候，有一位叫梅福的人，以前在地方上做過小官。他雖然已經不當官了，但很擔心國家，就一次又一次寫信給皇帝，勸皇帝多聽不同的意見，好好挑選真正有才能的人。',
      '梅福在信裡打了一個比方。他說，古時候有一位很會看馬的人叫伯樂，他能一眼看出哪一匹是能跑千里的好馬。假如有人拿著伯樂畫的「好馬圖」，跑到市場上，一匹一匹照著圖去比對，想找出千里馬，那是一定找不到的。',
      '為什麼呢？因為真正的好馬，不會長得跟圖上一模一樣。伯樂會看的，是馬的精神、力氣和跑起來的樣子，這些都不是一張圖畫得出來的。',
      '梅福接著說：現在朝廷想照著古代夏、商、周三個朝代的老辦法來選人才，就像拿著伯樂的圖到市場找馬一樣。時代不同了，只照著老規矩比對，怎麼找得到今天真正有用的人呢？',
      '可惜，漢成帝沒有接受梅福的建議，還是整天玩樂，不太管國家大事，朝廷的權力也越來越落到外戚手裡。',
      '後來，人們從梅福的這段話，引申出「按圖索驥」這個成語。它原本比喻做事拘泥死板、不知變通；後來也用來比喻照著掌握到的線索，一步一步去找、去做事。'
    ],
    mean: '照著圖畫去尋找好馬。比喻做事拘泥成規、呆板不知變通；後來也比喻按照掌握的線索去找、去辦事。',
    usage: ['第一個意思是批評做事死板、只照規矩比對，不懂變通（貶義），近義成語有「刻舟求劍」「膠柱鼓瑟」。', '第二個意思是照著線索去找、去做，例如：警察按圖索驥找到了失物。這時不是批評，近義成語有「順藤摸瓜」，反義成語有「大海撈針」。', '要看句子的情境，判斷它是在批評死板，還是在說照著線索做事。'],
    misuse: [],
    eg: ['他只會照著食譜按圖索驥，少了一樣材料就不知道怎麼辦。', '我們照著學長畫的地圖按圖索驥，很快就找到了藏在校園裡的寶藏盒。'],
    syn: ['刻舟求劍', '膠柱鼓瑟', '順藤摸瓜'], ant: ['大海撈針', '無跡可尋'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '梅福寫信給皇帝，是想勸皇帝做什麼？', opts: ['好好挑選真正有才能的人', '趕快到市場去買千里馬', '請伯樂來教大家畫馬', '讓王鳳掌管更多事情'], a: 0, why: '第二段：他勸皇帝多聽不同的意見，「好好挑選真正有才能的人」。' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '為什麼拿著伯樂畫的圖到市場，一定找不到千里馬？', opts: ['好馬的精神，圖畫不出來', '市場上根本沒有在賣馬', '伯樂畫的圖已經弄丟了', '千里馬都被藏起來了'], a: 0, why: '第四段：伯樂看的是馬的精神、力氣和跑起來的樣子，「都不是一張圖畫得出來的」。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '梅福說的「拿圖找馬」，是在比喻朝廷的哪一種做法？', opts: ['照古代老辦法挑選人才', '到市場去買很多好馬', '請畫家幫忙畫好馬圖', '讓伯樂到朝廷當大官'], a: 0, why: '第五段：朝廷想照夏、商、周的老辦法選人才，「就像拿著伯樂的圖到市場找馬一樣」。' },
      { id: 'r4', p: 4, d: 3, type: 'open', q: '「按圖索驥」可以是批評，也可以不是。你覺得什麼時候「照著圖、照著規則做」是好方法？什麼時候會變成死板？請舉例說明。',
        ref: '第一次組裝積木時，照著說明書一步一步做是好方法，因為不容易出錯。可是如果說明書少印了一頁，還一直只看說明書、不肯自己想辦法，就變成死板了。就像梅福說的，好馬不會長得跟圖一模一樣，要懂得看實際情況。',
        rubric: ['舉出照規則做是好方法的例子', '舉出變成死板的例子', '能連結故事中「圖」和「真馬」的道理'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「按圖索驥」的「驥」是什麼？', opts: ['好馬、千里馬', '一張地圖', '一條線索', '一位畫家'], a: 0, why: '「驥」是好馬、千里馬，「索」是尋找。按圖索驥就是照著圖找好馬。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '美勞課老師要大家做紙風車，發下一張示範圖。阿寶照著圖一步一步折，可是他拿到的紙比示範用的小了一半，折到最後，風車怎麼也轉不起來。老師提醒他把摺線的位置調整一下，他卻堅持：「圖上就是這樣畫的，我不能改。」', q: '阿寶的做法，最適合用哪個成語形容？', opts: ['按圖索驥', '臥薪嘗膽', '門庭若市', '聞一知十'], a: 0, why: '紙的大小已經不一樣，阿寶還堅持照圖、不肯調整，是拘泥成規的按圖索驥。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈新聞〉一位阿嬤在公園遺失了錢包。警察調出路口的監視器畫面，照著畫面上的路線一路追查，按圖索驥，終於在一家便利商店找回了錢包。', q: '新聞裡的「按圖索驥」用得恰當嗎？', opts: ['恰當，這裡是照著線索一步步去找', '不恰當，按圖索驥只能用來批評人', '不恰當，警察沒有拿著一張地圖', '恰當，因為阿嬤的錢包很珍貴'], a: 0, why: '按圖索驥也可以指「按照掌握的線索辦事」，警察照監視器線索找回錢包，用得恰當，不是批評。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '「按圖索驥」用來批評人不知變通時，下面哪一個成語意思最接近？', opts: ['刻舟求劍', '隨機應變', '臥薪嘗膽', '一字千金'], a: 0, why: '刻舟求劍也是不知變通，《成語典》列為近義。隨機應變意思相反。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '照著說明書、食譜、地圖做事，有時候很有用，有時候卻行不通。說一件你照著「圖」做事的經驗，當情況和圖不一樣時，你是怎麼調整的（或你以後會怎麼調整）？',
        ref: '我照著食譜做鬆餅，食譜說要加兩顆蛋，可是家裡只剩一顆。我就把麵粉和牛奶也減少一半，做成小份量的鬆餅。我發現照著食譜做很方便，但遇到不一樣的情況，要想想原因再調整。',
        rubric: ['說出一件照著圖、食譜或說明做事的經驗', '說出情況不一樣的地方', '說出合理的調整方法'] }
    ],
    xq: [
      { id: 'x1', k: 'judge', d: 1, type: 'tf', q: '「爸爸照著舊相片背面寫的地址按圖索驥，終於找到了小時候住過的老房子。」這句話的「按圖索驥」用得恰當。', a: true, why: '照著相片背面的地址這條線索去找，是按圖索驥「按照線索辦事」的意思，用得恰當。' },
      { id: 'x2', k: 'sit', d: 3, type: 'mc', ctx: '班上要選一位同學代表參加說故事比賽。小志提議：「去年得獎的人戴眼鏡、個子高、說話很大聲，我們就照這三個條件選吧！」結果選出來的同學雖然符合條件，卻很容易緊張，上台時說得結結巴巴。導師說：「選人要看真正的能力，不能只照著一張條件表比對。」', q: '小志選人的方法，最像哪一個成語的意思？', opts: ['按圖索驥', '三顧茅廬', '門可羅雀', '臥薪嘗膽'], a: 0, why: '只照著外表條件比對，不看真正的能力，就像拿伯樂的圖找馬，是按圖索驥。三顧茅廬是誠心邀請人才，重點不同。' }
    ]
  },
  {
    id: 'cy058', lv: 3, word: '三顧茅廬', zhuyin: 'ㄙㄢ ㄍㄨˋ ㄇㄠˊ ㄌㄨˊ', src: '三國蜀．諸葛亮〈前出師表〉',
    quote: '三顧臣於草廬之中',
    facts: ['語本三國蜀．諸葛亮〈前出師表〉｜教育部《成語典》', '東漢末年，劉備駐軍新野，聽徐庶說南陽隆中的諸葛亮很有才能，親自去拜訪，去了三次才見到｜教育部《成語典》典故說明', '諸葛亮在〈前出師表〉說：先帝不嫌他身分卑微，三次到草屋來問他天下大事，他因此感動，答應為先帝奔走｜〈前出師表〉', '近義成語有「禮賢下士」「求賢若渴」｜教育部《成語典》辨識', '隨從嫌麻煩的對話是改寫時加上的（小說《三國演義》也有類似描寫）；史書只記劉備去了三次才見到諸葛亮｜《三國志．蜀書．諸葛亮傳》、改寫說明'],
    story: [
      '東漢末年，天下分裂，各地英雄都想闖出一番事業。劉備是其中一位，他有心要讓國家重新安定，可是身邊缺少一位能出主意、看清天下大勢的人才。',
      '那時劉備帶兵駐守在新野。一位叫徐庶的朋友告訴他：「隆中住著一個人，叫諸葛亮，人稱『臥龍』，是真正有大才能的人。」劉備高興的說：「那請你帶他來見我吧！」',
      '徐庶搖搖頭：「這樣的人，只能您親自去拜訪，不能叫他來。」劉備聽了，二話不說，就出發了。',
      '諸葛亮住在山坡上一間用茅草蓋的小屋。劉備第一次去，沒見到他；第二次去，又沒見到。跟著去的人開始不耐煩了，說：「一個住在鄉下的讀書人，值得您一次又一次跑來嗎？」劉備卻說：「真正的人才，本來就不容易見到。」',
      '劉備第三次來到茅屋，終於見到了諸葛亮。劉備誠懇的向他請教，諸葛亮把天下的情勢分析得清清楚楚，告訴劉備該往哪裡發展。劉備聽了非常佩服，覺得好像撥開了眼前的雲霧。',
      '諸葛亮被劉備的誠意感動，答應出來幫助他。從那以後，他用盡一生的心力輔佐劉備。很多年後，諸葛亮寫了〈出師表〉給劉備的兒子，裡面提到：先帝不嫌我出身低微，親自三次到草屋來看我，問我天下大事，我因此深深感動，決心為他奔走效力。',
      '後來，「三顧茅廬」就用來比喻真心誠意的一再邀請、拜訪有才能的人。'
    ],
    mean: '劉備三次到諸葛亮住的草屋拜訪，才見到他。比喻對賢才真心誠意的邀請、拜訪。',
    usage: ['用在誠心誠意、一次又一次去邀請或拜訪有才能的人（褒義）。', '重點是「誠心邀請人才」；只是去同一個地方好幾次，例如常去一家店，不能說三顧茅廬。', '近義成語有「禮賢下士」「求賢若渴」。'],
    misuse: [],
    eg: ['球隊想請退休的老教練回來帶隊，隊長三顧茅廬，終於感動了他。', '為了請書法老師來社團指導，校長幾次登門拜訪，可說是三顧茅廬。'],
    syn: ['禮賢下士', '求賢若渴'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '是誰告訴劉備，隆中住著一位叫諸葛亮的人才？', opts: ['徐庶', '曹操', '伯樂', '梅福'], a: 0, why: '第二段：「一位叫徐庶的朋友告訴他。」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '徐庶為什麼說「只能您親自去拜訪」？', opts: ['真正的人才，要用誠意去請', '諸葛亮生病了不能出門', '隆中的路太遠，徐庶不認得', '諸葛亮很不喜歡劉備'], a: 0, why: '有大才能的人不能隨便叫來，要親自拜訪才能表現誠意。後來諸葛亮也是被劉備的誠意感動（第六段）。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '諸葛亮最後願意出來幫助劉備，最主要的原因是什麼？', opts: ['被劉備一再拜訪的誠意感動', '劉備送給他很多貴重的禮物', '徐庶一直在旁邊拜託他', '他住的茅屋快要倒了'], a: 0, why: '第六段：「諸葛亮被劉備的誠意感動，答應出來幫助他。」〈出師表〉也說他「因此深深感動」。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '諸葛亮在〈出師表〉裡回憶這件事時，最強調劉備哪一點？', opts: ['不嫌他出身低，親自來請教', '帶兵打仗的時候非常勇敢', '家裡有非常多的錢財', '和徐庶是很要好的朋友'], a: 0, why: '第六段：先帝「不嫌我出身低微，親自三次到草屋來看我，問我天下大事」。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '跟著劉備去的人覺得不值得一直跑，劉備卻堅持要去。你覺得劉備這樣做值得嗎？如果去了三次還是沒見到，你覺得他應該繼續嗎？請說明理由。',
        ref: '我覺得值得，因為諸葛亮後來幫劉備分析天下大勢，還用一生輔佐他，比跑三次的辛苦重要多了。如果三次還沒見到，我覺得可以再試試看，但也可以寫信說明自己的誠意，或請徐庶幫忙聯絡，換個方法表達誠心。',
        rubric: ['表明值不值得並說出理由', '用故事內容當證據', '對「還沒見到要不要繼續」提出合理看法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「三顧茅廬」的「顧」是什麼意思？', opts: ['拜訪', '照顧', '回頭看', '顧客'], a: 0, why: '「顧」在這裡是拜訪；「茅廬」是茅草蓋的屋子。三顧茅廬就是三次到草屋拜訪。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '學校想成立管樂隊，可是缺一位指揮老師。校長聽說鎮上有一位退休的音樂老師很會教，就親自登門拜訪。第一次老師說年紀大了不想教，第二次又說身體不太好。校長第三次帶著全校學生寫的邀請卡片再去，老師終於被感動，答應每週來學校指導。', q: '校長請老師的過程，最適合用哪個成語形容？', opts: ['三顧茅廬', '門庭若市', '按圖索驥', '紙上談兵'], a: 0, why: '校長誠心一再拜訪，終於請到人才，就是三顧茅廬。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈日記〉學校旁邊新開了一家紅豆餅店，紅豆餅又香又甜。這個星期我已經三顧茅廬，每天放學都去買兩個。', q: '日記裡的「三顧茅廬」用得恰當嗎？', opts: ['不恰當，它是拜訪人才，不是買東西', '恰當，因為他真的去了好幾次', '恰當，因為那家店是新開的', '不恰當，因為他去的次數超過三次'], a: 0, why: '三顧茅廬是誠心邀請、拜訪人才，不是常去一家店。問題不在次數。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '下面哪一個成語，意思和「三顧茅廬」最接近？', opts: ['禮賢下士', '門可羅雀', '首鼠兩端', '指鹿為馬'], a: 0, why: '禮賢下士是尊敬、禮遇有才德的人，和三顧茅廬相近（《成語典》近義）。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '劉備用誠意請到了諸葛亮。如果你想邀請一位很厲害的同學加入你的小組或社團，可是他一開始拒絕了，你會怎麼表現你的誠意？',
        ref: '我會先問他為什麼拒絕，如果是怕太忙，我可以告訴他我們會怎麼分工，不會讓他太累。我也會說清楚我為什麼特別想請他，例如他很會畫圖，可以讓海報更好看。如果他還是不想，我也會尊重他的決定。',
        rubric: ['說出表達誠意的具體做法', '能考慮對方拒絕的原因', '知道要尊重對方最後的決定'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '為了邀請這位作家來學校演講，圖書館主任＿＿＿＿，寫了三封邀請信，還親自去拜訪。', opts: ['三顧茅廬', '門庭若市', '按圖索驥', '首鼠兩端'], a: 0, why: '一再寫信、親自拜訪，誠心邀請人才，用三顧茅廬。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '哥哥：「我想請隔壁班最會打鼓的阿明加入樂團，他拒絕兩次了，我明天要第三次去拜託他。」\n妹妹：「你這是三顧茅廬耶！」', q: '妹妹說的「三顧茅廬」用得恰當。', a: true, why: '哥哥誠心一再邀請有才能的阿明，用三顧茅廬恰當。' }
    ]
  },
  {
    id: 'cy061', lv: 3, word: '聞一知十', zhuyin: 'ㄨㄣˊ ㄧ ㄓ ㄕˊ', src: '《論語．公冶長》',
    quote: '回也聞一以知十，賜也聞一以知二',
    facts: ['語出《論語．公冶長》，人物是春秋時代的孔子和弟子子貢、顏回｜教育部《成語典》', '子貢是衛國人，顏回是魯國人｜教育部《成語典》典故說明', '孔子問子貢和顏回誰比較好；子貢說顏回聽一件能推知十件，自己只能推知兩件；孔子同意，認為自己和子貢都比不上顏回｜教育部《成語典》典故說明', '《成語典》辨析：「舉一反三」側重天資聰慧靈敏，「聞一知十」側重推理反應敏捷｜教育部《成語典》辨析'],
    story: [
      '春秋時代，孔子收了很多學生。在這些學生裡，有兩個人特別出色：一個是顏回，一個是子貢。',
      '顏回是魯國人，家裡很窮，卻每天都開開心心的讀書、思考。他話不多，上課時總是安安靜靜的聽，可是下課以後，常常能把老師說的道理用在生活裡，還想得更深、更遠。',
      '子貢是衛國人，口才很好，腦筋轉得快，很會做生意，也很會跟人討論事情，是大家公認的聰明人。',
      '有一天，孔子問子貢：「你和顏回比起來，誰比較好呢？」',
      '子貢想了想，很誠懇的說：「我怎麼敢跟顏回比呢？顏回聽到一件事，就能推想出十件相關的道理；我聽到一件事，只能推想出兩件。」',
      '孔子聽了，點點頭說：「是比不上他啊。我和你，都比不上他。」',
      '孔子這句話很不簡單。身為老師，他沒有擺架子，坦白承認學生在某些地方比自己更強，這表示他真心欣賞顏回。而子貢明明也很聰明，卻願意大方的說自己不如同學，也是一種了不起的胸襟。',
      '後來，人們就用「聞一知十」形容一個人天資聰敏、善於推想，聽到一件事就能想通很多相關的事。'
    ],
    mean: '聽到一件事，就能推知十件相關的事。形容人天資聰敏，善於類推。',
    usage: ['用來稱讚人很聰明、反應快，能從一件事推想到很多事（褒義）。', '和「舉一反三」都形容學習能力很強；「聞一知十」側重推理反應敏捷，「舉一反三」側重天資聰慧靈敏。', '只是「知道很多事」或「背得很熟」，不一定是聞一知十；重點是「從一件事推想到其他事」。'],
    misuse: [],
    eg: ['老師才講了一種解題方法，小芸就聞一知十，連後面幾種變化題都會算了。', '妹妹聞一知十，學會「日」字旁的字常跟太陽有關後，就自己猜出「晴」「曬」的意思。'],
    syn: ['舉一反三', '觸類旁通'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '子貢說，顏回聽到一件事能推想出幾件？', opts: ['十件', '兩件', '一件', '三件'], a: 0, why: '第五段：「顏回聽到一件事，就能推想出十件相關的道理。」兩件是子貢說自己。' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '子貢說「我怎麼敢跟顏回比呢」，表示他是怎樣的人？', opts: ['能誠實承認別人比較強', '不太喜歡跟同學說話', '覺得自己是最聰明的', '很害怕被老師責罵'], a: 0, why: '子貢自己也很聰明（第三段），卻「很誠懇」的說比不上顏回，可見他能誠實承認別人的長處。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '文章說孔子的回答「很不簡單」，是因為什麼？', opts: ['老師肯承認學生比自己強', '孔子算數學算得比子貢快', '孔子其實不喜歡子貢', '孔子想要藉機考考顏回'], a: 0, why: '第七段：孔子「坦白承認學生在某些地方比自己更強」，表示他真心欣賞顏回。' },
      { id: 'r4', p: 4, d: 3, type: 'open', q: '子貢自己也很聰明，卻說「我比不上顏回」。你覺得承認「別人比我強」會讓人變差，還是變好？請用故事內容和自己的經驗說明。',
        ref: '我覺得會變好。子貢承認顏回比較強，才看得清楚自己還可以學什麼，孔子也因為這樣更欣賞他的誠實。我以前不喜歡承認同學數學比我好，後來我去請教他，才學會比較快的算法。',
        rubric: ['表明看法', '用故事內容當理由', '連結自己的經驗'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「聞一知十」的「聞」在這裡是什麼意思？', opts: ['聽到', '用鼻子聞', '名聲', '新聞'], a: 0, why: '「聞」在這裡是聽到。聞一知十就是聽到一件，知道十件。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '自然課老師說明「熱脹冷縮」時，只舉了一個例子：鐵軌之間要留一點縫。小安聽完馬上舉手說：「那電線夏天會比較鬆、冬天比較緊，對不對？還有，熱水倒進冷冷的玻璃杯，杯子可能會裂開，也是這個原因吧？」老師聽了很驚訝。', q: '小安的表現，最適合用哪個成語形容？', opts: ['聞一知十', '按圖索驥', '紙上談兵', '濫竽充數'], a: 0, why: '老師只講一個例子，小安就推想出好幾個相關的現象，是聞一知十。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈班級日記〉今天國語課要背一首很長的詩，阿哲念了二十遍，終於一字不漏的背出來了。大家都說阿哲真是聞一知十。', q: '大家說阿哲「聞一知十」，恰當嗎？', opts: ['不恰當，他是用功背熟，不是推想', '恰當，因為他把整首詩背出來了', '恰當，因為他念了整整二十遍', '不恰當，因為背詩不用耳朵聽'], a: 0, why: '聞一知十是從一件事推想很多事。阿哲是努力背熟，值得稱讚，但應該說他用功、有恆心。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '下面哪一個成語，意思和「聞一知十」最接近？', opts: ['舉一反三', '一知半解', '不求甚解', '期期艾艾'], a: 0, why: '舉一反三也是學一件能推想其他相關的事，《成語典》列為近義。一知半解、不求甚解是懂得不多不深。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '顏回能從一件事想到十件。請你試試看：從「冰塊放在太陽下會融化」這件事，你還能推想出生活中哪些相關的事？至少寫兩件，並說說你是怎麼想到的。',
        ref: '我想到夏天買冰淇淋要趕快吃，不然會融化；也想到冰箱如果停電，冷凍庫的東西會退冰，要先拿出來處理。我是想到「東西遇到熱、溫度變高就會變化」，再去找生活裡溫度變高的地方。',
        rubric: ['從題目的事推想出至少兩件相關的事', '推想的事合理，和原來的道理有關', '說出自己推想的方法'] }
    ],
    xq: [
      { id: 'x1', k: 'judge', d: 1, type: 'tf', q: '「老師只示範了一種摺紙的方法，他就聞一知十，自己摺出了好幾種不同的動物。」這句話的「聞一知十」用得恰當。', a: true, why: '只學一種方法就能推想、變出很多種，用聞一知十恰當。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '數學課學到「長方形面積＝長×寬」。小真回家後，自己想到：「那正方形就是長和寬一樣，面積就是邊長×邊長；如果把長方形沿著對角線切成兩半，三角形的面積應該就是長×寬÷2。」第二天她把想法告訴老師，老師說她都想對了，而且這些課本下一單元才會教。', q: '小真的表現可以用哪個成語形容？', opts: ['聞一知十', '一暴十寒', '門可羅雀', '紙上談兵'], a: 0, why: '從長方形面積一件事，推想出正方形和三角形的面積，是聞一知十。' }
    ]
  },
  {
    id: 'cy065', lv: 3, word: '刮目相看', zhuyin: 'ㄍㄨㄚ ㄇㄨˋ ㄒㄧㄤ ㄎㄢˋ', src: '晉．虞溥《江表傳》',
    quote: '士別三日，即更刮目相待',
    facts: ['語本晉．虞溥《江表傳》，人物是三國時代吳國的孫權、呂蒙和魯肅｜教育部《成語典》', '呂蒙年輕時學識不多，孫權勸他讀書；他起初以軍務繁忙推辭，後來才發奮向學｜教育部《成語典》典故說明', '魯肅和呂蒙議論事情竟然說不過他；呂蒙說：「士別三日，即更刮目相待。」｜教育部《成語典》典故說明', '《成語典》辨析：「刮目相看」側重對方有令人驚訝、不容忽視的轉變；「另眼相看」側重對方與眾不同、受人看重｜教育部《成語典》辨析'],
    story: [
      '三國時代，吳國有一位勇敢的將軍，叫做呂蒙。他從小在軍隊裡長大，打仗很拚命，可是沒讀過什麼書，很多人都覺得他只是一個粗魯的武人。',
      '有一天，吳國的國君孫權對呂蒙說：「你現在是帶兵的將軍了，應該多讀點書，增長見識。」呂蒙皺著眉頭說：「軍隊裡的事情那麼多，我哪有時間讀書呢？」',
      '孫權說：「我又不是要你成為研究學問的博士，只是希望你多看看書，了解從前的事。你說你忙，難道比我還忙嗎？我也常常讀書，覺得很有收穫。」呂蒙聽了很慚愧，從此開始認真讀書，一有空就捧著書本，讀得比很多讀書人還勤快。',
      '過了一段時間，吳國的大臣魯肅經過呂蒙駐守的地方。魯肅很有學問，以前也覺得呂蒙只會打仗。兩人一起討論事情，沒想到呂蒙說起話來頭頭是道，對局勢的分析既清楚又深入，魯肅好幾次都被他說得答不上話。',
      '魯肅驚訝的拍著呂蒙的背說：「我以為你只懂打仗，沒想到你現在的見識這麼好，已經不是從前吳地那個阿蒙了！」',
      '呂蒙笑著回答：「讀書人分開三天，就應該擦亮眼睛，用新的眼光重新看他啊！」',
      '後來，人們就用「刮目相看」形容用新的眼光看待一個人，通常是因為這個人有了令人驚訝的進步。'
    ],
    mean: '擦亮眼睛重新看。形容用新的眼光看待人，多半是因為對方有了令人驚訝的轉變或進步。',
    usage: ['用在一個人有了明顯、令人驚訝的進步，讓別人改變看法的時候。', '和「另眼相看」都有用新眼光看待的意思；「刮目相看」側重對方令人驚訝的轉變，「另眼相看」側重對方與眾不同、受到看重。', '如果對方一直都很好，沒有什麼改變，就不太適合說刮目相看。'],
    misuse: [],
    eg: ['弟弟以前連腳踏車都不敢騎，這學期竟然完成了環島騎車的挑戰，全家人都對他刮目相看。', '阿翔暑假每天練琴，開學表演時彈得好流暢，讓同學們刮目相看。'],
    syn: ['另眼相看'], ant: ['一視同仁'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '孫權勸呂蒙做什麼？', opts: ['多讀點書', '多練武功', '多帶點兵', '多休息'], a: 0, why: '第二段：孫權說「應該多讀點書，增長見識」。' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '孫權說「難道比我還忙嗎」，想讓呂蒙明白什麼？', opts: ['再忙也能找時間讀書', '國君的工作比將軍輕鬆', '呂蒙應該辭掉將軍', '孫權想要找人聊天'], a: 0, why: '孫權是國君，事情比呂蒙更多，還是常常讀書，所以「忙」不是不讀書的理由。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '魯肅前後對呂蒙的看法有什麼改變？', opts: ['從只會打仗，變成很有見識', '從很有學問，變成只會打仗', '從好朋友變成了敵人', '一直都覺得他很有學問'], a: 0, why: '第四段魯肅「以前也覺得呂蒙只會打仗」；第五段驚訝的說他「已經不是從前吳地那個阿蒙了」。' },
      { id: 'r4', p: 4, d: 3, type: 'open', q: '呂蒙說：「讀書人分開三天，就應該用新的眼光看他。」你同意人可以在一段不長的時間內有很大的改變嗎？請用故事內容和你看過的例子說明。',
        ref: '我同意，只要真的下功夫，人是可以改變的。呂蒙本來不讀書，被孫權勸了以後認真讀，一段時間後連魯肅都說不過他。我的表哥以前很怕上台，後來參加演講社每週練習，一個學期後就敢在全校面前主持了。不過改變需要努力，不是什麼都不做就會變。',
        rubric: ['表明同意或不同意', '用故事內容當理由', '舉出一個看過的改變例子'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「刮目相看」的意思是什麼？', opts: ['用新的眼光看待一個人', '不小心把眼睛刮傷了', '兩個人互相瞪著眼睛', '看東西看得很仔細'], a: 0, why: '刮目相看是「擦亮眼睛重新看」，用新的眼光看待人。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小凱以前上課常常打瞌睡，作業也常常缺交，國語考試總是不及格。這學期他每天放學去圖書館讀一個小時的書，還主動請老師幫他改作文。期末作文比賽，他寫的〈我的阿公〉得了全年級第一名，老師在全班面前唸了他的作文，大家都張大了嘴巴。', q: '同學們對小凱的感覺，最適合用哪個成語形容？', opts: ['刮目相看', '聞一知十', '門可羅雀', '首鼠兩端'], a: 0, why: '小凱從常不及格到得第一名，有令人驚訝的轉變，大家用新的眼光看他，就是刮目相看。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈日記〉表姊從小就是鋼琴高手，每次比賽都拿第一名。今天她又在音樂會上得到冠軍，我對她刮目相看。', q: '日記裡的「刮目相看」用得恰當嗎？', opts: ['不太恰當，表姊沒有驚人的改變', '恰當，因為表姊又拿了冠軍', '恰當，因為表姊的鋼琴彈得好', '不恰當，只有讀書才能刮目相看'], a: 0, why: '刮目相看側重「令人驚訝的轉變」。表姊一直都很厲害，這次也在意料之中，沒有轉變，用刮目相看不太恰當。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '這些成語跟「刮目相看」是什麼關係？配起來。', pairs: [['另眼相看', '近義成語'], ['一視同仁', '反義成語'], ['三顧茅廬', '意思無關']], why: '另眼相看也是用不同的眼光看待，相近；一視同仁是對每個人都一樣看待，相反；三顧茅廬是誠心邀請人才，無關。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '呂蒙靠讀書讓人刮目相看。你有沒有一件想讓別人（或自己）「刮目相看」的事？請說說你打算怎麼做，以及要花多少時間。',
        ref: '我想讓大家對我的游泳刮目相看，因為我現在只能游十公尺。我打算每週六去游泳池練一個小時，先練換氣，再練踢水，希望三個月後能游完五十公尺，在學期末的游泳課給大家一個驚喜。',
        rubric: ['說出一件想讓人刮目相看的事', '提出具體的努力方法', '說出合理的時間安排'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '以前怕狗的妹妹，現在竟然當起動物醫院的小志工，真讓人＿＿＿＿。', opts: ['刮目相看', '三顧茅廬', '門可羅雀', '按圖索驥'], a: 0, why: '妹妹從怕狗到當動物醫院志工，有令人驚訝的轉變，用刮目相看。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '社區籃球隊的阿樂以前跑兩圈就喘，大家都叫他「板凳隊長」。暑假兩個月，他每天清晨去河堤慢跑，還跟著影片練運球。開學後的比賽，他不但打滿全場，還投進了最後致勝的一球，隊友們都不敢相信眼前這個人是阿樂。', q: '隊友們對阿樂的感覺，可以用哪個成語形容？', opts: ['刮目相看', '一暴十寒', '首鼠兩端', '功虧一簣'], a: 0, why: '阿樂有了令人驚訝的進步，隊友用新的眼光看他，是刮目相看。' }
    ]
  },
  {
    id: 'cy068', lv: 3, word: '名落孫山', zhuyin: 'ㄇㄧㄥˊ ㄌㄨㄛˋ ㄙㄨㄣ ㄕㄢ', src: '宋．范公偁《過庭錄》',
    quote: '解名盡處是孫山，賢郎更在孫山外',
    facts: ['典出宋．范公偁《過庭錄》｜教育部《成語典》', '孫山是宋朝吳地的讀書人，聰明風趣、有才氣，人稱「滑稽才子」｜教育部《成語典》典故說明', '孫山和同鄉的兒子一起去外地考試；孫山考上最後一名，同鄉的兒子沒考上｜教育部《成語典》典故說明', '「名落孫山」指參加考試或選拔沒有被錄取｜教育部《成語典》釋義'],
    story: [
      '宋朝時，吳地有一位讀書人，名叫孫山。他很聰明，又很會說笑話，說話常常讓人捧腹大笑，大家都叫他「滑稽才子」。',
      '有一年，孫山要到別的郡城去參加考試。一位同鄉聽說了，就把自己的兒子託給他：「我兒子也要去考試，請你帶著他一起去吧。」孫山爽快的答應了。',
      '兩個人到了郡城，一起走進考場，各自拚命作答。考完以後，就等著放榜。',
      '放榜那天，城裡擠滿了人。孫山擠到榜前，從第一名一個一個往下找，找到最後一名，終於看到了自己的名字——「孫山」！他鬆了一口氣：考上了，雖然是最後一名。可是，他把榜單從頭到尾又看了一遍，都沒有看到同鄉兒子的名字。',
      '孫山先回到了家鄉。那位同鄉一聽說他回來了，就急忙跑來問：「我兒子考上了沒有？」',
      '孫山心想：直接說「沒考上」，對方一定很難過；可是又不能說謊。他想了一想，笑著念了兩句：「解名盡處是孫山，賢郎更在孫山外。」意思是：榜單上最後一個名字是孫山，您的兒子，還在孫山的後面呢。',
      '同鄉聽懂了，知道兒子沒考上。孫山用一句幽默的話，把壞消息說得不那麼刺耳。後來，人們就用「名落孫山」表示參加考試或選拔沒有被錄取。'
    ],
    mean: '名字落在孫山的後面。指參加考試或選拔，沒有被錄取。',
    usage: ['用在考試、甄選、選拔沒有考上、沒有被選上的時候。', '孫山自己其實考上了（最後一名）；「名落孫山」是說名字排在孫山後面，也就是沒考上。考上最後一名不能說名落孫山。', '近義成語有「榜上無名」，反義成語有「金榜題名」「魚躍龍門」。'],
    misuse: [],
    eg: ['哥哥第一次考研究所名落孫山，他沒有灰心，隔年再考就考上了。', '這次科展甄選我名落孫山，但我學到了很多做實驗的方法。'],
    syn: ['榜上無名'], ant: ['金榜題名', '魚躍龍門'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '孫山在榜單上排第幾名？', opts: ['最後一名', '第一名', '第二名', '沒有上榜'], a: 0, why: '第四段：他找到最後一名，「終於看到了自己的名字」。' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '孫山為什麼不直接說「你兒子沒考上」？', opts: ['怕對方聽了太難過', '他忘記去看榜單了', '他自己也沒有考上', '他想要故意騙對方'], a: 0, why: '第六段：他想「直接說『沒考上』，對方一定很難過；可是又不能說謊」，所以用幽默的方式說。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '「賢郎更在孫山外」這句話真正的意思是什麼？', opts: ['您的兒子排在榜外，沒考上', '您的兒子考得比孫山好', '您的兒子住在孫山家外面', '您的兒子還留在山的外面'], a: 0, why: '孫山是榜上最後一名，兒子「更在孫山外」，就是排在榜單外面，沒有考上。' },
      { id: 'r4', p: 4, d: 3, type: 'open', q: '孫山用幽默的話說出壞消息。你覺得這種說法好不好？如果你要告訴好朋友「你沒有被選上」，你會怎麼說？',
        ref: '我覺得不錯，因為孫山沒有說謊，又讓對方比較容易接受。可是如果對方很難過，太好笑的話可能會讓他覺得被開玩笑。如果是我，我會先說「選拔名單出來了」，再溫和的告訴他沒選上，然後說「你練習得很認真，下次我陪你一起練」。',
        rubric: ['對孫山的說法提出看法', '想到說壞消息時要照顧對方感受', '說出自己具體會怎麼說'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「名落孫山」是什麼意思？', opts: ['考試或選拔沒有被錄取', '名字被刻在一座山上', '考試考了全班第一名', '去爬山的時候迷了路'], a: 0, why: '名落孫山是名字落在孫山（最後一名）後面，也就是沒考上、沒選上。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '學校合唱團要招收十位新團員，有三十個人報名。小雅練習了一個月，甄選那天卻因為太緊張，高音唱破了。名單公布時，她從頭看到尾，都沒有看到自己的名字。媽媽安慰她：「明年還有機會，我們再一起練習。」', q: '小雅這次甄選的結果，最適合用哪個成語形容？', opts: ['名落孫山', '金榜題名', '刮目相看', '三顧茅廬'], a: 0, why: '小雅參加甄選沒有被選上，就是名落孫山。金榜題名是考上，意思相反。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈班級日記〉這次閱讀檢測，全班共有三十人過了及格線，阿明剛好是第三十名，搭上最後一班車。他開心的說：「我名落孫山，跟孫山一樣考上了！」', q: '阿明說自己「名落孫山」，恰當嗎？', opts: ['不恰當，他有考上，名落孫山是沒考上', '恰當，因為他和孫山一樣是最後一名', '恰當，因為他通過了閱讀檢測', '不恰當，閱讀檢測不是古代的考試'], a: 0, why: '名落孫山是名字落在孫山後面，也就是沒考上。阿明考上了，雖然是最後一名，也不能說名落孫山。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '下面哪一個成語，意思和「名落孫山」相反？', opts: ['金榜題名', '榜上無名', '一暴十寒', '功虧一簣'], a: 0, why: '金榜題名是考上了，和名落孫山相反。榜上無名意思相近。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '沒考上、沒選上，心裡一定不好受。想一次你「名落孫山」或沒有成功的經驗（考試、比賽、甄選都可以），你後來是怎麼面對的？如果重來一次，你會怎麼做？',
        ref: '我三年級參加躲避球校隊甄選沒選上，難過了好幾天，還說以後不玩了。如果重來一次，我會先問教練我哪裡還不夠好，例如接球不穩，然後每天找同學練習接球，隔年再去甄選。',
        rubric: ['說出一次沒成功的經驗', '說出當時的心情與反應', '提出更積極的面對方法'] }
    ],
    xq: [
      { id: 'x1', k: 'judge', d: 1, type: 'tf', q: '「這次英語演講比賽的初選，我名落孫山，沒能進入決賽。」這句話的「名落孫山」用得恰當。', a: true, why: '初選沒有被選上，用名落孫山恰當。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '社區少棒隊要從四十位小朋友裡選出十八位正式球員。阿哲和阿德一起參加測驗，結果阿哲以最後一名入選，阿德卻沒有選上。阿德的媽媽問阿哲結果，阿哲不好意思直接說，只好說：「名單最後一個是我，阿德還在我後面。」', q: '阿德的測驗結果，可以用哪個成語形容？', opts: ['名落孫山', '金榜題名', '刮目相看', '聞一知十'], a: 0, why: '阿德排在最後一名入選的阿哲後面，沒有選上，就是名落孫山。阿哲雖是最後一名，卻是入選了。' }
    ]
  },
  {
    id: 'cy071', lv: 3, word: '一暴十寒', zhuyin: 'ㄧ ㄆㄨˋ ㄕˊ ㄏㄢˊ', src: '《孟子．告子上》',
    quote: '一日暴之，十日寒之，未有能生者也',
    facts: ['語本《孟子．告子上》｜教育部《成語典》', '孟子認為齊王做事沒有成效，不是因為不聰明，而是受身邊小人干擾，不能持續向善｜教育部《成語典》典故說明', '「暴」讀ㄆㄨˋ，同「曝」，曝曬的意思｜教育部《成語典》辨析', '同一章孟子也舉弈秋教兩個學生下棋的例子，說明不專心就學不好｜《孟子．告子上》', '注音本音ㄧ ㄆㄨˋ，「一」口語變調讀ㄧˊ｜教育部《成語典》注音'],
    story: [
      '戰國時代，孟子到齊國去，希望齊王能好好治理國家，照顧百姓。可是，齊王做事總是三心二意，一下子想做好事，一下子又放下了。有人說齊王不夠聰明，孟子卻搖搖頭。',
      '孟子說：「不要奇怪齊王不聰明。就算是天底下最容易生長的植物，如果曬一天太陽，又讓它冷凍十天，也不可能活得下來。」',
      '他接著說：「我能見到齊王的機會很少。我一離開，那些出壞主意的人就圍到他身邊，讓他的心又冷掉了。就算他心裡剛冒出一點想做好事的嫩芽，又能怎麼樣呢？」',
      '孟子又舉了一個例子。有一位全國最會下棋的人，叫做弈秋，他同時教兩個學生下棋。',
      '第一個學生全心全意，眼睛盯著棋盤，耳朵只聽弈秋講解。第二個學生雖然也坐在那裡聽，心裡卻想著：「天上會不會有天鵝飛過來？我要拿弓箭把牠射下來。」',
      '兩個人跟同一位老師學，學的是同樣的東西，可是第二個學生怎麼也比不上第一個。孟子問：「難道是他比較笨嗎？」當然不是，是因為他不專心啊。',
      '孟子用「曬一天、凍十天」說明：做事、學習如果時斷時續，努力一下又停很久，再好的開始也長不出成果。後來，人們就把這句話說成「一暴十寒」，比喻做事缺乏恆心，常常中斷。這裡的「暴」讀作ㄆㄨˋ，就是「曝曬」的「曝」。'
    ],
    mean: '曬一天太陽，又凍十天。比喻做事、學習缺乏恆心，常常中斷。',
    usage: ['用在批評學習或工作時斷時續、不能堅持（貶義）。', '「暴」讀ㄆㄨˋ，同「曝」，是曬太陽的意思，不要讀成ㄅㄠˋ。', '反義成語有「持之以恆」「鍥而不舍」「孜孜矻矻」。'],
    misuse: ['「他背單字一暴（ㄅㄠˋ）十寒，背一天休息十天。」✗　「暴」同「曝」，是曬太陽，要讀ㄆㄨˋ，不讀ㄅㄠˋ。'],
    eg: ['學英文如果一暴十寒，想到才念一下，就很難真正學會。', '弟弟練鋼琴一暴十寒，比賽前拚命練，比完就一個月不碰琴。'],
    syn: [], ant: ['持之以恆', '鍥而不舍', '孜孜矻矻'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '弈秋的第二個學生，上課時心裡在想什麼？', opts: ['想射下飛過來的天鵝', '下一步棋要怎麼走', '放學後要去哪裡玩', '老師說的話對不對'], a: 0, why: '第五段：他心裡想著「天上會不會有天鵝飛過來？我要拿弓箭把牠射下來」。' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '孟子說「我一離開，就有人讓齊王的心又冷掉」，這裡的「冷掉」是什麼意思？', opts: ['想做好事的心又被打消了', '齊王的身體著涼生病了', '宮殿裡的天氣變冷了', '齊王對孟子很生氣'], a: 0, why: '第三段：齊王剛冒出想做好事的「嫩芽」，又被出壞主意的人打消了，就像植物曬一天又凍十天。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '孟子說的「植物」和「下棋的學生」，共同想說明什麼道理？', opts: ['學習要持續專心，不能中斷', '植物要多曬太陽才長得好', '學下棋一定要找好老師', '天鵝是很難射到的鳥'], a: 0, why: '植物曬一天凍十天活不了，學生不專心學不好，最後一段說明：時斷時續、不專心，就長不出成果。' },
      { id: 'r4', p: 4, d: 3, type: 'open', q: '孟子認為齊王做不好，不是因為笨，而是因為身邊的人干擾、不能堅持。你覺得「環境」和「自己」哪一個對能不能堅持比較重要？請用故事內容和自己的經驗說明。',
        ref: '我覺得兩個都重要，但自己比較重要。弈秋的兩個學生在同一個環境上課，一個專心、一個分心，結果就不一樣。可是環境也會影響人，像齊王身邊有人一直出壞主意。我寫功課時會把手機放到客廳，讓環境幫助自己專心。',
        rubric: ['表明自己的看法', '用故事內容當理由（弈秋的兩個學生或齊王）', '連結自己的經驗'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「一暴十寒」的「暴」，在這裡是什麼意思？', opts: ['曬太陽', '很兇暴', '突然', '暴風雨'], a: 0, why: '「暴」同「曝」，讀ㄆㄨˋ，是曬太陽的意思。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小志新年時立志每天寫日記。第一個星期他寫得很認真，每天都寫滿一頁。第二個星期開始，他說功課太多，就停了。過了半個月，他想起來又連寫三天，接著又忘了一個月。到了年底，他的日記本只寫了不到二十頁。', q: '小志寫日記的情形，最適合用哪個成語形容？', opts: ['一暴十寒', '磨杵成針', '臥薪嘗膽', '聞一知十'], a: 0, why: '小志寫幾天、停很久，時斷時續，是一暴十寒。磨杵成針、臥薪嘗膽都是長期努力，剛好相反。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈運動社紀錄〉阿美這學期每天早上都到操場跑步，下雨天就改在走廊原地跑，一天也沒停，期末跑步測驗進步了一分鐘。社長說：「阿美練跑真是一暴十寒！」', q: '社長用「一暴十寒」恰當嗎？', opts: ['不恰當，阿美天天練，沒有中斷', '恰當，因為阿美在太陽下跑步', '恰當，因為下雨天很寒冷', '不恰當，因為跑步不需要曬太陽'], a: 0, why: '一暴十寒是時斷時續、沒有恆心。阿美一天也沒停，應該說「持之以恆」。成語是比喻，跟曬不曬太陽無關。' },
      { id: 'p4', k: 'fill', d: 2, type: 'mc', q: '學樂器要每天練一點，如果＿＿＿＿，練一天就休息好幾天，永遠也彈不好。', opts: ['一暴十寒', '持之以恆', '臥薪嘗膽', '磨杵成針'], a: 0, why: '練一天休息好幾天，就是一暴十寒。持之以恆、臥薪嘗膽、磨杵成針都是持續努力，放進句子會前後矛盾。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '想一件你曾經「一暴十寒」的事（例如運動、背單字、整理房間），你覺得是什麼原因讓你停下來？你可以想出什麼方法，讓自己不再中斷？',
        ref: '我以前背英文單字常常背兩天就停，因為一次背太多覺得很累。我想改成每天只背五個，貼在書桌前，背完就在月曆上畫一個圈，看到圈越來越多就會想繼續。',
        rubric: ['說出一件曾經做做停停的事', '找出讓自己中斷的原因', '提出能持續的具體方法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '整理房間不能＿＿＿＿，大掃除一次以後就放著一個月不管。', opts: ['一暴十寒', '金榜題名', '三顧茅廬', '門庭若市'], a: 0, why: '整理一次就一個月不管，是時斷時續，用一暴十寒。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '姊姊：「這個暑假我每週一、三、五都去游泳，兩個月沒有缺過一次。」\n弟弟：「姊姊游泳一暴十寒，難怪進步這麼多！」', q: '弟弟說的「一暴十寒」用得恰當。', a: false, why: '姊姊固定練習、從不缺席，是持之以恆，不是一暴十寒。' }
    ]
  },
  {
    id: 'cy074', lv: 3, word: '功虧一簣', zhuyin: 'ㄍㄨㄥ ㄎㄨㄟ ㄧ ㄎㄨㄟˋ', src: '《書經．旅獒》',
    quote: '為山九仞，功虧一簣',
    facts: ['語出《書經．旅獒》｜教育部《成語典》', '周武王滅商後，西方的旅國進貢獒犬；召公擔心武王玩物喪志，勸他修德、重用賢人、不要珍視異物｜教育部《成語典》典故說明', '堆土成山已到九仞，卻因差最後一簣而不能成功｜教育部《成語典》釋義', '《成語典》辨析：「功虧一簣」指只差最後一點努力而失敗，含惋惜；「前功盡棄」指事情進行了一大半而失敗，毀掉前面的努力｜教育部《成語典》辨析', '注音本音ㄧ ㄎㄨㄟˋ，「一」口語變調讀ㄧˊ｜教育部《成語典》注音'],
    story: [
      '三千多年前，周武王打敗了商朝，建立周朝。天下安定以後，四方的部族都派人送來禮物，表示願意和周朝友好。',
      '西方有一個叫「旅」的國家，送來了幾隻獒犬。獒犬又高又壯，毛色光亮，跑起來虎虎生風，是非常珍貴的大狗。武王看了很喜歡。',
      '大臣召公看在眼裡，心裡卻有點擔心：「大王剛建立國家，還有很多事要做。如果因為喜歡這些稀奇的動物、寶物，把心思放在玩樂上，那可就糟了。」於是，他寫了一篇文章，好好的勸武王。',
      '召公在文章裡說：君王應該用心修養品德，重用有才能的人，不要把遠方送來的稀奇東西看得太重。玩弄別人，會失去品德；玩弄東西，會失去志向。',
      '最後，召公說了一個比喻：「要堆一座九仞高的土山，一筐土一筐土的往上堆，已經堆得好高好高了，如果只差最後一筐土就停下來，這座山還是沒有完成。」',
      '召公的意思是：建立國家就像堆土山，前面已經付出了那麼多努力，如果在小地方鬆懈，不能堅持到最後，前面的辛苦就可能白費。',
      '「仞」是古代的長度單位，「簣」是裝土用的竹筐。後來，人們就用「功虧一簣」比喻事情只差最後一步，卻因為沒有堅持到底而失敗，帶著很可惜的意思。'
    ],
    mean: '堆一座九仞高的山，只差最後一筐土而沒有完成。比喻事情只差最後一步，卻因為沒有堅持到底而失敗，含有惋惜的意思。',
    usage: ['用在「快要成功，卻在最後關頭鬆懈或停下來而失敗」的時候，帶有可惜的語氣。', '和「前功盡棄」不同：功虧一簣是只差最後一點努力；前功盡棄是做了一大半而失敗、毀掉前面的努力，像颱風把快採收的果實打落，要用前功盡棄。', '近義成語有「功敗垂成」，反義成語有「善始善終」「堅持不懈」。'],
    misuse: ['「颱風把快要收成的柳丁吹落一地，果農功虧一簣。」✗　這是天災毀掉了前面的辛苦，不是只差最後一點努力，《成語典》認為這種情況要說「前功盡棄」。'],
    eg: ['拼圖只剩最後三片，弟弟卻說累了不拼了，真是功虧一簣。', '比賽最後一分鐘我們放鬆了防守，被對手連進兩球，功虧一簣。'],
    syn: ['功敗垂成', '前功盡棄', '半途而廢'], ant: ['善始善終', '堅持不懈'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '旅國送給周武王的禮物是什麼？', opts: ['獒犬', '黃金', '寶劍', '駿馬'], a: 0, why: '第二段：旅國「送來了幾隻獒犬」。' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '召公看到武王很喜歡獒犬，為什麼會擔心？', opts: ['怕武王把心思放在玩樂上', '怕兇猛的獒犬會咬傷武王', '怕旅國要把狗要回去', '怕獒犬每天吃掉太多糧食'], a: 0, why: '第三段：國家剛建立，召公怕武王「把心思放在玩樂上」。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '召公用「堆土山只差一筐」來比喻什麼？', opts: ['最後鬆懈，前面的努力會白費', '堆土山是一件好玩的遊戲', '周朝需要準備更多的竹筐', '獒犬很喜歡在土山上奔跑'], a: 0, why: '第六段：建立國家就像堆土山，「如果在小地方鬆懈，不能堅持到最後，前面的辛苦就可能白費」。' },
      { id: 'r4', p: 4, d: 3, type: 'open', q: '為什麼很多事情常常在「最後一步」失敗？請用故事的比喻和自己的經驗說明，並說說你會怎麼提醒自己撐到最後。',
        ref: '因為快完成的時候，人會覺得「差不多了」，就容易放鬆，就像堆土山只差一筐卻停下來。我上次做勞作，最後上色時覺得累，就隨便塗一塗，結果整個作品變醜了。以後我會在最後一步前休息一下，再告訴自己「做完才算數」。',
        rubric: ['說出最後一步容易失敗的原因', '用故事的比喻或自己的經驗說明', '提出撐到最後的方法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「功虧一簣」的「簣」是什麼？', opts: ['裝土用的竹筐', '古代的長度單位', '一種珍貴的狗', '堆起來的土山'], a: 0, why: '「簣」是裝土用的竹筐；古代的長度單位是「仞」。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '班上用寶特瓶蓋拼一幅大型的台灣地圖，大家收集了兩個月，拼好了九成多。最後只剩東部一小塊還沒完成，可是同學們覺得「差不多了」，一個個跑去準備運動會，再也沒人去補。結果學校的作品展，這幅缺了一角的地圖沒能展出。', q: '這幅地圖的結果，最適合用哪個成語形容？', opts: ['功虧一簣', '精衛填海', '三顧茅廬', '刮目相看'], a: 0, why: '只差最後一小塊，卻因為鬆懈沒完成而失敗，就是功虧一簣。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈日記〉今天和家人去爬山，原本要爬到山頂，可是才走到山腳的登山口，就下起了大雨，我們只好回家。這次爬山真是功虧一簣。', q: '日記裡的「功虧一簣」用得恰當嗎？', opts: ['不恰當，才剛開始就停，不是只差最後一步', '恰當，因為他們最後還是沒有爬到山頂', '恰當，因為半路下大雨，真的很可惜', '不恰當，因為爬山根本不用裝土的竹筐'], a: 0, why: '功虧一簣是「只差最後一步」才失敗。他們才到登山口，還沒開始爬，不能用功虧一簣。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '下面哪一句應該用「前功盡棄」，不適合用「功虧一簣」？', opts: ['冰雹把快採收的水梨打落一地', '只剩最後一題，他卻放棄不寫了', '拼圖剩最後一片，他卻不拼了', '跑到終點前十公尺，他停下來走路'], a: 0, why: '《成語典》辨析：功虧一簣是只差最後一點努力；天災把快採收的水果打落，是前面的努力被毀，要用前功盡棄。其他三句都是最後一步沒堅持。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '想一件你「差一點就完成」卻沒做完的事（例如一本沒讀完的書、一個沒做完的作品）。你覺得當時是什麼原因讓你停下來？現在可以怎麼把它完成？',
        ref: '我有一本恐龍百科只剩最後兩章沒讀，因為後來迷上了別的漫畫就忘了。我可以把它放回書桌上，每天睡前讀十頁，三天就能讀完，讀完再在書的最後一頁寫下完成的日期。',
        rubric: ['說出一件差一點完成的事', '找出停下來的原因', '提出完成它的具體做法'] }
    ],
    xq: [
      { id: 'x1', k: 'judge', d: 1, type: 'tf', q: '「大隊接力我們一路領先，最後一棒卻在終點前掉了棒，被對手超過，真是功虧一簣。」這句話的「功虧一簣」用得恰當。', a: true, why: '一路領先，只差最後一點卻失手，用功虧一簣恰當。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '小薇報名了「每天閱讀二十分鐘，連續一百天」的挑戰，完成就能得到圖書館的獎狀。她每天認真的讀，一直讀到第九十八天。第九十九天全家去露營，她心想「少一天應該沒關係」，就沒有讀。結果挑戰規定要連續，她只能從頭開始。', q: '小薇的挑戰結果，可以用哪個成語形容？', opts: ['功虧一簣', '一暴十寒', '臥薪嘗膽', '名落孫山'], a: 0, why: '堅持了九十八天，只差最後兩天卻鬆懈，是功虧一簣。小薇前面一直很有恆心，不是一暴十寒。' }
    ]
  },

  // ==================== L4 分辨用法 ====================
  {
    id: 'cy078', lv: 4, word: '文不加點', zhuyin: 'ㄨㄣˊ ㄅㄨˋ ㄐㄧㄚ ㄉㄧㄢˇ', src: '漢．禰衡〈鸚鵡賦〉',
    quote: '筆不停綴，文不加點',
    facts: ['典出漢．禰衡〈鸚鵡賦〉（序）｜教育部《成語典》', '東漢的禰衡很有才華卻恃才傲物，曹操容不下他，把他送走，後來他到了黃祖那裡｜教育部《成語典》典故說明', '黃祖的兒子黃射大宴賓客，有人獻上鸚鵡，請禰衡當場作賦；他下筆迅速，寫成後沒有任何塗改｜教育部《成語典》典故說明', '形容文思敏捷、下筆成章，通篇無所塗改｜教育部《成語典》釋義'],
    story: [
      '東漢末年，有一位很年輕就出名的才子，叫做禰衡。他讀書過目不忘，文章寫得又快又好，可是個性很高傲，常常看不起別人，說話也不留情面。',
      '當時權力最大的曹操聽說禰衡很有才華，想見見他。沒想到禰衡在眾人面前一點也不客氣，讓曹操很沒面子。曹操不想留他在身邊，就把他送走了。後來，禰衡到了一位叫黃祖的將領手下做事。',
      '黃祖的兒子黃射很欣賞禰衡的才華，常常和他來往。有一天，黃射舉辦了一場熱鬧的宴會，請來許多客人。宴會上，有一位客人獻上一隻漂亮的鸚鵡，羽毛綠得發亮，還會學人說話，大家都圍過來看。',
      '黃射舉起酒杯，對禰衡說：「今天大家這麼高興，又有這隻難得的鸚鵡，請先生為牠寫一篇賦，讓客人們欣賞欣賞吧！」「賦」是一種很講究文采的文章，平常的人要寫好幾天才寫得出來。',
      '禰衡也不推辭，拿起筆就寫。只見他的筆一路往下寫，一刻也沒停過，寫完一句接一句，從頭到尾沒有塗掉一個字、改掉一句話。沒多久，一篇文辭華美的〈鸚鵡賦〉就完成了，在座的客人讀了，都讚嘆不已。',
      '〈鸚鵡賦〉前面的序記下了這個場面：「筆不停綴，文不加點。」意思是筆沒有停下來，文章也沒有一處塗改。',
      '後來，人們就用「文不加點」形容一個人文思敏捷，下筆就能寫成文章，而且通篇都不用塗改。',
      '要特別注意：這裡的「點」是塗改的意思，不是標點符號。說一篇文章「文不加點」，是在稱讚作者寫得又快又好，不是說文章沒有加上標點。'
    ],
    mean: '文章寫好，沒有一處需要塗改。形容文思敏捷，下筆成章，通篇沒有修改。',
    usage: ['用來稱讚人寫文章又快又好，一氣呵成，不用修改（褒義）。', '「點」是塗改，不是標點符號；文章沒加標點，不能說文不加點。', '近義成語有「一氣呵成」「一揮而就」「下筆成章」。'],
    misuse: ['「這篇作文從頭到尾一個逗號、句號都沒有，真是文不加點。」✗　「點」是塗改的意思，不是標點符號；文不加點是稱讚文章寫得快又好。', '「他寫作文時改了又改，花了一整個晚上，終於文不加點的完成了。」✗　改了又改，就不是「不用塗改」了。'],
    eg: ['姊姊對這次的題目很有感覺，拿起筆就文不加點的寫完了一篇八百字的作文。', '詩人看著夕陽，靈感湧現，文不加點的寫下了一首詩。'],
    syn: ['一氣呵成', '一揮而就', '下筆成章'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '宴會上，客人獻上了什麼？', opts: ['一隻鸚鵡', '一把寶劍', '一幅畫', '一壺酒'], a: 0, why: '第三段：「有一位客人獻上一隻漂亮的鸚鵡。」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '文章特別說「賦」平常要寫好幾天，是要讓讀者明白什麼？', opts: ['禰衡當場寫好，真的很了不起', '賦是一種很簡單、很好寫的文章', '黃射自己不懂得怎麼寫賦', '客人們都等得很不耐煩'], a: 0, why: '別人要寫好幾天，禰衡在宴會上沒多久就寫完，還不用修改，更顯出他文思敏捷。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '「筆不停綴，文不加點」這兩句，分別在說什麼？', opts: ['筆沒有停，文章也沒有塗改', '筆寫斷了，文章也沒加標點', '寫得很慢，字也寫得很小', '筆用完了，墨水也乾了'], a: 0, why: '第六段：「意思是筆沒有停下來，文章也沒有一處塗改。」' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '文章最後特別提醒「點」不是標點符號，是因為什麼？', opts: ['很多人容易把它誤會成沒加標點', '古時候的文章本來都有加標點', '禰衡寫字時其實很喜歡加標點', '標點符號是禰衡發明的'], a: 0, why: '最後一段：「點」是塗改，「不是說文章沒有加上標點」。這是最容易望文生義、用錯的地方。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '禰衡很有才華，卻因為高傲得罪了很多人。你覺得一個人「很有才華」和「待人有禮」，哪一個比較重要？請用故事內容說明你的看法。',
        ref: '我覺得兩個都重要，但待人有禮更重要。禰衡文章寫得那麼好，當場就能寫完一篇賦，可是他看不起別人，連曹操都不想留他。如果他對人有禮貌，他的才華會有更多人願意欣賞、願意給他機會。',
        rubric: ['表明看法', '用故事內容當理由', '說明才華和禮貌的關係'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「文不加點」的「點」在這裡是什麼意思？', opts: ['塗改', '標點符號', '一點點', '點心'], a: 0, why: '「點」在這裡是塗改。文不加點就是文章沒有一處塗改。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '國語課臨時要大家寫一篇以「下雨天」為題的短文，限時二十分鐘。很多同學咬著鉛筆想了好久，橡皮擦擦了又擦。小涵卻一拿到稿紙就開始寫，筆幾乎沒停過，十五分鐘就寫好了，稿紙上乾乾淨淨，一個字也沒有改，老師讀了還說內容很生動。', q: '小涵寫短文的情形，最適合用哪個成語形容？', opts: ['文不加點', '老生常談', '期期艾艾', '不求甚解'], a: 0, why: '小涵寫得又快又好，一個字也沒改，就是文不加點。' },
      { id: 'p3', k: 'judge', d: 2, type: 'tf', q: '「表哥寫演講稿時，靈感來得很快，一口氣寫完，一個字都沒改，真是文不加點。」這句話的「文不加點」用得恰當。', a: true, why: '一口氣寫完、一字未改，用文不加點恰當。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈作文評語〉這篇作文內容很有趣，可惜整篇只有一個句號，逗號一個都沒有，讀起來很吃力，真是文不加點。下次記得把標點加上去。', q: '評語裡的「文不加點」用得恰當嗎？', opts: ['不恰當，「點」是塗改，不是標點', '恰當，因為作文真的很少加標點', '恰當，因為評語提醒他要加標點', '不恰當，因為這篇作文寫得太長'], a: 0, why: '這是最常見的望文生義：把「點」當成標點符號。文不加點是稱讚寫得又快又好、不用塗改。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '禰衡能「文不加點」，是因為他平常讀了很多書、寫過很多文章。你覺得自己寫作文時，要做哪些準備，才能寫得更順、更少塗改？',
        ref: '我覺得平常要多讀書，累積好的句子和想法。寫之前先花兩分鐘把要寫的重點列在草稿紙上，像第一段寫什麼、第二段寫什麼，這樣下筆時就知道方向，不會寫到一半又要擦掉重寫。',
        rubric: ['提出平常的累積方法', '提出寫之前的準備步驟', '說明這些準備怎麼讓寫作更順'] }
    ],
    xq: [
      { id: 'x1', k: 'judge', d: 2, type: 'tf', q: '「他寫的報告連一個標點都沒加，老師說他文不加點。」這句話的「文不加點」用得恰當。', a: false, why: '「點」是塗改，不是標點。報告沒加標點，不能說文不加點。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '學校作文比賽當天，題目是「我最難忘的一天」。阿德一看到題目，就想起去年和阿公一起去釣魚的事。他拿起筆就寫，一段接一段，寫完正好在時間內，稿紙上一個修改的痕跡也沒有，評審說他的文章自然又流暢。', q: '阿德寫作文的情形，可以用哪個成語形容？', opts: ['文不加點', '不求甚解', '首鼠兩端', '期期艾艾'], a: 0, why: '下筆就寫成，沒有任何修改，是文不加點。' }
    ]
  },
  {
    id: 'cy081', lv: 4, word: '期期艾艾', zhuyin: 'ㄑㄧˊ ㄑㄧˊ ㄞˋ ㄞˋ', src: '《史記．張丞相列傳》、晉．裴啟《語林》',
    quote: '臣口不能言，然臣期期知其不可',
    facts: ['「期期」語出《史記．張丞相列傳》，「艾艾」語出晉．裴啟《語林》，兩個典故合成這個成語｜教育部《成語典》釋義', '周昌是西漢沛縣人，跟隨劉邦起兵，個性耿直、說話口吃｜教育部《成語典》典故說明', '劉邦想廢太子，改立戚夫人的兒子如意；周昌急得連說「期期」，劉邦聽了大笑，這件事便作罷｜教育部《成語典》典故說明', '鄧艾是三國魏國的將領，說話口吃，常說「艾艾」；宣王司馬懿問他到底有幾個艾，他用「鳳兮鳳兮」回答｜《語林》、教育部《成語典》典故說明'],
    story: [
      '「期期艾艾」這個成語很特別，它是由兩個不同時代的故事拼起來的。兩個故事的主角，說話都有點結巴。',
      { h: '第一個故事：周昌的「期期」' },
      '西漢初年，有一位大臣叫周昌，他和漢高祖劉邦是同鄉，很早就跟著劉邦打天下。周昌個性耿直，有話直說，就連皇帝做錯了，他也敢當面勸。不過他有一個特點：說話容易結巴，一著急就更嚴重。',
      '有一次，劉邦想把原本的太子換掉，改立他最寵愛的戚夫人所生的兒子如意。大臣們紛紛反對，劉邦就問周昌的意見。周昌急得臉都紅了，說：「臣……臣嘴巴不會說話，可是臣期……期期知道這樣做不行！陛下就算要換太子，臣期……期期不接受這道命令！」',
      '劉邦聽他「期期、期期」說個不停，忍不住哈哈大笑，換太子的事也就暫時放下了。周昌雖然說得結結巴巴，卻是真心為國家著想。',
      { h: '第二個故事：鄧艾的「艾艾」' },
      '過了四百多年，到了三國時代，魏國有一位很會打仗的將領，叫做鄧艾。鄧艾說話也會結巴，每次說到自己的名字，常常說成「艾……艾……」。',
      '有一天，當時的丞相司馬懿故意開他的玩笑：「你老是說艾艾，到底有幾個艾啊？」鄧艾不慌不忙的回答：「古書裡唱『鳳兮鳳兮』，說了兩次鳳，也只是一隻鳳啊。」這個回答又有學問又機靈，大家都很佩服。',
      '後來，人們把周昌的「期期」和鄧艾的「艾艾」合在一起，成了「期期艾艾」，用來形容說話結結巴巴、不順暢的樣子。',
      '要注意，這裡的「期期」不是「期待」的意思，「艾艾」也不是植物艾草，兩個詞都是在模仿口吃時重複的聲音。另外，兩位主角雖然說話結巴，卻都是有勇氣、有智慧的人，說話結巴並不代表能力不好。'
    ],
    mean: '形容說話口吃、結結巴巴、不流暢的樣子。',
    usage: ['用來形容說話口吃、結巴，或因為緊張、害羞而說得不順。', '「期期」不是期待，「艾艾」也不是艾草，都是模仿口吃重複的聲音。', '描述別人時要注意禮貌，不要拿來嘲笑說話結巴的人；故事裡的周昌和鄧艾都是很有能力的人。'],
    misuse: ['「全班期期艾艾的等著校外教學那一天快點到來。」✗　「期期」不是期待的意思；期期艾艾是形容說話結巴，盼望某件事要說「滿心期待」。'],
    eg: ['第一次上台報告，我緊張得期期艾艾，連自己的名字都說得結結巴巴。', '弟弟打破了花瓶，被問起時期期艾艾，半天說不出一句完整的話。'],
    syn: ['結結巴巴'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '劉邦想做什麼事，周昌急著反對？', opts: ['把原本的太子換掉', '把首都搬到別的地方', '出兵攻打其他國家', '把周昌趕出朝廷'], a: 0, why: '第三段：劉邦想把原本的太子換掉，改立如意。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '鄧艾說「鳳兮鳳兮」，是想說明「艾艾」其實只有一個艾。', a: true, why: '第八段：說了兩次鳳，也只是一隻鳳；同樣的，說了兩次艾，也只有一個鄧艾。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '周昌說話結巴，卻還是堅持當面反對，表示他是怎樣的人？', opts: ['耿直、真心為國家著想', '喜歡惹皇帝生氣的人', '說話很好笑的人', '不想當官的人'], a: 0, why: '第三、五段：周昌「個性耿直，有話直說」，雖然結巴，「卻是真心為國家著想」。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '「期期艾艾」這個成語是怎麼來的？', opts: ['兩個口吃的人的故事合起來', '一個人期待吃到艾草的故事', '鄧艾和周昌一起說話的故事', '劉邦開周昌玩笑的故事'], a: 0, why: '第一段和第九段：周昌的「期期」加上鄧艾的「艾艾」，兩人相隔四百多年，並沒有一起說話。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '文章最後說：「說話結巴並不代表能力不好。」你同意嗎？如果班上有同學說話結巴，被別人笑，你會怎麼做？請用故事內容說明。',
        ref: '我同意。周昌雖然結巴，卻敢當面勸皇帝；鄧艾也結巴，卻能用古書機靈的回答，他們都很有勇氣和智慧。如果有同學被笑，我會跟笑他的人說「他說慢一點我們也聽得懂」，也會耐心等他把話說完。',
        rubric: ['表明同意或不同意', '用故事中周昌或鄧艾的例子當理由', '提出尊重或幫助同學的具體做法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「期期艾艾」形容什麼樣子？', opts: ['說話結結巴巴', '滿心期待某件事', '很喜歡艾草', '做事慢吞吞'], a: 0, why: '期期艾艾是模仿口吃重複的聲音，形容說話結巴。「期期」不是期待。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小宇第一次在全校朝會上領獎，校長請他說兩句得獎感言。他看著台下上千個同學，心臟跳得好快，拿著麥克風說：「我……我……很……很高興……謝……謝謝……」說了好久才講完一句話，臉紅得像番茄一樣。台下的同學都替他捏了一把冷汗，等他說完，才一起用力鼓掌。', q: '小宇說得獎感言的樣子，最適合用哪個成語形容？', opts: ['期期艾艾', '文不加點', '老生常談', '首鼠兩端'], a: 0, why: '小宇緊張得說話結結巴巴，就是期期艾艾。首鼠兩端是猶豫不決，不是說話結巴。' },
      { id: 'p3', k: 'judge', d: 2, type: 'tf', q: '「大家都期期艾艾的盼望暑假趕快到來。」這句話的「期期艾艾」用得恰當。', a: false, why: '「期期」不是期待；期期艾艾是說話結巴，不能形容盼望。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈日記〉今天我在班會上報告運動會的分工。前一天我練習了好多次，所以上台時說得很順，一句也沒有卡住，同學們都聽得很清楚。我真是期期艾艾！', q: '日記裡的「期期艾艾」用得恰當嗎？', opts: ['不恰當，他說得很順，這個詞是說結巴', '恰當，因為他事前一直很期待上台報告', '恰當，因為他上台前練習了好多次', '不恰當，因為班會不能上台報告'], a: 0, why: '期期艾艾是說話結巴。他說得很順、沒有卡住，剛好相反。這裡把「期期」誤會成「期待」或稱讚。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '上台說話時，很多人都會緊張到「期期艾艾」。你有什麼方法可以幫自己說得更順？如果聽到別人說得結結巴巴，你又可以怎麼幫他？',
        ref: '我上台前會先深呼吸三次，把要說的話寫成重點小卡，看著卡片說就比較不會卡住。如果別人說得結結巴巴，我會安靜的等他說完，不催他，也不笑他，最後給他拍拍手，讓他下次更有勇氣。',
        rubric: ['提出讓自己說得更順的方法', '提出對結巴的人友善的做法', '做法具體可行'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '面試時他太緊張了，回答問題時＿＿＿＿，一句話要停好幾次才說得完。', opts: ['期期艾艾', '文不加點', '門庭若市', '愛屋及烏'], a: 0, why: '一句話要停好幾次，是說話結巴，用期期艾艾。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '媽媽：「妹妹練了一個星期的英文自我介紹，今天在台上說得好流暢呀！」\n哥哥：「是啊，她說得期期艾艾，一點都沒有卡住。」', q: '哥哥說的「期期艾艾」用得恰當。', a: false, why: '期期艾艾是說話結巴。妹妹說得很流暢，不能用期期艾艾。' }
    ]
  },
  {
    id: 'cy085', lv: 4, word: '愛屋及烏', zhuyin: 'ㄞˋ ㄨ ㄐㄧˊ ㄨ', src: '《尚書大傳．大戰》',
    quote: '愛人者兼其屋上之烏',
    facts: ['典出《尚書大傳．大戰》｜教育部《成語典》', '周武王在牧野打敗紂王、商朝滅亡後，不知道怎麼安置殷商遺民，召集大臣商議｜教育部《成語典》典故說明', '姜太公、召公先後提出主張，武王都不認同；周公主張讓百姓安居樂業並舉用賢人，武王讚許並採用｜教育部《成語典》典故說明', '「愛人者兼其屋上之烏」是姜太公說的話｜《尚書大傳．大戰》'],
    story: [
      '三千多年前，商朝的最後一個君王紂王非常殘暴，百姓過得很痛苦。周武王帶著軍隊和紂王在牧野大戰，打敗了商朝，商朝就這樣結束了。',
      '戰爭結束了，武王卻遇到一個難題：商朝留下來的大臣、士兵和百姓那麼多，到底該怎麼對待他們呢？他把幾位重要的大臣找來商量。',
      '第一個開口的是姜太公。他說：「我聽說，喜愛一個人，就會連他家屋頂上的烏鴉也一起喜愛；討厭一個人，就連他家附近的東西都討厭。商朝的人是我們的敵人，乾脆一個也不要留下。」武王聽了，搖搖頭說：「不行。」',
      '接著，召公說：「有罪的人就處罰，沒有罪的人就讓他們好好過日子。」武王想了想，還是說：「這樣也不夠好。」',
      '最後，周公說：「讓每個人都回到自己的家，耕種自己的田地；不分新朝舊朝，只要是有才德的人，就請他出來做事。」武王聽了，非常高興的說：「說得真好！天下就能安定了。」武王採用了周公的辦法。',
      '有趣的是，「愛屋及烏」這句話，原本是姜太公說的，而他的建議並沒有被武王採用。但是這個比喻太生動了：一隻烏鴉，本來和人沒有什麼關係，只因為牠停在心愛的人的屋頂上，就連牠也一起喜歡了。所以這句話一直流傳下來，變成了一個成語。',
      '今天說「愛屋及烏」，是比喻愛一個人，也會連帶關愛和他有關的一切人、事、物。它的重點在「因為愛一個人，所以連帶喜歡」，不是說喜歡房子或喜歡烏鴉。'
    ],
    mean: '因為愛一個人，連帶也愛他屋頂上的烏鴉。比喻愛一個人，也連帶關愛和他有關的一切。',
    usage: ['用在因為喜歡某個人，連帶喜歡、關心和他有關的人、事、物。', '一定要有「先愛一個人，再連帶愛其他東西」的關係；單純喜歡房子或喜歡鳥，不能說愛屋及烏。', '它是在說喜愛、關懷，帶有連帶偏愛的意思；《成語典》正文沒有列近義、反義成語。'],
    misuse: ['「表哥很愛乾淨，每天都把房子打掃得亮晶晶，真是愛屋及烏。」✗　愛屋及烏不是愛房子，而是因為愛一個人，連帶愛和他有關的一切。'],
    eg: ['阿嬤很疼我，連我的好朋友來家裡，她都準備一大盤水果，真是愛屋及烏。', '姊姊喜歡那位作家，愛屋及烏，連作家養的貓的照片都收集起來。'],
    syn: [], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '周武王打敗紂王以後，遇到什麼難題？', opts: ['怎麼對待商朝留下的人', '找不到可以住的宮殿', '軍隊的糧食吃完了', '烏鴉飛到宮殿屋頂上'], a: 0, why: '第二段：商朝留下來的人那麼多，「到底該怎麼對待他們呢？」' },
      { id: 'r2', p: 1, d: 1, type: 'order', q: '依照文章，排出大臣們提出建議的先後順序。', items: ['姜太公', '召公', '周公'], why: '第三段姜太公先說，第四段召公接著說，第五段周公最後說。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '武王聽完周公的話「非常高興」，表示武王希望怎麼對待商朝的人？', opts: ['讓大家安心過日子', '把商朝的人都趕走', '只照顧周朝自己的人', '請烏鴉替他看守百姓'], a: 0, why: '周公主張讓每個人回家耕田、有才德的人出來做事，武王讚許並採用，可見他希望大家都能安心過日子。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '「愛屋及烏」原本是誰說的？他的建議有沒有被採用？', opts: ['姜太公說的，沒有被採用', '周公說的，被採用了', '召公說的，被採用了', '武王說的，沒有被採用'], a: 0, why: '第三段是姜太公說的；第六段說他的建議「並沒有被武王採用」，被採用的是周公的辦法。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '姜太公說：愛一個人，就連他屋上的烏鴉也愛；討厭一個人，就連他身邊的東西都討厭。你覺得這種「連帶」的感覺，有什麼好處和壞處？請舉例說明。',
        ref: '好處是會讓人更體貼，例如我喜歡好朋友，也會對他的弟弟比較好。壞處是可能不公平，例如因為討厭一個人，就連他的朋友也討厭，可是他的朋友根本沒做錯事。就像周公說的，應該看每個人自己的表現。',
        rubric: ['說出連帶感覺的好處並舉例', '說出壞處並舉例', '能連結故事內容（例如周公的做法）'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「愛屋及烏」的意思是什麼？', opts: ['愛一個人，也連帶愛他的一切', '非常喜歡自己從小住的房子', '很喜歡在家裡的屋頂養烏鴉', '愛護動物，保護環境'], a: 0, why: '愛屋及烏是因為愛一個人，連帶也愛和他有關的一切，不是愛房子或烏鴉。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小安最喜歡的表哥在讀大學，他是學校籃球隊的隊員。自從知道表哥喜歡打籃球，小安也開始每天看籃球比賽，還把表哥大學球隊的隊徽貼在書包上，連表哥喜歡的那家麵店，小安每次經過都想進去吃一碗。', q: '小安的情形，最適合用哪個成語形容？', opts: ['愛屋及烏', '老生常談', '首鼠兩端', '門可羅雀'], a: 0, why: '因為喜歡表哥，連帶喜歡籃球、隊徽和麵店，就是愛屋及烏。' },
      { id: 'p3', k: 'judge', d: 2, type: 'tf', q: '「他很喜歡大自然，每天都去公園看烏鴉和麻雀，真是愛屋及烏。」這句話的「愛屋及烏」用得恰當。', a: false, why: '他是本來就喜歡鳥，沒有「因為愛一個人而連帶喜歡」的關係，不能用愛屋及烏。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈部落格〉我最喜歡的歌手出了新專輯，我不只買了專輯，連他在節目裡推薦的書、他喜歡的那款帽子，我都想辦法買來。我想，這就是愛屋及烏吧！', q: '這段話的「愛屋及烏」用得恰當嗎？', opts: ['恰當，因為喜歡歌手而連帶喜歡', '不恰當，愛屋及烏只能用在家人之間', '不恰當，因為他買的東西裡沒有房子', '恰當，因為他花了很多錢買東西'], a: 0, why: '因為喜歡歌手，連帶喜歡他推薦的書和帽子，用愛屋及烏恰當。它不限於家人，也和花多少錢無關。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '因為喜歡一個人而「愛屋及烏」，有時很溫暖，有時卻會讓自己不夠冷靜（例如亂花錢）。想一個你曾經愛屋及烏的例子，說說它帶來的好處，以及你要注意的地方。',
        ref: '我很喜歡班導，所以連她推薦的書我都去借來看，結果發現了好多好看的書，這是好處。不過我也要注意，不能因為喜歡一個人，就覺得他說的每件事都一定對，還是要自己想一想。',
        rubric: ['說出一個自己愛屋及烏的例子', '說出它帶來的好處', '說出需要注意的地方'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '奶奶很疼小孫子，＿＿＿＿，連孫子養的小倉鼠都每天幫忙餵。', opts: ['愛屋及烏', '期期艾艾', '門可羅雀', '首鼠兩端'], a: 0, why: '因為疼孫子，連孫子的倉鼠也照顧，用愛屋及烏。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '王先生的女兒在一所國小當志工。自從女兒開始在那所國小幫忙，王先生每次經過學校，都會停下來看看；學校辦園遊會，他一定去捧場；聽說學校的圖書館缺書，他還捐了一百本童書。他說：「女兒喜歡這裡，我也就跟著喜歡這所學校了。」', q: '王先生對這所學校的感情，可以用哪個成語形容？', opts: ['愛屋及烏', '三顧茅廬', '門庭若市', '後生可畏'], a: 0, why: '因為愛女兒，連帶喜歡女兒服務的學校，是愛屋及烏。' }
    ]
  },
  {
    id: 'cy088', lv: 4, word: '不求甚解', zhuyin: 'ㄅㄨˋ ㄑㄧㄡˊ ㄕㄣˋ ㄐㄧㄝˇ', src: '晉．陶潛〈五柳先生傳〉',
    quote: '好讀書，不求甚解，每有會意，便欣然忘食',
    facts: ['語出晉．陶潛〈五柳先生傳〉｜教育部《成語典》', '陶潛字元亮，東晉潯陽柴桑人；四十一歲出任彭澤令，只做了八十多天，因不願整衣迎接督郵而辭官歸隱｜教育部《成語典》典故說明', '原指讀書著重理解義理，不過度鑽研字句；後來也形容學習或工作態度不認真，只懂皮毛｜教育部《成語典》釋義、用法說明', '近義成語有「一知半解」「囫圇吞棗」，反義成語有「融會貫通」「尋根究底」｜教育部《成語典》辨識'],
    story: [
      '東晉的時候，有一位詩人叫陶潛，也有人叫他陶淵明。他的曾祖父曾經是大官，可是到了他這一代，家裡已經很窮了。',
      '陶潛做過幾次官，最後一次是當彭澤縣的縣令。才當了八十多天，上級派了一位叫「督郵」的官員來視察，有人提醒陶潛：「您得穿戴整齊，恭恭敬敬的去迎接。」陶潛不願意為了一點薪水，就對人彎腰討好，乾脆辭了官，回到鄉下種田。',
      '陶潛寫過一篇短短的文章，叫〈五柳先生傳〉。文章裡的主角，家門口種著五棵柳樹，所以叫「五柳先生」。很多人認為，五柳先生就是陶潛在寫他自己。',
      '文章裡說，五柳先生個性安靜，話不多，不羨慕名利。他很喜歡讀書，但讀書時「不求甚解」：不會為了一個字、一句話的解釋鑽牛角尖，而是用心體會書裡的道理。每當讀到心有所感的地方，他就高興得連吃飯都忘了。',
      '他住的房子很簡陋，擋不住風吹日曬；衣服破了，就補一補繼續穿。但是他一點也不在意，常常寫文章自娛，過得自由自在。',
      '你看，陶潛說的「不求甚解」，原本並不是壞事。他的意思是讀書要抓住大意、讀懂道理，不要只顧著咬文嚼字。',
      '可是，後來的人用這個成語時，意思慢慢多了一層。今天我們說一個人「不求甚解」，常常是在批評他學東西不認真，只懂一點皮毛，就以為自己懂了。',
      '所以，「不求甚解」有兩種意思：讀陶潛的文章時，要知道它原本是「讀書重在體會道理」；在今天的生活裡，它多半是指「學習或工作態度隨便、不深入」。用的時候，要看清楚上下文。'
    ],
    mean: '原本是讀書著重理解道理，不過度鑽研字句的解釋；後來也用來形容學習或工作的態度不認真，只求略懂皮毛、不深入了解。',
    usage: ['今天多用在批評學習、做事只懂皮毛、不肯深入了解（貶義）。', '讀陶潛〈五柳先生傳〉時，要知道它原本是「讀書重在體會道理」，不是批評。', '近義成語有「一知半解」「囫圇吞棗」，反義成語有「融會貫通」「尋根究底」。'],
    misuse: ['「他讀書不求甚解，每個不懂的字都去查字典，還做了好多筆記。」✗　查字典、做筆記是深入了解，跟今天說的不求甚解正好相反，應該說「尋根究底」。'],
    eg: ['做實驗不能不求甚解，只看結果，不想想為什麼會這樣。', '弟弟讀說明書不求甚解，只看了圖片就開始組裝，結果零件裝反了。'],
    syn: ['一知半解', '囫圇吞棗'], ant: ['融會貫通', '尋根究底'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '陶潛為什麼辭去彭澤縣令？', opts: ['不願為了薪水向人彎腰討好', '生了一場重病，沒辦法工作', '家裡的田地需要人照顧', '皇帝下命令要他回鄉下去'], a: 0, why: '第二段：陶潛「不願意為了一點薪水，就對人彎腰討好，乾脆辭了官」。' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '五柳先生讀到心有所感的地方「高興得連吃飯都忘了」，表示什麼？', opts: ['他是真心喜歡讀書', '他家裡沒有飯可以吃', '他讀書讀到太累了', '他本來就不愛吃飯'], a: 0, why: '讀到有體會的地方，快樂得忘了吃飯，可見他是真心喜歡讀書、用心體會。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '「不求甚解」原本和後來的意思有什麼不同？', opts: ['原本是重在體會道理；後來多指學習不認真', '原本是學習不認真；後來是重在體會道理', '一直都是指讀書非常認真', '一直都是指喜歡種柳樹'], a: 0, why: '第六段說原本不是壞事，是讀書抓大意、讀懂道理；第七段說今天常用來批評學東西不認真。' },
      { id: 'r4', p: 4, d: 3, type: 'open', q: '陶潛讀書「不求甚解」，只抓大意；也有人認為讀書要一字一句弄清楚。你覺得哪一種讀法比較好？還是要看讀什麼書？請舉例說明。',
        ref: '我覺得要看讀什麼書。讀小說、故事書時，可以像陶潛一樣先抓大意，享受故事，不用每個字都查。可是讀數學課本或實驗步驟時，就要一句一句弄清楚，不然會算錯、做錯。',
        rubric: ['表明自己的看法', '能分辨不同情況適合不同讀法', '舉出具體的例子'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '今天說一個人讀書「不求甚解」，通常是什麼意思？', opts: ['只懂皮毛，不深入了解', '讀書非常仔細認真', '很喜歡讀古人的書', '讀書讀到忘了吃飯'], a: 0, why: '今天說不求甚解，多半是批評學習態度不認真，只懂皮毛。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '自然課要做「紙杯電話」，老師發了一張說明，提醒大家先讀懂聲音為什麼能傳過去。阿凱只看了一眼圖片，就急著剪剪貼貼，線也沒有拉緊。做好以後聽不到聲音，他也不去想原因，只說：「反正大概就是這樣，算我做完了吧。」', q: '阿凱做實驗的態度，最適合用哪個成語形容？', opts: ['不求甚解', '文不加點', '後生可畏', '愛屋及烏'], a: 0, why: '阿凱只看一眼就做，出了問題也不想原因，只懂皮毛、不深入了解，是不求甚解。' },
      { id: 'p3', k: 'judge', d: 2, type: 'tf', q: '「讀歷史課本時，他不求甚解，對不懂的地方一定追問到底。」這句話的「不求甚解」用得恰當。', a: false, why: '追問到底是尋根究底，跟不求甚解相反。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈讀書會紀錄〉今天討論陶潛的〈五柳先生傳〉。小芸說：「五柳先生讀書不求甚解，每讀到有感覺的地方就高興得忘了吃飯，他是真的愛讀書。」', q: '小芸這裡用「不求甚解」恰當嗎？', opts: ['恰當，她用的是原本的意思', '不恰當，這個詞只能用來批評人', '不恰當，五柳先生其實不愛讀書', '恰當，因為五柳先生常常忘了吃飯'], a: 0, why: '在討論〈五柳先生傳〉時，用的是原本「讀書重在體會道理」的意思，恰當。不求甚解不是只能批評人，要看上下文。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '不求甚解有時可以（例如輕鬆讀故事），有時卻不行（例如讀實驗步驟）。想一件你曾經「只懂皮毛」就去做，結果出問題的事，下次你會怎麼「求甚解」？',
        ref: '我上次幫忙用洗衣機，只看了一個按鈕就按下去，結果把毛衣洗縮水了。下次我會先看清楚衣服上的洗標，再讀說明書，弄懂每個按鈕的用途，不懂的地方先問大人再按。',
        rubric: ['說出一件只懂皮毛就做而出問題的事', '說明問題出在沒有深入了解', '提出深入了解的具體做法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '學桌遊不能＿＿＿＿，規則沒看懂就開始玩，一定會吵起來。', opts: ['不求甚解', '三顧茅廬', '期期艾艾', '門庭若市'], a: 0, why: '規則沒看懂就玩，是只懂皮毛，用不求甚解。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '小明：「這次報告的資料，我只看了網路上第一筆搜尋結果的標題，就直接抄下來了。」\n組長：「這樣不求甚解，報告裡可能會有錯誤喔。」', q: '組長說的「不求甚解」用得恰當。', a: true, why: '只看標題就抄，沒有深入了解，用不求甚解提醒他，恰當。' }
    ]
  },
  {
    id: 'cy091', lv: 4, word: '後生可畏', zhuyin: 'ㄏㄡˋ ㄕㄥ ㄎㄜˇ ㄨㄟˋ', src: '《論語．子罕》',
    quote: '後生可畏，焉知來者之不如今也',
    facts: ['語出《論語．子罕》，是孔子說的話｜教育部《成語典》', '孔子周遊列國十三年未獲重用，晚年回到魯國整理典籍，以「有教無類」收徒，弟子約三千人｜教育部《成語典》典故說明', '這句話既肯定年輕人，也勉勵年長者不可懈怠；後來比喻年輕人的成就超越先輩，令人敬畏｜教育部《成語典》典故說明、釋義', '《論語．子罕》同一章接著說：到了四十、五十歲還沒有好名聲，就不值得敬畏了｜《論語．子罕》'],
    story: [
      '春秋時代的孔子，是中國最有名的老師。他曾經在魯國做官，後來因為理想和國君不合，離開魯國，帶著學生到各國去，走了十三年，希望有國君願意採用他的想法。',
      '可惜，一直沒有國君真正重用他。年紀大了以後，孔子回到魯國，專心整理古代的書籍，並且教導學生。他收學生不分貴賤、貧富，相傳前前後後有三千人跟他學習。',
      '孔子的學生大多比他年輕得多。有的學生聰明伶俐，有的學生非常勤奮，常常提出讓孔子也覺得新鮮的看法。孔子看著這些年輕人一天天成長，心裡很高興。',
      '孔子曾經說：「年輕人是值得敬畏的。怎麼知道他們將來不會比現在的人更好呢？」意思是：年輕人有大好的時光，只要肯努力，將來的成就很可能超越前輩，所以不能小看他們。',
      '但是孔子接著又說：「如果到了四十歲、五十歲，還是沒有什麼好的表現，那也就不值得敬畏了。」這句話提醒年輕人：「可畏」不是因為年紀小，而是因為有努力的時間和成長的可能。如果把時間浪費掉，再好的條件也沒有用。',
      '這段話同時也是在提醒年紀大的人：不要以為自己年紀大、經驗多，就可以停下腳步，年輕人隨時可能追上來、超過你。',
      '後來，人們就用「後生可畏」比喻年輕人的成就超越前輩，令人敬畏、佩服。這裡的「畏」是敬畏、佩服，不是害怕；「後生」是年輕人、晚輩。'
    ],
    mean: '年輕人前途無量，令人敬畏。比喻年輕人的成就超越先輩，讓人佩服。',
    usage: ['用來稱讚年輕人、晚輩表現出色，甚至超越前輩（褒義），多由長輩或前輩說出。', '「畏」是敬畏、佩服，不是害怕；不能用來形容年輕人很兇、很可怕。', '近義成語是「青出於藍」，反義成語是「乳臭未乾」。'],
    misuse: ['「那群少年在公園裡大吵大鬧，還亂丟垃圾，真是後生可畏。」✗　後生可畏是稱讚年輕人表現出色、令人佩服，不是說年輕人讓人害怕。'],
    eg: ['這位十二歲的棋手打敗了好幾位職業選手，老棋手們都說後生可畏。', '學弟第一次參加科展就拿到全國第一名，學長們直呼後生可畏。'],
    syn: ['青出於藍'], ant: ['乳臭未乾'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '孔子離開魯國，到各國去走了幾年？', opts: ['十三年', '三年', '三十年', '四十年'], a: 0, why: '第一段：「帶著學生到各國去，走了十三年。」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '孔子說「怎麼知道他們將來不會比現在的人更好」，表示他對年輕人的態度是什麼？', opts: ['看好他們，不小看他們', '擔心他們不聽話', '覺得他們太年輕不懂事', '希望他們早點離開'], a: 0, why: '第四段：年輕人將來的成就可能超越前輩，「所以不能小看他們」。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '把孔子前後兩段話合起來看，年輕人「可畏」的真正原因是什麼？', opts: ['年輕人有成長的可能', '年輕人的年紀比較小', '年輕人說話比較大聲', '年輕人比較不聽話'], a: 0, why: '第五段：「可畏」不是因為年紀小，而是因為有努力的時間和成長的可能；浪費掉就不值得敬畏了。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '第六段說，這段話也在提醒「年紀大的人」什麼？', opts: ['不能因經驗多就停止進步', '年紀大了就應該在家退休', '要多跟年輕人一起出去玩', '要小心年輕人搶東西'], a: 0, why: '第六段：「不要以為自己年紀大、經驗多，就可以停下腳步」。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '孔子說年輕人「可畏」，但也說如果浪費時間，到了四十、五十歲就不值得敬畏了。你覺得這段話對你這個年紀的人有什麼提醒？請說明理由。',
        ref: '我覺得這段話提醒我：我現在年紀小，有很多時間可以學東西，這是我的優勢。可是如果每天只玩手機、不努力，時間過去了，就什麼也沒學到。所以我要好好利用時間，例如每天讀一點書、練一項自己喜歡的才藝。',
        rubric: ['說出這段話對自己的提醒', '能說明「時間」和「努力」的關係', '提出具體的行動'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「後生可畏」的「畏」在這裡是什麼意思？', opts: ['敬畏、佩服', '害怕、恐懼', '生氣、討厭', '擔心、緊張'], a: 0, why: '「畏」在這裡是敬畏、佩服，不是害怕。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '社區舉辦書法比賽，參賽的大多是練了幾十年的爺爺奶奶。沒想到這次第一名是一位才五年級的小女孩，她的字寫得端正有力，連評審都說找不到缺點。已經得過好幾次冠軍的李爺爺看了她的作品，笑著說：「這孩子將來一定比我們都厲害！」', q: '李爺爺的心情，最適合用哪個成語形容？', opts: ['後生可畏', '乳臭未乾', '老生常談', '門可羅雀'], a: 0, why: '年輕的小女孩表現超越前輩，李爺爺很佩服，就是後生可畏。乳臭未乾是看不起年輕人，相反。' },
      { id: 'p3', k: 'judge', d: 2, type: 'tf', q: '「新來的實習醫生雖然年輕，手術卻做得又快又好，資深醫生都說後生可畏。」這句話的「後生可畏」用得恰當。', a: true, why: '年輕醫生表現出色，前輩佩服，用後生可畏恰當。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈新聞短評〉幾位青少年深夜在街上飆車、按喇叭，吵得附近居民都睡不著，還差點撞到路人。記者在短評裡寫：「這些少年真是後生可畏，讓人看了心驚膽跳。」', q: '記者用「後生可畏」恰當嗎？', opts: ['不恰當，它是稱讚，不是說可怕', '恰當，因為這些少年真的讓人害怕', '恰當，因為這些少年的年紀很輕', '不恰當，因為記者沒有寫出名字'], a: 0, why: '後生可畏的「畏」是敬畏、佩服，用來稱讚年輕人。飆車讓人害怕，不能用後生可畏。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '你身邊有沒有讓你覺得「後生可畏」的弟弟妹妹或學弟學妹？他哪裡讓你佩服？你可以向他學習什麼？',
        ref: '我的表弟才二年級，已經會自己用積木做出會動的小車，還會跟我解釋齒輪怎麼轉。我很佩服他遇到問題會一直試，不會放棄。我可以學他的耐心，遇到難的數學題不要馬上說不會。',
        rubric: ['舉出一位年紀比自己小的人', '說出他讓人佩服的具體表現', '說出自己可以學習的地方'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '這位十五歲的少年設計的手機程式，被上萬人下載使用，真是＿＿＿＿。', opts: ['後生可畏', '乳臭未乾', '老生常談', '期期艾艾'], a: 0, why: '年輕人做出很大的成就，令人佩服，用後生可畏。乳臭未乾是嫌人年輕不懂事，和句子意思矛盾。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '學校樂隊的阿傑學長練了三年鼓。這學期新加入的三年級學弟才練兩個月，就能把整首進行曲打得又穩又準，還自己編了一段好聽的鼓點。阿傑學長拍拍學弟的肩膀說：「再過一年，換我要跟你學了。」', q: '阿傑學長對學弟的感覺，可以用哪個成語形容？', opts: ['後生可畏', '老生常談', '愛屋及烏', '期期艾艾'], a: 0, why: '年紀小的學弟進步神速，學長佩服他、覺得他會超越自己，是後生可畏。' }
    ]
  },
  {
    id: 'cy094', lv: 4, word: '首鼠兩端', zhuyin: 'ㄕㄡˇ ㄕㄨˇ ㄌㄧㄤˇ ㄉㄨㄢ', src: '《史記．魏其武安侯列傳》',
    quote: '何為首鼠兩端',
    facts: ['語出《史記．魏其武安侯列傳》｜教育部《成語典》', '丞相田蚡娶親的宴席上，灌夫勸酒受到冷落，當眾發脾氣，觸怒田蚡；灌夫的好友竇嬰出面營救｜教育部《成語典》典故說明', '漢武帝召集大臣評議，御史大夫韓安國兩方都不得罪，說都有道理，請皇帝裁斷；之後田蚡責備他猶豫不決｜教育部《成語典》典故說明', '「首鼠」有兩種說法：一說老鼠生性多疑、出洞前探頭張望；一說「首鼠」是「躊躇」的音轉｜歷來注解（作者整理，《成語典》正文未收此注）'],
    story: [
      '西漢漢武帝的時候，朝廷裡有兩位很有勢力的人：一位是老臣竇嬰，被封為魏其侯；一位是太后的弟弟田蚡，被封為武安侯，當時正擔任丞相。兩個人一向合不來。',
      '竇嬰有一位好朋友叫灌夫，是個武將，個性剛直，喜歡喝酒，說話很衝，得罪過不少有權勢的人。',
      '有一次，田蚡娶親，大擺宴席，朝廷的大臣幾乎都來了。宴席上，灌夫起身向大家敬酒，可是好幾個人只是隨便應付，對他愛理不理。灌夫越想越氣，忍不住當著眾人的面發起脾氣，把宴會鬧得很難看。',
      '田蚡非常生氣，決定要重重的處罰灌夫。竇嬰知道了，趕緊出面替好朋友說情，兩邊吵得不可開交，最後鬧到了皇帝面前。',
      '漢武帝把大臣們找來，讓大家說說看，到底是誰對、誰錯。竇嬰說灌夫立過功勞，只是喝醉了；田蚡說灌夫太過分，不能放過。皇帝轉頭問御史大夫韓安國的意見。',
      '韓安國想了又想，兩邊都不想得罪。他說：「魏其侯說得有道理，丞相說得也有道理，還是請陛下自己決定吧。」其他大臣也大多不敢表態，這場討論最後沒有結果，就散了。',
      '退朝以後，田蚡很不高興，他把韓安國叫上自己的車，責備他：「竇嬰已經沒有什麼權勢了，你何必為了他畏首畏尾，兩邊都不敢得罪呢？」',
      '田蚡說的「首鼠兩端」，有一種說法是：老鼠生性多疑，做事畏首畏尾，拿不定主意；也有人認為「首鼠」就是「躊躇」，是聲音轉變而來的。不管是哪一種說法，意思都是猶豫不決。',
      '後來，人們就用「首鼠兩端」形容猶豫不決、拿不定主意，在兩邊之間搖擺的樣子。'
    ],
    mean: '形容猶豫不決、拿不定主意的樣子。',
    usage: ['用在面對兩個選擇或兩方意見，一直猶豫、不敢決定的時候（貶義）。', '只是「兩邊跑來跑去」或「很忙碌」，不能說首鼠兩端；重點是「心裡猶豫，拿不定主意」。', '近義成語有「猶豫不定」「舉棋不定」，反義成語有「當機立斷」「毅然決然」。'],
    misuse: ['「下課十分鐘，他一下跑到操場、一下跑回教室，首鼠兩端，忙得滿頭大汗。」✗　首鼠兩端是心裡猶豫不決，不是身體在兩個地方跑來跑去。'],
    eg: ['要參加足球隊還是合唱團，阿明首鼠兩端，報名截止了還沒決定。', '店長在兩張設計稿之間首鼠兩端，拖了一個月才選定新招牌。'],
    syn: ['猶豫不定', '舉棋不定', '狐疑不決'], ant: ['當機立斷', '毅然決然'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '灌夫在哪一個場合發脾氣？', opts: ['田蚡娶親的宴席上', '皇帝上朝的時候', '竇嬰的生日宴會', '打仗的戰場上'], a: 0, why: '第三段：「田蚡娶親，大擺宴席……灌夫……忍不住當著眾人的面發起脾氣。」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '韓安國說「兩邊都有道理，請陛下自己決定」，他心裡最可能在想什麼？', opts: ['兩邊都有勢力，誰都不想得罪', '他真的覺得兩邊一樣對', '他根本沒聽清楚兩人的話', '他想趕快回家休息'], a: 0, why: '第六段：韓安國「兩邊都不想得罪」。竇嬰是老臣、田蚡是丞相，他怕得罪任何一邊。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '田蚡罵韓安國「首鼠兩端」，是在責備他什麼？', opts: ['猶豫不決，不肯表態', '跑得太慢，像老鼠一樣', '說話太大聲，吵到皇帝', '偷偷幫灌夫說好話'], a: 0, why: '第七、八段：田蚡責備他畏首畏尾、兩邊都不敢得罪，「首鼠兩端」就是猶豫不決。' },
      { id: 'r4', p: 4, d: 3, type: 'open', q: '韓安國兩邊都不得罪，看起來很「安全」，卻被田蚡責備。你覺得在大家意見不同時，「不表態」是好方法嗎？請用故事內容說明你的看法。',
        ref: '我覺得不一定是好方法。韓安國不表態，討論就沒有結果，最後還被田蚡責備，兩邊都不滿意。如果真的覺得兩邊都有道理，可以說清楚哪裡有道理、哪裡不對，提出自己的建議，而不是把問題丟給別人。',
        rubric: ['表明看法', '用故事內容當理由（討論沒有結果、被責備）', '提出比較好的做法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「首鼠兩端」形容什麼？', opts: ['猶豫不決的樣子', '老鼠跑得很快', '兩邊都很忙碌', '頭很痛的樣子'], a: 0, why: '首鼠兩端形容猶豫不決、拿不定主意，跟老鼠跑得快、忙碌無關。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '班上要決定園遊會賣什麼。一半的同學想賣珍珠奶茶，一半想賣烤香腸。負責做決定的班長，聽到這邊說奶茶好，就說「好像奶茶不錯」；聽到那邊說香腸好，又說「香腸也可以啦」。一個星期過去，報名表還是空白，其他班早就開始準備了。', q: '班長的表現，最適合用哪個成語形容？', opts: ['首鼠兩端', '當機立斷', '老生常談', '愛屋及烏'], a: 0, why: '班長在兩個選擇之間搖擺，一直拿不定主意，就是首鼠兩端。當機立斷意思相反。' },
      { id: 'p3', k: 'pair', d: 2, type: 'match', q: '這些成語跟「首鼠兩端」是什麼關係？配起來。', pairs: [['舉棋不定', '近義成語'], ['當機立斷', '反義成語'], ['門可羅雀', '意思無關']], why: '舉棋不定是拿著棋子不知道下哪裡，相近；當機立斷是馬上做決定，相反；門可羅雀是冷清，無關。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈日記〉今天大掃除，我先去擦窗戶，擦完又跑去倒垃圾，接著又回教室掃地，一個人跑來跑去做了好多事。同學說我真是首鼠兩端，好勤勞！', q: '日記裡的「首鼠兩端」用得恰當嗎？', opts: ['不恰當，它是猶豫不決，不是勤勞', '恰當，因為他跑來跑去做了很多事', '恰當，因為他一次做了兩件事', '不恰當，因為教室裡沒有老鼠'], a: 0, why: '首鼠兩端是心裡猶豫不決（貶義），不是勤勞地跑來跑去。成語是比喻，跟有沒有老鼠無關。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '想一次你在兩個選擇之間「首鼠兩端」、一直拿不定主意的經驗。後來結果怎麼樣？下次遇到難以決定的事，你可以用什麼方法幫自己做決定？',
        ref: '我上次在書店拿著兩本書，想了半個小時還是不知道買哪本，最後要回家了，我一本也沒買到。下次我會把兩個選擇的好處和壞處寫下來比一比，再給自己五分鐘，時間到就決定。',
        rubric: ['說出一次猶豫不決的經驗與結果', '提出幫自己做決定的方法', '方法具體可行'] }
    ],
    xq: [
      { id: 'x1', k: 'judge', d: 2, type: 'tf', q: '「面對要不要轉學，他首鼠兩端，想了一整個暑假還是拿不定主意。」這句話的「首鼠兩端」用得恰當。', a: true, why: '一直拿不定主意，用首鼠兩端恰當。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '小芬和小美吵架了，兩個人都來找阿珍評理。阿珍在小芬面前說：「你說得對。」轉頭在小美面前又說：「你也沒錯啦。」她怕得罪任何一個人，始終不肯說出自己真正的想法。後來兩個人和好了，一對質，反而都不太相信阿珍了。', q: '阿珍的做法，可以用哪個成語形容？', opts: ['首鼠兩端', '愛屋及烏', '後生可畏', '文不加點'], a: 0, why: '阿珍在兩邊之間搖擺、不肯表態，就像故事裡的韓安國，是首鼠兩端。' }
    ]
  },
  {
    id: 'cy097', lv: 4, word: '門可羅雀', zhuyin: 'ㄇㄣˊ ㄎㄜˇ ㄌㄨㄛˊ ㄑㄩㄝˋ', src: '《史記．汲鄭列傳》',
    quote: '及廢，門外可設雀羅',
    facts: ['語本《史記．汲鄭列傳》｜教育部《成語典》', '汲黯和鄭當時都當過高官，賓客眾多；兩人個性剛直，相繼失勢後，賓客也隨之散去｜教育部《成語典》典故說明', '翟公當廷尉時賓客擠滿門口，被罷官後門外冷清得可以張網捕雀；後來復官，賓客又想上門｜教育部《成語典》典故說明', '原本形容做官的人失勢後賓客稀少；後來也泛指一般來客稀少、門庭冷清｜教育部《成語典》釋義'],
    story: [
      '西漢的時候，有兩位大臣，一位叫汲黯，一位叫鄭當時。汲黯說話直來直往，敢當面指出皇帝的錯；鄭當時為人厚道，很喜歡結交朋友、推薦人才。',
      '他們當大官的時候，家門口每天都車水馬龍，來拜訪的客人一個接著一個。可是兩人的個性太過剛直，不太適合在官場裡打轉，後來都丟了官位。官位一沒有，客人也一下子不見了，門口變得冷冷清清。',
      '寫《史記》的司馬遷，寫到這兩個人時，忍不住感嘆，還講了另一個人的故事。',
      '有一位叫翟公的人，當過管理司法的大官「廷尉」。他當官的時候，來拜訪的人多到把門口擠得滿滿的。後來他被免了官，門外一下子空蕩蕩的，安靜到可以張開網子在門口抓麻雀。',
      '過了一段時間，翟公又被任命做官了。那些以前不見人影的客人，又爭著要上門拜訪。翟公看透了這些人，就在大門上寫了幾句話，大意是：一個人遇到生死、貧富、高低的變化時，才看得出朋友的交情是真是假。',
      '司馬遷說：像汲黯、鄭當時這樣賢能的人，也免不了遇到這種冷暖人情，真是令人感慨啊！',
      '後來，人們從「門外可設雀羅」這句話，變出了「門可羅雀」這個成語。「羅」原本是捕鳥的網子，這裡是張網捕捉的意思。它原本形容做官的人失勢以後，賓客稀少的冷清樣子；後來也用來形容一般的地方客人很少、門庭冷落。',
      '要注意：「門可羅雀」說的是「冷清、沒有人」，不是說門口有很多麻雀；它的反義成語是「門庭若市」。'
    ],
    mean: '門前冷清，空得可以張網捕麻雀。原本形容做官的人失勢後賓客稀少；後來也泛指一般來客稀少、門庭冷清。',
    usage: ['今天多用在形容店家、場所客人很少、冷冷清清。', '原本帶有「人情冷暖」的感嘆：有權有勢時大家都來，失勢就沒人來。', '它是說「冷清」，不是說麻雀很多；反義成語有「門庭若市」「車馬盈門」「賓客盈門」。'],
    misuse: ['「公園的大樹上住了好多麻雀，吱吱喳喳的，真是門可羅雀。」✗　門可羅雀是形容冷清、客人很少，不是說麻雀很多。', '「週年慶第一天，百貨公司門可羅雀，擠得走不動。」✗　擠得走不動是很熱鬧，應該說「門庭若市」。'],
    eg: ['那家餐廳換了老闆以後，菜變得不好吃，現在門可羅雀。', '颱風天的觀光夜市門可羅雀，只剩幾個攤位還亮著燈。'],
    syn: [], ant: ['門庭若市', '車馬盈門', '賓客盈門'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '翟公被免官以後，他家門口是什麼樣子？', opts: ['冷清得可以張網抓麻雀', '擠滿了來拜訪的客人', '停滿了大官的馬車', '掛滿了慶祝的燈籠'], a: 0, why: '第四段：「門外一下子空蕩蕩的，安靜到可以張開網子在門口抓麻雀。」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '翟公又當官以後，那些客人為什麼又爭著上門？', opts: ['翟公又有了官位和權力', '翟公家門口的麻雀變多了', '翟公寫信請他們來', '他們剛好路過翟公家'], a: 0, why: '第五段：翟公「又被任命做官了」，以前不見人影的客人才又上門，可見他們看重的是官位。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '把汲黯、鄭當時和翟公的故事合起來看，司馬遷想感嘆什麼？', opts: ['有權勢就來、失勢就走的人情', '當官的人都不喜歡交朋友', '麻雀喜歡住在大官家門口', '當官一定會被免官'], a: 0, why: '三個人都是當官時客人多、失勢就冷清，第六段司馬遷感嘆的是「冷暖人情」。' },
      { id: 'r4', p: 4, d: 3, type: 'open', q: '翟公在門上寫字，說遇到變化時才看得出真朋友。你覺得什麼樣的朋友才是真朋友？請用故事內容和自己的經驗說明。',
        ref: '我覺得真朋友是你不順利的時候還願意陪你的人。翟公有官位時客人很多，沒官位就沒人來，那些人只是看上他的權力。我上次生病請假一週，阿凱每天幫我抄聯絡簿、送作業來，我覺得他就是真朋友。',
        rubric: ['說出自己認為的真朋友是什麼樣子', '用故事內容當理由', '舉出自己的經驗'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「門可羅雀」的「羅」在這裡是什麼意思？', opts: ['張網捕捉', '排成一排', '很多很多', '繞來繞去'], a: 0, why: '「羅」是捕鳥的網子，這裡是張網捕捉。門可羅雀就是門口冷清得可以張網捕麻雀。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '老街上有一家開了四十年的照相館。以前每到畢業季，來拍畢業照的學生排到門外；現在大家都用手機拍照，照相館一整天常常沒有一個客人上門，老闆只好坐在櫃台後面看報紙，聽著外面的蟬聲。', q: '照相館現在的樣子，最適合用哪個成語形容？', opts: ['門可羅雀', '門庭若市', '愛屋及烏', '首鼠兩端'], a: 0, why: '一整天沒有客人上門，冷冷清清，就是門可羅雀。門庭若市是以前熱鬧的樣子，相反。' },
      { id: 'p3', k: 'judge', d: 2, type: 'tf', q: '「暑假的游泳池擠滿了人，每個水道都有人在游，真是門可羅雀。」這句話的「門可羅雀」用得恰當。', a: false, why: '擠滿了人是熱鬧，應該說門庭若市；門可羅雀是冷清。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈社區報〉巷口新開的早餐店，三明治好吃又便宜，每天早上客人都排到隔壁門口，老闆忙得連喝水的時間都沒有。可以說是門可羅雀。', q: '社區報的「門可羅雀」用得恰當嗎？', opts: ['不恰當，客人很多，應該說門庭若市', '恰當，因為早餐店的老闆非常忙', '恰當，因為客人排到了隔壁門口', '不恰當，因為早餐店沒有賣麻雀'], a: 0, why: '門可羅雀是冷清、客人少。早餐店客人多到排隊，應該用反義的門庭若市。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '老街上有些店家從熱鬧變得「門可羅雀」。如果你家附近有一家你喜歡、但客人越來越少的小店，你覺得可以怎麼幫助它？請提出至少兩個想法。',
        ref: '我家附近有一家賣手工麵包的小店，客人越來越少。我可以常常去買，也可以跟同學推薦。我還可以建議老闆在門口放一塊小黑板，寫上今天的新口味，讓路過的人知道這裡有好吃的麵包。',
        rubric: ['說出一家具體的小店或情境', '提出至少兩個幫助的想法', '想法合理可行'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '這家書店搬到巷子深處以後，路過的人變少了，平日常常＿＿＿＿。', opts: ['門可羅雀', '門庭若市', '後生可畏', '老生常談'], a: 0, why: '路過的人變少、平日冷清，用門可羅雀。門庭若市和「人變少」矛盾。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '記者：「這座新開的動物園，假日一天湧進三萬名遊客，停車場全滿。」\n主播：「看來這座動物園門可羅雀，非常受歡迎。」', q: '主播說的「門可羅雀」用得恰當。', a: false, why: '三萬名遊客是非常熱鬧，應該說門庭若市；門可羅雀是冷清、沒人來。' }
    ]
  },
  {
    id: 'cy100', lv: 4, word: '老生常談', zhuyin: 'ㄌㄠˇ ㄕㄥ ㄔㄤˊ ㄊㄢˊ', src: '《三國志．魏書．管輅傳》',
    quote: '此老生之常譚',
    facts: ['語本《三國志．魏書．管輅傳》；「談」在典源寫作「譚」，「譚」同「談」｜教育部《成語典》釋義', '管輅是三國魏國人，精通《周易》，常替人占卜｜教育部《成語典》典故說明', '吏部尚書何晏請管輅占卜，問能否位列三公，又問夢見青蠅的預兆；管輅以仁義之道和先聖的作為勸勉他｜教育部《成語典》典故說明', '在一旁的鄧颺認為這些都是老書生的老話｜教育部《成語典》典故說明'],
    story: [
      '三國時代的魏國，有一個人叫管輅。他精通一本叫《周易》的古書，很會替人占卜，大家都說他算得很準，所以名氣很大。',
      '有一天，朝廷裡的大官何晏請管輅到家裡來。何晏的地位已經很高了，可是他還不滿足。他問管輅：「請你替我算一算，我能不能當上三公這樣的大官？」',
      '何晏又說：「我最近一連好幾天，都夢見幾十隻青蠅停在我的鼻子上，怎麼趕都趕不走，這是什麼意思呢？」',
      '管輅沒有說一堆好聽的話。他認真的說：「從前輔佐國君的賢人，都是因為心地善良、謙虛待人，才得到大家的尊敬。現在您的地位很高，可是真心感念您的人少，害怕您的人多，這不是好事啊。」',
      '他接著說：「希望您學學古代的聖賢，多做合乎仁義的事，不合禮的事就不要做。這樣，三公的位子自然可以得到，那些青蠅也會飛走。」',
      '坐在一旁的鄧颺聽了，不以為然的說：「這些話不過是老書生說的老套話罷了，誰沒聽過？」',
      '鄧颺說的「老生之常譚」，後來就變成了「老生常談」。「老生」是老書生，「常談」是常說的話，用來比喻常常聽到、沒有新意的老話。',
      '可是讀了這個故事，你會發現：管輅說的雖然是老話，卻是很重要的道理。有些話之所以常常聽到，正是因為它很重要，只是很多人聽了，卻沒有放在心上。',
      '今天我們說一段話是「老生常談」，意思是它聽起來沒有新意；但是在用這個詞以前，也可以先想一想：這句老話，自己真的做到了嗎？'
    ],
    mean: '老書生常說的話。比喻時常聽到、沒有新意的老話。',
    usage: ['用在形容一再重複、大家都聽過、沒有新意的話，多帶有不耐煩的意思。', '它說的是「話很老套」，不是「老先生常常聊天」，也不是「老師常常說話」。', '近義成語有「老調重彈」「陳腔濫調」，反義成語有「別出心裁」「聞所未聞」。'],
    misuse: ['「公園裡幾位老爺爺每天坐在樹下老生常談，聊得很開心。」✗　老生常談是指聽過很多次、沒有新意的話，不是老人家常常聊天。'],
    eg: ['每次放假前都要提醒注意安全，雖然是老生常談，卻很重要。', '他的演講內容都是老生常談，台下的聽眾聽得直打哈欠。'],
    syn: ['老調重彈', '陳腔濫調', '千篇一律'], ant: ['別出心裁', '聞所未聞'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '何晏請管輅占卜，最想知道什麼？', opts: ['自己能不能當上三公', '明天洛陽會不會下雨', '青蠅喜歡吃什麼', '鄧颺是不是真心對他好'], a: 0, why: '第二段：何晏問「我能不能當上三公這樣的大官？」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '鄧颺說管輅的話是「老書生說的老套話」，表示鄧颺的態度是什麼？', opts: ['覺得沒有新意，不放在心上', '覺得非常有道理，很佩服', '覺得管輅說得太快聽不懂', '覺得何晏應該多睡一點'], a: 0, why: '第六段：鄧颺「不以為然」，還說「誰沒聽過」，可見他覺得這些話老套，不值得重視。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '把管輅的話和第八段合起來看，作者認為管輅的話怎麼樣？', opts: ['雖然是老話，卻是重要的道理', '是一些很新奇、很有趣的笑話', '完全沒有道理，不用放在心上', '是專門用來嚇人的話'], a: 0, why: '第八段：「管輅說的雖然是老話，卻是很重要的道理。」' },
      { id: 'r4', p: 4, d: 3, type: 'open', q: '很多重要的提醒（例如過馬路要看紅綠燈、要誠實）都是「老生常談」。你覺得為什麼常常聽到的話，大家反而容易不放在心上？要怎麼讓自己真的做到？請用故事說明。',
        ref: '因為聽太多次了，會覺得「我早就知道了」，就不認真聽，就像鄧颺覺得管輅的話很老套。可是知道不等於做到。我可以把重要的提醒變成小習慣，例如每次過馬路都在心裡數「停、看、聽」，讓自己真的做到。',
        rubric: ['說出常聽的話容易被忽略的原因', '用故事內容說明（例如鄧颺的態度）', '提出讓自己真的做到的方法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「老生常談」的意思是什麼？', opts: ['常聽到、沒新意的老話', '老先生常常一起聊天', '學生常常討論功課', '老朋友說的笑話'], a: 0, why: '老生常談是老書生常說的話，比喻常聽到、沒有新意的話，不是老人家聊天。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '社區的里長每年在中秋晚會上致詞，說的話幾乎都一樣：「感謝大家來參加，烤肉要注意安全，垃圾要記得帶走。」五年級的阿哲聽了五年，連里長下一句要說什麼都猜得出來，忍不住小聲跟同學說：「又是這幾句，我都會背了。」', q: '阿哲覺得里長的致詞，最適合用哪個成語形容？', opts: ['老生常談', '別出心裁', '文不加點', '後生可畏'], a: 0, why: '每年都說差不多的話，聽起來沒有新意，就是老生常談。別出心裁是有新意，相反。' },
      { id: 'p3', k: 'pair', d: 2, type: 'match', q: '這些成語跟「老生常談」是什麼關係？配起來。', pairs: [['老調重彈', '近義成語'], ['別出心裁', '反義成語'], ['門可羅雀', '意思無關']], why: '老調重彈是把舊的話再說一遍，相近；別出心裁是想出跟別人不同的新點子，相反；門可羅雀是冷清，無關。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈日記〉今天放學後，阿公和他的老同學在廟口下棋，兩個人一邊下棋一邊聊以前的事，聊了一整個下午，真是老生常談。', q: '日記裡的「老生常談」用得恰當嗎？', opts: ['不恰當，它是指老套的話，不是聊天', '恰當，因為阿公和老同學聊了很久', '恰當，因為他們聊的是以前的事', '不恰當，因為下棋時不能說話'], a: 0, why: '老生常談是常聽到、沒有新意的話，不是老人家聊天，這是望文生義的誤用。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '大人常說的「早點睡」「多喝水」「做事要專心」，聽起來像老生常談。選一句你常聽到的提醒，想想它為什麼重要，並說說你要怎麼真正做到。',
        ref: '我常聽到「早點睡」，以前覺得很煩。可是我發現只要睡太晚，第二天上課就會打瞌睡。我要真正做到，就要在九點半前把功課和明天的書包準備好，十點準時關燈。',
        rubric: ['選一句常聽到的提醒', '說明它為什麼重要', '提出真正做到的具體方法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '他每次上台都只會說「大家要團結合作」，這種＿＿＿＿，同學們早就聽膩了。', opts: ['老生常談', '別出心裁', '門可羅雀', '首鼠兩端'], a: 0, why: '一再重複、大家聽膩的話，是老生常談。別出心裁是有新意，和「聽膩了」矛盾。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '社區媽媽教室請來一位講師談「親子溝通」。講師講了兩個小時，內容都是「要多陪孩子」「要多聽孩子說話」這些大家早就聽過很多次的話，沒有提出任何新的方法或例子。下課時，好幾位家長都說：「這些我在網路上看過一百遍了。」', q: '這位講師的內容，可以用哪個成語形容？', opts: ['老生常談', '文不加點', '後生可畏', '門庭若市'], a: 0, why: '講的都是大家聽過很多次、沒有新意的話，是老生常談。' }
    ]
  }
]);
window.DATA_CY_READ = (window.DATA_CY_READ || []).concat([
  {
    id: 'cyr04', lv: 2, genre: '訪談', domain: ['藝術', '社會'], title: '屋頂上的龍：專訪剪黏林師傅',
    uses: ['cy031', 'cy032', 'cy034', 'cy039'],
    facts: ['訪談中的師傅、廟宇、班級都是虛構的｜虛構情境', '剪黏是把彩色瓷片剪成小片，黏在灰泥上做成人物、花鳥等裝飾，常見於台灣傳統廟宇的屋頂｜傳統工藝常識（作者整理）'],
    body: [
      '學校附近的福安宮正在整修屋頂，屋脊上有一條色彩鮮豔的龍，是用一片一片碎瓷片黏成的，這種工藝叫做「剪黏」。我們五年四班的校刊小記者，訪問了負責修復的林師傅。林師傅今年六十八歲，做剪黏已經五十年了。',
      { h: '剪了三年的碗片' },
      '記者：師傅，您是幾歲開始學剪黏的？',
      '林師傅：十八歲。我跟著師父當學徒，前三年幾乎都在剪碗片。把彩色的瓷碗用剪鉗剪成小片，剪成花瓣、剪成龍鱗，每天剪到手指起水泡。',
      '記者：剪了三年都不會膩嗎？',
      '林師傅：怎麼不會？我也想過放棄。可是師父說，剪黏就像磨杵成針，鐵棒要一點一點磨，手感也要一片一片剪出來，沒有捷徑。後來我真的發現，剪的片數多了，手就知道該怎麼下刀。',
      { h: '先在心裡畫好一條龍' },
      '記者：屋頂上那條龍好大，您是怎麼開始做的？',
      '林師傅：動手之前，我會先在紙上畫好整條龍的樣子，龍頭朝哪裡、身體怎麼彎、每一段用什麼顏色，都要先想清楚。心裡有了完整的龍，才算胸有成竹，上了屋頂才不會手忙腳亂。',
      '記者：有沒有遇過很難的情況？',
      '林師傅：有啊。我年輕時第一次自己接工作，照著書上的圖做，以為一定沒問題。結果屋頂是斜的，風又大，灰泥乾得特別快，書上的方法根本來不及用。那時候才知道，自己學的很多只是紙上談兵。後來師父來幫忙，他一看就知道該先做哪裡、灰泥要怎麼調，真是老馬識途。',
      { h: '手藝要有人傳下去' },
      '記者：現在願意學剪黏的年輕人多嗎？',
      '林師傅：不多。這門手藝要花很長的時間，賺的錢也不多。不過最近有幾位大學生來跟我學，還把作品拍下來放上網路，讓更多人認識剪黏。我很高興，手藝要有人學，才不會消失。',
      '記者：最後，您想對小朋友說什麼？',
      '林師傅：不管學什麼，都要多看、多練。下次經過廟口，抬頭看看屋頂，每一片瓷片都是一位師傅的耐心喔。'
    ],
    qs: [
      { id: 'q1', p: 1, d: 1, type: 'mc', q: '林師傅當學徒的前三年，幾乎都在做什麼？', opts: ['剪碗片和瓷片', '畫龍的設計圖', '在屋頂上黏龍', '把作品拍照上網'], a: 0, why: '「剪了三年的碗片」這一段：前三年幾乎都在剪碗片。' },
      { id: 'q2', p: 2, d: 2, type: 'mc', q: '師父說剪黏就像「磨杵成針」，是想告訴林師傅什麼？', opts: ['手感要靠長時間一片一片練出來', '剪黏一定要用磨過的鐵棒當工具', '剪黏的作品可以拿來縫衣服', '學剪黏只要練三年就能學會'], a: 0, why: '師父說「手感也要一片一片剪出來，沒有捷徑」，就像磨鐵棒成針要一點一點磨。' },
      { id: 'q3', p: 2, d: 2, type: 'mc', q: '林師傅年輕時照著書做卻失敗了，最主要的原因是什麼？', opts: ['真實的屋頂情況和書上不一樣', '他那時沒有買到顏色對的瓷片', '師父故意不教他真正的方法', '那天他生病了沒辦法做'], a: 0, why: '屋頂是斜的、風大、灰泥乾得快，「書上的方法根本來不及用」。' },
      { id: 'q4', p: 3, d: 2, type: 'match', q: '把訪談裡的事情和林師傅用的成語配起來。', pairs: [['三年天天剪碗片，練出手感', '磨杵成針'], ['先畫好整條龍再動手', '胸有成竹'], ['照書做，遇到斜屋頂就不會', '紙上談兵'], ['師父一看就知道怎麼做', '老馬識途']], why: '長時間累積＝磨杵成針；事前想清楚＝胸有成竹；只懂書上方法＝紙上談兵；有經驗的人帶路＝老馬識途。' },
      { id: 'q5', p: 4, d: 3, type: 'mc', q: '林師傅說「手藝要有人學，才不會消失」。根據訪談，下面哪一個做法最能幫助剪黏傳下去？', opts: ['讓更多人認識並願意學這門手藝', '把所有剪黏作品都收進倉庫保存', '只讓林師傅一個人繼續做下去', '把廟口的屋頂改成水泥的'], a: 0, why: '林師傅很高興大學生來學、還放上網路讓更多人認識，可見要有人認識、有人學，手藝才能傳下去。' },
      { id: 'q6', p: 4, d: 3, type: 'open', q: '林師傅說自己年輕時是「紙上談兵」，後來靠師父「老馬識途」才解決問題。你覺得學一門手藝，「讀書學方法」和「跟著有經驗的人做」哪一個比較重要？請用訪談內容說明。',
        ref: '我覺得兩個都要，但跟著有經驗的人做更重要。林師傅照書做，遇到斜屋頂和大風就不會了，是師父一看就知道怎麼調整。書可以讓人知道基本方法，可是真正遇到狀況時，需要有經驗的人帶，自己也要多練習。',
        rubric: ['表明自己的看法', '用訪談內容當證據（照書失敗、師父幫忙）', '說明兩者的關係或各自的作用'] }
    ]
  },
  {
    id: 'cyr07', lv: 3, genre: '說明文', domain: ['自然', '社會'], title: '颱風來之前：小晴家的防颱清單',
    uses: ['cy062', 'cy063', 'cy069', 'cy070'],
    facts: ['文中的家庭、人物都是虛構的｜虛構情境', '颱風常帶來強風豪雨，可能造成停電、停水、淹水；中央氣象署會先發布海上颱風警報，再視情況發布陸上颱風警報｜防災常識（作者整理）'],
    body: [
      { h: '為什麼要提早準備？' },
      '台灣每年夏天到秋天，常常有颱風來。颱風帶來強風和豪雨，可能吹倒大樹、造成停電停水，低窪的地方還可能淹水。中央氣象署通常會先發布海上颱風警報，颱風更靠近時再發布陸上颱風警報，兩次警報之間，就是做準備的好機會。古人說「未雨綢繆」，意思是下雨以前就先把門窗修補好；防颱也是一樣，越早準備越安心。',
      { h: '防颱準備清單' },
      '下面是五年七班的小晴和家人一起做的防颱紀錄。她把準備的事分成三類，還記下每一件事是在什麼時候完成的。',
      { table: { cap: '小晴家的防颱準備紀錄', head: ['類別', '要做的事', '完成時間'], rows: [
        ['家裡外面', '把陽台的盆栽、曬衣架搬進屋內', '海上警報發布後'],
        ['家裡外面', '清理排水孔的落葉，讓雨水流得出去', '海上警報發布後'],
        ['生活用品', '準備手電筒、備用電池和行動電源', '海上警報發布後'],
        ['生活用品', '準備三天份的飲用水和乾糧', '陸上警報發布後'],
        ['安全確認', '查好離家最近的避難處所', '陸上警報發布後'],
        ['安全確認', '把門窗關緊，遠離窗邊', '颱風來的那天晚上']
      ] } },
      { h: '去年學到的教訓' },
      '去年的颱風，小晴家沒有先清排水孔。颱風來的那天晚上，陽台積水越來越高，爸爸只能拿著小水桶一桶一桶往外舀，可是雨下得太大，這點力氣簡直是杯水車薪，水還是淹進了客廳。',
      '今年，爸爸在颱風還在海上時，就先把排水孔清乾淨，又把容易被吹走的東西搬進屋裡。媽媽說，這就像「曲突徙薪」的故事：在危險發生以前，先把可能出問題的地方處理好。',
      '小晴不知道避難處所在哪裡，就去問隔壁讀一年級的小弟弟，因為他們學校上星期才做過防災演練。小弟弟馬上帶她去看巷口的告示牌。媽媽笑著說：「你肯向比你小的人請教，這就是不恥下問。」',
      { h: '給你的提醒' },
      '防颱準備做得好，颱風來時就不必手忙腳亂。記得注意氣象署的最新消息，颱風天不要到河邊、海邊或山區，也不要因為好奇跑出門看風雨。'
    ],
    qs: [
      { id: 'q1', p: 1, d: 1, type: 'mc', q: '根據表格，小晴家在「陸上警報發布後」準備了哪一件事？', opts: ['三天份的飲用水和乾糧', '把陽台的盆栽搬進屋內', '清理排水孔裡的落葉', '把門窗關緊'], a: 0, why: '表格「生活用品」那一列：準備三天份的飲用水和乾糧，完成時間是陸上警報發布後。' },
      { id: 'q2', p: 1, d: 1, type: 'tf', q: '根據表格，小晴家把清理排水孔安排在颱風來的那天晚上才做。', a: false, why: '表格寫的是「海上警報發布後」就清理排水孔；颱風來的那天晚上做的是關緊門窗。' },
      { id: 'q3', p: 2, d: 2, type: 'mc', q: '去年小晴家為什麼會淹水？', opts: ['沒先清排水孔，雨水排不出去', '颱風把家裡的窗戶吹破了', '爸爸忘了把盆栽搬進來', '隔壁的水流到他們家'], a: 0, why: '「去年學到的教訓」第一段：沒有先清排水孔，陽台積水越來越高，最後淹進客廳。' },
      { id: 'q4', p: 3, d: 2, type: 'match', q: '把文章裡的事情和成語配起來。', pairs: [['用小水桶舀大量的積水', '杯水車薪'], ['颱風還在海上就先清排水孔', '曲突徙薪'], ['向一年級的小弟弟請教', '不恥下問']], why: '力量太小、問題太大＝杯水車薪；危險發生前先預防＝曲突徙薪；向年紀比自己小的人請教＝不恥下問。' },
      { id: 'q5', p: 3, d: 3, type: 'mc', q: '比較去年和今年，小晴家防颱的做法最大的不同是什麼？', opts: ['今年在危險發生以前就先處理', '今年買了更大的水桶來舀水', '今年全家搬到避難處所去住', '今年颱風比較小，不用準備'], a: 0, why: '去年是淹水了才舀水；今年颱風還在海上就先清排水孔、搬東西，是事先預防。' },
      { id: 'q6', p: 4, d: 3, type: 'open', q: '文章用了「未雨綢繆」「曲突徙薪」來說明防颱。請從表格選出你認為最重要的一項準備，說明為什麼它最重要；再想一想，你家還可以多做哪一件準備？',
        ref: '我覺得「清理排水孔」最重要，因為小晴家去年就是沒清排水孔才淹水，等水淹進來再舀就是杯水車薪了。我家附近有很多大樹，我覺得還可以先把車子停到離樹比較遠的地方，免得樹倒下來壓到。',
        rubric: ['從表格選出一項並說明理由', '理由能用到文章內容', '提出一項合理的額外準備'] }
    ]
  },
  {
    id: 'cyr10', lv: 4, genre: '多文本', domain: ['社會', '生活'], title: '老街要不要改造？',
    uses: ['cy091', 'cy093', 'cy097', 'cy099'],
    facts: ['文中的老街、店家、居民、學校和調查數字都是虛構的｜虛構情境'],
    body: [
      '青石老街有一百多年的歷史，街上有紅磚屋、老雜貨店和打鐵店。這幾年，老街的客人越來越少。鎮公所提出一個改造計畫：把老房子的外牆全部換成新的玻璃門面，再請連鎖商店進駐。下面是三份不同的意見。',
      { doc: '文本一：雜貨店老闆陳先生' },
      '我的雜貨店開了五十年。以前一到過年，店裡擠得走不動；現在平常日子常常門可羅雀，一整個下午只有兩三個客人。我贊成鎮公所的改造計畫。老房子的牆壁斑駁、屋頂會漏水，晚上整條街暗暗的，很多遊客走到一半就掉頭離開。換上明亮的玻璃門面，再請幾家連鎖商店進來，就能把人潮帶回來，大家的小店也會跟著熱鬧。如果什麼都不改，再過幾年，老街可能只剩下空房子了。',
      { doc: '文本二：住在老街的林奶奶' },
      '有人說這些老房子又舊又破，不值錢。可是我在這裡住了七十年，屋裡的木窗、門口的石階，都是我的回憶。也許別人會說我敝帚自珍，但這些老東西是別的地方買不到的。老街冷清，我也看在眼裡，把路面、路燈和公共廁所整理好，我都贊成。我擔心的是，為了配合連鎖商店的要求，硬把老房子改成不適合的樣子，那就像削足適履，鞋子是新的，腳卻受傷了。',
      { doc: '文本三：青石國小五年級的調查' },
      '我們五年級在老街訪問了一百位遊客，問了兩個問題：「最喜歡老街的什麼」（每個人可以選兩項），和「最希望老街改善什麼」（每個人選一項）。',
      { table: { cap: '表一　遊客最喜歡老街的地方（一百人，每人選兩項）', head: ['最喜歡的地方', '人數'], rows: [['紅磚老房子', '62'], ['傳統小吃', '55'], ['打鐵、做糕餅等老手藝', '41'], ['新的連鎖商店', '12'], ['其他', '30']] } },
      { table: { cap: '表二　遊客最希望老街改善的地方（一百人，每人選一項）', head: ['最希望改善的地方', '人數'], rows: [['增加停車位和乾淨的廁所', '36'], ['把店面整修得明亮、安全', '28'], ['多一些連鎖商店和新品牌', '16'], ['維持原樣，不用改', '20']] } },
      '調查的最後，我們訪問了一位二十五歲的大哥哥。他從外地回來，在老街開了一家「手作糕餅體驗教室」，教遊客用古早的木頭模具做糕餅。開幕不到半年，假日就要預約才排得到。打鐵店的老師傅說：「沒想到年輕人能把老手藝做出新花樣，真是後生可畏！」'
    ],
    qs: [
      { id: 'q1', p: 1, d: 1, type: 'mc', q: '根據文本三的表一，遊客最喜歡老街的哪一個地方？', opts: ['紅磚老房子', '傳統小吃', '老手藝', '新的連鎖商店'], a: 0, why: '表一中「紅磚老房子」有六十二人選，是最多的。' },
      { id: 'q7', p: 2, d: 2, type: 'mc', q: '陳先生為什麼贊成鎮公所的改造計畫？', opts: ['他認為明亮的新店面能帶回遊客', '他打算把雜貨店賣給連鎖商店', '他想把老街改建成百貨公司', '他覺得老房子住起來太擠了'], a: 0, why: '文本一：老房子斑駁漏水、街道暗，遊客走到一半就離開；換上明亮的門面、請連鎖商店進來，就能把人潮帶回來。其他三項文中都沒有說。' },
      { id: 'q3', p: 3, d: 2, type: 'mc', q: '林奶奶說的「削足適履」，在她的意見裡比喻什麼？', opts: ['為了配合商店，把老房子改成不適合的樣子', '為了讓遊客走路方便，把老街的路面重新鋪過', '買了一雙不合腳的新鞋子，結果把腳磨傷了', '把老房子的木窗都拆下來，賣給收藏的人'], a: 0, why: '林奶奶擔心「為了配合連鎖商店的要求，硬把老房子改成不適合的樣子」，就像為了穿新鞋而削腳。' },
      { id: 'q8', p: 3, d: 3, type: 'mc', q: '陳先生和林奶奶的看法，有哪一點是一樣的？', opts: ['都覺得老街冷清，需要整理', '都贊成請連鎖商店進駐', '都希望把老房子拆掉重蓋', '都認為老街完全不用改變'], a: 0, why: '陳先生說客人越來越少、贊成改造；林奶奶也說「老街冷清，我也看在眼裡」，贊成整理路面、路燈和廁所。兩人不同的是要不要換掉老房子的外牆、請連鎖商店進來。' },
      { id: 'q9', p: 4, d: 3, type: 'mc', q: '根據文本三的兩個表格，下面哪一個說法最合理？', opts: ['遊客喜歡老房子，也希望設施變好', '遊客最想要的是更多連鎖商店', '大部分遊客都認為老街不用改', '遊客最不喜歡的是傳統小吃'], a: 0, why: '表一最多人喜歡紅磚老房子（六十二人）；表二有三十六人希望增加停車位和廁所、二十八人希望店面明亮安全。選連鎖商店的只有十六人，選不用改的只有二十人，不是大部分；表格也沒有問遊客不喜歡什麼。' },
      { id: 'q6', p: 4, d: 3, type: 'open', q: '讀完三份意見，你贊成鎮公所的計畫、林奶奶的想法，還是有別的做法？請至少用到兩份文本的內容當理由，也回應一下和你想法不同的意見。',
        ref: '我贊成整修老街，但不要把老房子的外牆全部換掉。陳先生說得有道理，老街太暗、設施不好，表二也有三十六位遊客希望增加停車位和廁所；可是表一有六十二人最喜歡紅磚老房子，林奶奶也說這些老東西別的地方買不到。所以我建議先整理路燈、廁所和店面安全，保留紅磚牆，再像開糕餅教室的大哥哥一樣，用新方法介紹老手藝。',
        rubric: ['清楚說出自己贊成的改造方式', '至少用到兩份文本的內容當理由', '有回應和自己不同的意見'] }
    ]
  }
]);
